# Generated from tools/data/rulebooks/duck_racing.json; run tools/compile-rulebooks.rb.
module GameRoomGames
  class DuckRacing
    module GeneratedRulebook
      private

      def generated_rule_sections
        [
          rule_section(:aim, GameRoomRules.translate("The aim of the game"),
            GameRoomRules.translate("Duck Racing is a game for two to eight players. Race around Peaceful Pond, use cards to help your duck or hold up your rivals, and compete for feathers in challenges. The first duck to complete the agreed number of laps wins."),
            GameRoomRules.translate("The track has 30 squares. Each player starts on square 1 with three cards and six feathers per planned lap. The default race lasts three laps, so you start with 18 feathers."),
            GameRoomRules.translate("On your final lap, crossing the finish line is enough to win, including when a card moves you across it.")),
          rule_section(:turn, GameRoomRules.translate("Your turn"),
            GameRoomRules.translate("You may play one card before rolling on your turn. Browse your hand with the arrow keys and press D to hear a card's effect and feather cost. Press Enter to play it. If you need to choose a player, use the arrows and confirm with Enter."),
            GameRoomRules.translate("Press Space to roll, then move forward by the number shown. You can also select the roll at the bottom of your card list and press Enter. An ordinary die has results from one to six."),
            GameRoomRules.translate("Resolve what happens on your landing square before the next player takes a turn. If a card or move starts a challenge, finish it before continuing."),
            GameRoomRules.translate("- C checks your position, feathers and active effects."),
            GameRoomRules.translate("- S reads everyone's race status."),
            GameRoomRules.translate("- T tells you whose turn it is.")),
          rule_section(:track, GameRoomRules.translate("Squares and encounters"),
            GameRoomRules.translate("Squares can give you cards or feathers, move your duck, make you miss turns or ask a question. Press V to explore the track and hear each square's description, the ducks there and any card left on it."),
            GameRoomRules.translate("When you land, the square acts first, then its card, then an encounter with another duck. If the square or card moves you again, continue resolving events at the new square."),
            GameRoomRules.translate("Landing with another duck starts a random duel. If several are there, you face the most recent arrival who is not frozen. You can meet even when you are on different laps."),
            GameRoomRules.translate("Moving backwards can take you into an earlier lap, but only as far as the start of the race. For example, one step back from square 1 of lap 2 takes you to square 30 of lap 1.")),
          rule_section(:cards, GameRoomRules.translate("Playing cards"),
            GameRoomRules.translate("Cards help you race or hinder your opponents. Some cost feathers, and you need enough to pay the full cost before playing them. You can hold as many cards as you collect."),
            GameRoomRules.translate("- Cards played on a duck act immediately. They can move it, give or take feathers, make it miss turns or change its die."),
            GameRoomRules.translate("- Cards left on a square wait for the next duck to land there, then disappear after taking effect. Your own duck can trigger them too. Feather-stealing cards are the exception: they leave their owner alone and keep waiting. Each square holds one card."),
            GameRoomRules.translate("- Other cards let you take cards from opponents or exchange whole hands."),
            GameRoomRules.translate("- Challenge starts a duel with a chosen opponent. Super challenge involves all unfrozen ducks. Curiosity asks everyone a quiz question."),
            GameRoomRules.translate("A die-changing card replaces the previous change and also applies in dice challenges. Only rolls made in the race use up its remaining rolls.")),
          rule_section(:feathers, GameRoomRules.translate("Feathers and freezing"),
            GameRoomRules.translate("You spend feathers on cards and win or lose them in challenges. When you run out, your duck freezes. You keep your cards but miss between one and four of your turns."),
            GameRoomRules.translate("The further ahead of the last duck you are, the longer you stay frozen. The distance includes whole laps:"),
            GameRoomRules.translate("- Up to 9 squares ahead: one turn."),
            GameRoomRules.translate("- 10\u201319 squares ahead: two turns."),
            GameRoomRules.translate("- 20\u201329 squares ahead: three turns."),
            GameRoomRules.translate("- At least 30 squares ahead: four turns."),
            GameRoomRules.translate("You receive five feathers when you thaw. If another effect also makes you miss turns, both waits count down together."),
            GameRoomRules.translate("If a missed-turn effect starts before you roll, the current turn counts. If it starts after your roll, count from your next turn.")),
          rule_section(:challenge_rules, GameRoomRules.translate("Challenges"),
            GameRoomRules.translate("The race pauses while you play a challenge. Some challenges are for two players; others can involve a group. In turn-based challenges, the starting player is chosen at random."),
            GameRoomRules.translate("For speed challenges, wait for the countdown to finish before answering. Press P to hear the task again, including while typing a number."),
            GameRoomRules.translate("The winner takes feathers from each loser at the challenge's stated rate. If players tie for first place, no feathers change hands. If you owe more than you have, you give up your remaining feathers.")),
          rule_section(:rock_paper_scissors, GameRoomRules.translate("Rock, paper, scissors"),
            GameRoomRules.translate("Two players choose rock, paper or scissors with the arrow keys and confirm with Enter. You have 15 seconds."),
            GameRoomRules.translate("Rock beats scissors, scissors beat paper, and paper beats rock. The winner takes three feathers. Matching choices tie. If only one player answers, that player wins.")),
          rule_section(:dice_duel, GameRoomRules.translate("Dice duel"),
            GameRoomRules.translate("Take turns rolling once each. Press Enter on your turn; if ten seconds pass, the game rolls for you."),
            GameRoomRules.translate("You use your current race die, including any card affecting it. The highest roll wins. Each opponent pays the winner the difference between their rolls in feathers.")),
          rule_section(:blackjack, GameRoomRules.translate("Twenty-one"),
            GameRoomRules.translate("Start with two cards and try to get as close to 21 as possible without going over. Each player has a separate 52-card deck."),
            GameRoomRules.translate("- Cards from 2 to 10 are worth their numbers."),
            GameRoomRules.translate("- Jacks, queens and kings are worth ten."),
            GameRoomRules.translate("- An ace is worth eleven unless that would take you over 21, in which case it is worth one. Its value then stays fixed."),
            GameRoomRules.translate("On your turn, press Space to draw or Enter to stand. Reaching or exceeding 21 also ends your turn, and the next player begins. You have 30 seconds for each decision; running out of time leaves you with your current total."),
            GameRoomRules.translate("The highest total of 21 or less wins. Each loser pays the difference between their total and the winner's in feathers. Going over 21 also costs one extra feather for each point over, paid to the game."),
            GameRoomRules.translate("For example, with totals of 20 and 24, the loser gives the winner four feathers and loses three more for going over 21. If everyone goes over, only the extra penalties apply.")),
          rule_section(:risky_dice, GameRoomRules.translate("Risky dice"),
            GameRoomRules.translate("Roll two dice and keep adding the results. The highest total of 25 or less wins."),
            GameRoomRules.translate("Press Enter to roll, then Enter again whenever you want another roll. To stop, select Save result with Down arrow and confirm with Enter. The next player then begins. A total of 25 or more ends your attempt automatically."),
            GameRoomRules.translate("You have 30 seconds for each decision. When time runs out, your total is saved; if you have not rolled yet, the game rolls once first. A card changing your race die applies to both dice."),
            GameRoomRules.translate("Each loser pays the winner the difference between their totals in feathers. Every point over 25 costs another feather, paid to the game. With 24 against 28, that means four feathers to the winner and three extra lost. If everyone goes over, only these penalties apply.")),
          rule_section(:guess_number, GameRoomRules.translate("Guess the number"),
            GameRoomRules.translate("Find the hidden number from 1 to 999. You are told how many digits it has. Type your guesses; after each one, you learn whether the answer is higher or lower. You have ten guesses and two minutes."),
            GameRoomRules.translate("Your closest guess counts. Whoever gets closest wins; if two players are equally close to the target, the challenge is a draw."),
            GameRoomRules.translate("The winner takes up to five feathers from each opponent. The amount depends on how much closer the winner was. For example, if the target is 47, guesses of 46 and 35 give an advantage of 11."),
            GameRoomRules.translate("- One-digit target: an advantage of 1 costs one feather; 2\u20133 costs two; 4 costs three; 5\u20136 costs four; 7 or more costs five."),
            GameRoomRules.translate("- Two-digit target: one feather for each started group of 10 in the advantage, up to five feathers."),
            GameRoomRules.translate("- Three-digit target: one feather for each started group of 100 in the advantage, up to five feathers."),
            GameRoomRules.translate("If you do not submit a guess, you give the winner five feathers. You can only lose feathers you have.")),
          rule_section(:copy_number, GameRoomRules.translate("Copy the number"),
            GameRoomRules.translate("Copy the three-digit number as quickly as you can. You have three attempts and 15 seconds. The first correct answer wins four feathers from each opponent.")),
          rule_section(:arithmetic, GameRoomRules.translate("Mental arithmetic"),
            GameRoomRules.translate("Work out and type the answer to an addition, subtraction, multiplication or division. You have three attempts and 20 seconds. The first correct answer wins four feathers from each opponent.")),
          rule_section(:race_question, GameRoomRules.translate("Question about the race"),
            GameRoomRules.translate("Type the answer to a question about the race: a player's square, lap, feathers or number of cards. You can check these details with C and S."),
            GameRoomRules.translate("You have two attempts and 20 seconds. The first correct answer wins four feathers from each opponent.")),
          rule_section(:numbered_balls, GameRoomRules.translate("Numbered balls"),
            GameRoomRules.translate("Two players take turns collecting balls from a row of twelve. The values can be positive or negative. Aim to finish with a higher total than your opponent."),
            GameRoomRules.translate("Browse the row with the arrow keys. Press 1, 2 or 3 to take that many balls from the front. You have one minute to decide; when it runs out, you take one ball."),
            GameRoomRules.translate("Once the row is empty, the higher total wins. The winner takes feathers equal to the difference, up to ten.")),
          rule_section(:count_ducks, GameRoomRules.translate("Count the ducks"),
            GameRoomRules.translate("Count the quacks, then type your answer after the countdown. There are between five and fifteen. Press F5 if you want to hear them again."),
            GameRoomRules.translate("You have two attempts and 20 seconds to answer. The first correct answer wins four feathers from each opponent.")),
          rule_section(:rhythm, GameRoomRules.translate("Repeat the rhythm"),
            GameRoomRules.translate("Repeat a drum pattern with F and J. Try both sounds, then press Enter or Space to start your own attempt. You hear a pattern of six to ten beats."),
            GameRoomRules.translate("After listening, press Enter and play the pattern. You have 15 seconds to begin, and can hear it once more with F5 before starting. You get one attempt; a three-second gap between key presses ends it."),
            GameRoomRules.translate("Half your score comes from the order of the sounds, and half from the gaps between them. The most accurate performance wins. Each ten percentage points of advantage, rounded up, earns one feather from that opponent.")),
          rule_section(:sound_order, GameRoomRules.translate("Order the sounds"),
            GameRoomRules.translate("Arrange a scale from the lowest note to the highest. Begin after the countdown. Keys 1 to 8 play the notes at those positions."),
            GameRoomRules.translate("To swap two notes, press Shift with the first position's digit, then Shift with the second. You hear both notes after the swap."),
            GameRoomRules.translate("You have 45 seconds. The first complete scale wins. Each opponent pays one feather per note still out of place, up to five. If nobody finishes, there is no winner.")),
          rule_section(:simon, GameRoomRules.translate("Simon"),
            GameRoomRules.translate("Remember a growing tune and repeat it with keys 1 to 5. Key 1 plays the lowest tone and 5 the highest. Try the tones before starting, then press Enter or Space when ready."),
            GameRoomRules.translate("Your attempt starts with a single note, without waiting for the other players. Each correct repetition adds one note to the tune and makes it a little faster. Wait until playback ends before repeating it."),
            GameRoomRules.translate("Keep going until you make a mistake or go five seconds without a key press while answering. Everyone finishes their own attempt. Your longest complete tune is your score; the winner takes one feather from each opponent for every note of advantage.")),
          rule_section(:sound_memory, GameRoomRules.translate("Sound pairs"),
            GameRoomRules.translate("Find more pairs than your opponent. Ten sounds, arranged in five pairs, are hidden under the number keys from 1 through 0. Both players press Enter when ready."),
            GameRoomRules.translate("Take turns uncovering two positions by pressing their digits. Listen to your opponent's choices too and remember where the sounds are. A matching pair is removed and scores a point; a mismatch is hidden again."),
            GameRoomRules.translate("You have 15 seconds per turn. The challenge ends when all pairs are found or after 90 seconds. The winner takes feathers equal to the difference in pairs found.")),
          rule_section(:hit_duck, GameRoomRules.translate("Hit the duck"),
            GameRoomRules.translate("Listen for the quack and press its position on keys 1 to 9. Key 1 is far left, 5 is the centre and 9 is far right."),
            GameRoomRules.translate("Try all the positions, then press Enter or Space to start your own attempt. Five targets appear in turn, with three seconds to answer each."),
            GameRoomRules.translate("After each shot, you hear a short rating before the next duck appears."),
            GameRoomRules.translate("Your score depends on how close you get:"),
            GameRoomRules.translate("- Exact hit: 100%."),
            GameRoomRules.translate("- One position away: 75%."),
            GameRoomRules.translate("- Two positions away: 50%."),
            GameRoomRules.translate("- Three positions away: 25%."),
            GameRoomRules.translate("- Other shots: zero."),
            GameRoomRules.translate("The highest average across the five shots wins. Each ten percentage points of advantage, rounded up, earns one feather from that opponent.")),
          rule_section(:quiz, GameRoomRules.translate("Quiz question"),
            GameRoomRules.translate("Answer a question by pressing 1 to 4 for one of the four choices. You can also select with the arrows and confirm with Enter. You have 20 seconds."),
            GameRoomRules.translate("Everyone who answers correctly receives four feathers from the game. Results are revealed once everyone has answered or time runs out."),
            GameRoomRules.translate("A duel question is for its participants. A question from a square or Curiosity is for everyone, including frozen ducks.")),
          rule_section(:audio_ball, GameRoomRules.translate("One point in Audio Ball"),
            GameRoomRules.translate("Play one point at Normal difficulty. The first server is chosen at random, and the winner takes five feathers from the opponent."),
            GameRoomRules.translate("Before starting, try the three ball sounds:"),
            GameRoomRules.translate("- W or Up arrow: the first type."),
            GameRoomRules.translate("- D or Left arrow: the second type."),
            GameRoomRules.translate("- S or Down arrow: the third type."),
            GameRoomRules.translate("Both players press Enter or Space when ready. When you have the ball, press A or Right arrow to prepare, then one of the three shot keys to send it."),
            GameRoomRules.translate("After each opponent's shot, recognise the ball sound and press the matching defence key. A successful defence lets you prepare your next shot. Each return makes the ball faster.")),
          rule_section(:axel_pong, GameRoomRules.translate("One point in Axel Pong"),
            GameRoomRules.translate("Play one singles point in Classic mode at Normal speed. The first server is chosen at random. The winner takes five feathers from the opponent."),
            GameRoomRules.translate("Press Enter when you are ready. The point starts once both players have confirmed."),
            GameRoomRules.translate("Move your paddle with Left and Right arrow. Serve with Up arrow or Space. When the ball returns, move into its path and press the same key when it comes within reach."),
            GameRoomRules.translate("If automatic hitting is enabled in your settings, positioning the paddle is enough to defend. You still serve manually.")),
          rule_section(:settings, GameRoomRules.translate("Choosing race settings"),
            GameRoomRules.translate("The host chooses these settings before the race:"),
            GameRoomRules.translate("- Laps: one to ten, with three as the default."),
            GameRoomRules.translate("- Challenges: tick the ones you want to include. All are enabled by default. Keep at least one for duels and one for groups."),
            GameRoomRules.translate("- Questions: choose the language and question sets. The general set is selected by default. Each selected set has an equal chance of being drawn, for all questions in the race.")),
          rule_section(:interruptions, GameRoomRules.translate("Saving and interrupted challenges"),
            GameRoomRules.translate("You can save the race between turns, once the challenge and any other events from the move have finished."),
            GameRoomRules.translate("If a challenge participant leaves the table or is replaced, the challenge is cancelled without anyone losing feathers.")),
          rule_section(:question_reports, GameRoomRules.translate("Reporting questions"),
            GameRoomRules.translate("Ctrl+B marks the current question for reporting, and Ctrl+Shift+B marks the previous one. This works for questions from squares, cards and challenges. After leaving the table, choose Yes when asked whether you want to report them. Describe the problem and press Send. The form shows the question, its choices and the answer marked as correct in the set.")),
          rule_section(:controls, GameRoomRules.translate("Race shortcuts"),
            GameRoomRules.translate("Arrow keys: choose a card or the roll at the end of the list."),
            GameRoomRules.translate("Enter: play the selected card or roll."),
            GameRoomRules.translate("Space: roll the die."),
            GameRoomRules.translate("D: describe the selected card."),
            GameRoomRules.translate("C: your position, feathers and active effects."),
            GameRoomRules.translate("S: everyone's race status."),
            GameRoomRules.translate("T: current turn or challenge."),
            GameRoomRules.translate("V: explore the track, starting at your current square."),
            GameRoomRules.translate("P: repeat the challenge instructions."),
            GameRoomRules.translate("Ctrl+B: mark the current question for reporting."),
            GameRoomRules.translate("Ctrl+Shift+B: mark the previous question for reporting."))
        ]
      end

      def localized_rule_sections
        case GameRoomLocalization.primary_language
        when "cs"
          [
            rule_section(:aim, "C\u00EDl hry",
              "Z\u00E1vody kachen jsou pro dva a\u017E osm hr\u00E1\u010D\u016F. Ob\u00EDhej se svou kachnou Klidn\u00FD rybn\u00EDk, pom\u00E1hej si kartami a soupe\u0159 s ostatn\u00EDmi o pe\u0159\u00ED ve v\u00FDzv\u00E1ch. Vyhraje ten, kdo jako prvn\u00ED dokon\u010D\u00ED ur\u010Den\u00FD po\u010Det kol.",
              "Okruh m\u00E1 30 pol\u00ED. Ka\u017Ed\u00FD za\u010D\u00EDn\u00E1 na poli 1 se t\u0159emi kartami a \u0161esti p\u00EDrky za ka\u017Ed\u00E9 pl\u00E1novan\u00E9 kolo. Ve v\u00FDchoz\u00EDm z\u00E1vod\u011B na t\u0159i kola tedy dostane\u0161 18 p\u00EDrek.",
              "V posledn\u00EDm kole sta\u010D\u00ED p\u0159ekro\u010Dit c\u00EDlovou \u010D\u00E1ru. Vyhr\u00E1t m\u016F\u017Ee\u0161 i posunem pomoc\u00ED karty."),
            rule_section(:turn, "Pr\u016Fb\u011Bh tahu",
              "P\u0159ed hodem m\u016F\u017Ee\u0161 ve sv\u00E9m tahu zahr\u00E1t jednu kartu. Vyber ji \u0161ipkami; kl\u00E1vesou D si p\u0159e\u010Dte\u0161 jej\u00ED \u00FA\u010Dinek a cenu v p\u00EDrk\u00E1ch. Enterem ji zahraje\u0161. Pokud m\u00E1\u0161 ur\u010Dit hr\u00E1\u010De, vyber ho \u0161ipkami a potvr\u010F Enterem.",
              "Mezern\u00EDkem hod\u00ED\u0161 kostkou a posune\u0161 se o hozen\u00FD po\u010Det pol\u00ED. Hod m\u016F\u017Ee\u0161 vybrat tak\u00E9 Enterem na konci seznamu pod kartami. B\u011B\u017En\u00E1 kostka d\u00E1v\u00E1 v\u00FDsledky od jedn\u00E9 do \u0161esti.",
              "Po pohybu se vyhodnot\u00ED ud\u00E1losti na poli, kde jsi zastavil. Potom hraje dal\u0161\u00ED hr\u00E1\u010D. Vyvol\u00E1-li karta nebo pohyb v\u00FDzvu, nejprve ji dokon\u010D\u00EDte.",
              "- C p\u0159ipomene tvoji pozici, pe\u0159\u00ED a \u00FA\u010Dinky, kter\u00E9 na tebe p\u016Fsob\u00ED.",
              "- S p\u0159e\u010Dte stav v\u0161ech hr\u00E1\u010D\u016F.",
              "- T ozn\u00E1m\u00ED, kdo je na tahu."),
            rule_section(:track, "Pole a setk\u00E1n\u00ED",
              "Na pol\u00EDch m\u016F\u017Ee\u0161 z\u00EDskat karty a pe\u0159\u00ED, posunout se jinam, vynechat tahy nebo dostat ot\u00E1zku. P\u0159ehled okruhu otev\u0159e\u0161 kl\u00E1vesou V. U ka\u017Ed\u00E9ho pole najde\u0161 popis, p\u0159\u00EDtomn\u00E9 kachny a p\u0159\u00EDpadnou odlo\u017Eenou kartu.",
              "Po zastaven\u00ED nejprve p\u016Fsob\u00ED pole, pak karta a nakonec setk\u00E1n\u00ED s jinou kachnou. Pokud t\u011B pole nebo karta p\u0159esune jinam, dal\u0161\u00ED ud\u00E1losti se odehraj\u00ED na nov\u00E9m m\u00EDst\u011B.",
              "Setk\u00E1n\u00ED s jinou kachnou vyvol\u00E1 n\u00E1hodn\u00FD souboj. Je-li jich na poli v\u00EDc, utk\u00E1\u0161 se s posledn\u00ED p\u0159\u00EDchoz\u00ED kachnou, kter\u00E1 nen\u00ED zmrzl\u00E1. Nez\u00E1le\u017E\u00ED na tom, ve kter\u00E9m kole z\u00E1vodu pr\u00E1v\u011B jste.",
              "Pohyb zp\u011Bt t\u011B m\u016F\u017Ee vr\u00E1tit do d\u0159\u00EDv\u011Bj\u0161\u00EDho kola, nejd\u00E1l v\u0161ak na za\u010D\u00E1tek z\u00E1vodu. Nap\u0159\u00EDklad z pole 1 druh\u00E9ho kola vede jeden krok zp\u011Bt na pole 30 prvn\u00EDho kola."),
            rule_section(:cards, "Karty",
              "Karty ti pom\u00E1haj\u00ED v z\u00E1vod\u011B nebo zt\u011B\u017Euj\u00ED cestu soupe\u0159\u016Fm. N\u011Bkter\u00E9 stoj\u00ED pe\u0159\u00ED; p\u0159ed zahr\u00E1n\u00EDm mus\u00ED\u0161 m\u00EDt dost na celou cenu. Po\u010Det karet v ruce nen\u00ED omezen.",
              "- Karty zahran\u00E9 na kachnu p\u016Fsob\u00ED hned. Mohou ji posunout, p\u0159idat \u010Di ubrat pe\u0159\u00ED, zastavit na n\u011Bkolik tah\u016F nebo zm\u011Bnit jej\u00ED kostku.",
              "- Karta odlo\u017Een\u00E1 na poli \u010Dek\u00E1 na p\u0159\u00ED\u0161t\u00ED kachnu a po pou\u017Eit\u00ED zmiz\u00ED. M\u016F\u017Ee\u0161 narazit i na vlastn\u00ED kartu. V\u00FDjimkou jsou karty kradouc\u00ED pe\u0159\u00ED: majiteli neubl\u00ED\u017E\u00ED a \u010Dekaj\u00ED d\u00E1l. Na jednom poli m\u016F\u017Ee le\u017Eet jedna karta.",
              "- Dal\u0161\u00ED karty umo\u017E\u0148uj\u00ED vz\u00EDt kartu soupe\u0159i nebo si s hr\u00E1\u010Di vym\u011Bnit v\u0161echny karty.",
              "- V\u00FDzva zah\u00E1j\u00ED souboj s vybran\u00FDm hr\u00E1\u010Dem. Superv\u00FDzva zapoj\u00ED v\u0161echny nezmrzl\u00E9 kachny. Zv\u011Bdavost polo\u017E\u00ED kv\u00EDzovou ot\u00E1zku v\u0161em.",
              "Nov\u00E1 zm\u011Bna kostky nahrad\u00ED p\u0159edchoz\u00ED a plat\u00ED tak\u00E9 ve v\u00FDzv\u00E1ch s kostkami. Po\u010Det zb\u00FDvaj\u00EDc\u00EDch hod\u016F se sni\u017Euje jen p\u0159i hodech v z\u00E1vod\u011B."),
            rule_section(:feathers, "Pe\u0159\u00ED a zmrznut\u00ED",
              "Pe\u0159\u00EDm plat\u00ED\u0161 za karty a vyhr\u00E1v\u00E1\u0161 \u010Di prohr\u00E1v\u00E1\u0161 ho ve v\u00FDzv\u00E1ch. Bez pe\u0159\u00ED kachna zmrzne. Karty ti z\u016Fstanou, ale vynech\u00E1\u0161 jeden a\u017E \u010Dty\u0159i vlastn\u00ED tahy.",
              "\u010C\u00EDm d\u00E1l jsi p\u0159ed posledn\u00ED kachnou, t\u00EDm d\u00E9le zmrznut\u00ED trv\u00E1. Do vzd\u00E1lenosti se po\u010D\u00EDtaj\u00ED i cel\u00E1 kola:",
              "- N\u00E1skok do 9 pol\u00ED: jeden tah.",
              "- N\u00E1skok 10\u201319 pol\u00ED: dva tahy.",
              "- N\u00E1skok 20\u201329 pol\u00ED: t\u0159i tahy.",
              "- N\u00E1skok alespo\u0148 30 pol\u00ED: \u010Dty\u0159i tahy.",
              "Po rozmrznut\u00ED dostane\u0161 p\u011Bt p\u00EDrek. Pokud vynech\u00E1v\u00E1\u0161 tahy tak\u00E9 z jin\u00E9ho d\u016Fvodu, ob\u011B p\u0159est\u00E1vky se odpo\u010D\u00EDt\u00E1vaj\u00ED sou\u010Dasn\u011B.",
              "Za\u010Dne-li p\u0159est\u00E1vka p\u0159ed tv\u00FDm hodem, po\u010D\u00EDt\u00E1 se u\u017E sou\u010Dasn\u00FD tah. Po hodu za\u010Dne a\u017E tv\u00FDm p\u0159\u00ED\u0161t\u00EDm tahem."),
            rule_section(:challenge_rules, "V\u00FDzvy",
              "Po dobu v\u00FDzvy se z\u00E1vod p\u0159eru\u0161\u00ED. N\u011Bkter\u00E9 \u00FAkoly jsou pro dva hr\u00E1\u010De, jin\u00E9 i pro v\u011Bt\u0161\u00ED skupinu. Ve v\u00FDzv\u00E1ch na tahy se losuje, kdo za\u010Dne.",
              "V rychlostn\u00EDch \u00FAkolech po\u010Dkej s odpov\u011Bd\u00ED na konec odpo\u010D\u00EDt\u00E1v\u00E1n\u00ED. Kl\u00E1vesa P zopakuje zad\u00E1n\u00ED a funguje i p\u0159i psan\u00ED \u010D\u00EDsla.",
              "V\u00EDt\u011Bz bere pe\u0159\u00ED od ka\u017Ed\u00E9ho pora\u017Een\u00E9ho podle pravidel dan\u00E9 v\u00FDzvy. P\u0159i shod\u011B na prvn\u00EDm m\u00EDst\u011B si pe\u0159\u00ED nikdo nep\u0159ed\u00E1v\u00E1. Nem\u00E1\u0161-li dost na zaplacen\u00ED, odevzd\u00E1\u0161 v\u0161echno, co ti zb\u00FDv\u00E1."),
            rule_section(:rock_paper_scissors, "K\u00E1men, n\u016F\u017Eky, pap\u00EDr",
              "V souboji pro dva vyber \u0161ipkami k\u00E1men, pap\u00EDr nebo n\u016F\u017Eky a potvr\u010F Enterem. M\u00E1\u0161 15 sekund.",
              "K\u00E1men por\u00E1\u017E\u00ED n\u016F\u017Eky, n\u016F\u017Eky pap\u00EDr a pap\u00EDr k\u00E1men. V\u00EDt\u011Bz bere t\u0159i p\u00EDrka. Stejn\u00E9 volby znamenaj\u00ED rem\u00EDzu. Pokud odpov\u00ED jen jeden hr\u00E1\u010D, vyhr\u00E1v\u00E1."),
            rule_section(:dice_duel, "Souboj v hodu kostkou",
              "H\u00E1z\u00EDte po \u0159ad\u011B, ka\u017Ed\u00FD jednou. Ve sv\u00E9m tahu stiskni Enter. M\u00E1\u0161 deset sekund; potom hod\u00ED hra za tebe.",
              "Pou\u017E\u00EDv\u00E1\u0161 svou kostku ze z\u00E1vodu i s \u00FA\u010Dinkem karty, kter\u00E1 ji zm\u011Bnila. Nejvy\u0161\u0161\u00ED hod vyhr\u00E1v\u00E1. Ka\u017Ed\u00FD soupe\u0159 odevzd\u00E1 v\u00EDt\u011Bzi tolik p\u00EDrek, kolik \u010Din\u00ED rozd\u00EDl jejich hod\u016F."),
            rule_section(:blackjack, "Jednadvacet",
              "Dostane\u0161 dv\u011B karty a sna\u017E\u00ED\u0161 se jejich sou\u010Dtem p\u0159ibl\u00ED\u017Eit k 21, ale nep\u0159ekro\u010Dit ho. Ka\u017Ed\u00FD hraje s vlastn\u00EDm bal\u00ED\u010Dkem 52 karet.",
              "- Karty od 2 do 10 maj\u00ED hodnotu uveden\u00E9ho \u010D\u00EDsla.",
              "- Kluk, d\u00E1ma a kr\u00E1l maj\u00ED hodnotu deset.",
              "- Eso dostane hodnotu jeden\u00E1ct, pokud t\u00EDm sou\u010Det nep\u0159ekro\u010D\u00ED 21; jinak m\u00E1 hodnotu jedna. Ta u\u017E z\u016Fst\u00E1v\u00E1 stejn\u00E1.",
              "Ve sv\u00E9m tahu dob\u00EDrej mezern\u00EDkem, nebo dob\u00EDr\u00E1n\u00ED ukon\u010Di Enterem. Tah kon\u010D\u00ED tak\u00E9 p\u0159i sou\u010Dtu 21 nebo vy\u0161\u0161\u00EDm. Pak za\u010Dne dal\u0161\u00ED hr\u00E1\u010D. Na ka\u017Ed\u00E9 rozhodnut\u00ED m\u00E1\u0161 30 sekund; po jejich uplynut\u00ED si ponech\u00E1\u0161 sou\u010Dasn\u00FD sou\u010Det.",
              "Vyhr\u00E1v\u00E1 nejvy\u0161\u0161\u00ED sou\u010Det do 21. Ka\u017Ed\u00FD pora\u017Een\u00FD zaplat\u00ED v\u00EDt\u011Bzi rozd\u00EDl v\u00FDsledk\u016F v p\u00EDrk\u00E1ch. Za ka\u017Ed\u00FD bod nad 21 nav\u00EDc ztrat\u00ED jedno p\u00EDrko, kter\u00E9 v\u00EDt\u011Bz nedostane.",
              "Nap\u0159\u00EDklad p\u0159i v\u00FDsledc\u00EDch 20 a 24 pora\u017Een\u00FD odevzd\u00E1 v\u00EDt\u011Bzi \u010Dty\u0159i p\u00EDrka a dal\u0161\u00ED t\u0159i ztrat\u00ED za p\u0159ekro\u010Den\u00ED 21. Pokud p\u0159ebere ka\u017Ed\u00FD, plat\u00ED se jen tyto dodate\u010Dn\u00E9 tresty."),
            rule_section(:risky_dice, "Riskantn\u00ED kostky",
              "H\u00E1zej dv\u011Bma kostkami a s\u010D\u00EDtej v\u00FDsledky hod\u016F. Vyhr\u00E1v\u00E1 nejvy\u0161\u0161\u00ED sou\u010Det, kter\u00FD nep\u0159ekro\u010D\u00ED 25.",
              "Enterem provede\u0161 prvn\u00ED i dal\u0161\u00ED hody. Chce\u0161-li skon\u010Dit, \u0161ipkou dol\u016F vyber \u201EUlo\u017Eit v\u00FDsledek\u201C a potvr\u010F Enterem. Potom za\u010Dne dal\u0161\u00ED hr\u00E1\u010D. P\u0159i sou\u010Dtu 25 nebo vy\u0161\u0161\u00EDm tv\u016Fj pokus skon\u010D\u00ED automaticky.",
              "Na rozhodnut\u00ED m\u00E1\u0161 30 sekund. Potom se v\u00FDsledek ulo\u017E\u00ED; pokud jsi je\u0161t\u011B neh\u00E1zel, hra nejprve provede jeden hod. Karta m\u011Bn\u00EDc\u00ED tvou z\u00E1vodn\u00ED kostku zde p\u016Fsob\u00ED na ob\u011B kostky.",
              "Pora\u017Een\u00FD odevzd\u00E1 v\u00EDt\u011Bzi rozd\u00EDl v\u00FDsledk\u016F v p\u00EDrk\u00E1ch. Za ka\u017Ed\u00FD bod nad 25 nav\u00EDc ztrat\u00ED jedno p\u00EDrko ve prosp\u011Bch hry. P\u0159i v\u00FDsledc\u00EDch 24 a 28 jsou to \u010Dty\u0159i p\u00EDrka v\u00EDt\u011Bzi a t\u0159i za p\u0159ekro\u010Den\u00ED. P\u0159ehod\u00ED-li v\u0161ichni, z\u016Fst\u00E1vaj\u00ED jen tyto tresty."),
            rule_section(:guess_number, "H\u00E1dej \u010D\u00EDslo",
              "Uhodni \u010D\u00EDslo od 1 do 999. Dozv\u00ED\u0161 se, kolik m\u00E1 \u010D\u00EDslic. Pi\u0161 sv\u00E9 odhady; po ka\u017Ed\u00E9m dostane\u0161 n\u00E1pov\u011Bdu, zda je hledan\u00E9 \u010D\u00EDslo vy\u0161\u0161\u00ED, nebo ni\u017E\u0161\u00ED. M\u00E1\u0161 deset pokus\u016F a dv\u011B minuty.",
              "Po\u010D\u00EDt\u00E1 se tv\u016Fj nejbli\u017E\u0161\u00ED odhad. Vyhr\u00E1v\u00E1 ten, kdo se p\u0159ibl\u00ED\u017E\u00ED nejv\u00EDc. Pokud jsou dva hr\u00E1\u010Di stejn\u011B bl\u00EDzko hledan\u00E9mu \u010D\u00EDslu, v\u00FDzva kon\u010D\u00ED rem\u00EDzou.",
              "V\u00EDt\u011Bz bere od ka\u017Ed\u00E9ho soupe\u0159e nejv\u00FD\u0161e p\u011Bt p\u00EDrek podle toho, o kolik byl bl\u00ED\u017E. Nap\u0159\u00EDklad u hledan\u00E9ho \u010D\u00EDsla 47 d\u00E1vaj\u00ED odhady 46 a 35 rozd\u00EDl vzd\u00E1lenost\u00ED 11.",
              "- Jednocifern\u00E9 \u010D\u00EDslo: rozd\u00EDl 1 stoj\u00ED jedno p\u00EDrko, 2\u20133 dv\u011B, 4 t\u0159i, 5\u20136 \u010Dty\u0159i a 7 nebo v\u00EDce p\u011Bt.",
              "- Dvoucifern\u00E9 \u010D\u00EDslo: jedno p\u00EDrko za ka\u017Ed\u00FDch zapo\u010Dat\u00FDch 10 rozd\u00EDlu, nejv\u00FD\u0161e p\u011Bt p\u00EDrek.",
              "- Trojcifern\u00E9 \u010D\u00EDslo: jedno p\u00EDrko za ka\u017Ed\u00FDch zapo\u010Dat\u00FDch 100 rozd\u00EDlu, nejv\u00FD\u0161e p\u011Bt p\u00EDrek.",
              "Bez odpov\u011Bdi odevzd\u00E1\u0161 v\u00EDt\u011Bzi p\u011Bt p\u00EDrek. Nem\u016F\u017Ee\u0161 ztratit v\u00EDc p\u00EDrek, ne\u017E m\u00E1\u0161."),
            rule_section(:copy_number, "Opi\u0161 \u010D\u00EDslo",
              "Co nejrychleji opi\u0161 zadan\u00E9 trojcifern\u00E9 \u010D\u00EDslo. M\u00E1\u0161 t\u0159i pokusy a 15 sekund. Prvn\u00ED spr\u00E1vn\u00E1 odpov\u011B\u010F vyhr\u00E1v\u00E1 \u010Dty\u0159i p\u00EDrka od ka\u017Ed\u00E9ho soupe\u0159e."),
            rule_section(:arithmetic, "Po\u010D\u00EDt\u00E1n\u00ED zpam\u011Bti",
              "Spo\u010D\u00EDtej a napi\u0161 v\u00FDsledek s\u010D\u00EDt\u00E1n\u00ED, od\u010D\u00EDt\u00E1n\u00ED, n\u00E1soben\u00ED nebo d\u011Blen\u00ED. M\u00E1\u0161 t\u0159i pokusy a 20 sekund. Prvn\u00ED spr\u00E1vn\u00E1 odpov\u011B\u010F vyhr\u00E1v\u00E1 \u010Dty\u0159i p\u00EDrka od ka\u017Ed\u00E9ho soupe\u0159e."),
            rule_section(:race_question, "Ot\u00E1zka o z\u00E1vodu",
              "Napi\u0161 odpov\u011B\u010F na ot\u00E1zku o z\u00E1vodu: na kter\u00E9m poli \u010Di v jak\u00E9m kole je hr\u00E1\u010D nebo kolik m\u00E1 pe\u0159\u00ED \u010Di karet. Tyto \u00FAdaje si m\u016F\u017Ee\u0161 zjistit kl\u00E1vesami C a S.",
              "M\u00E1\u0161 dva pokusy a 20 sekund. Prvn\u00ED spr\u00E1vn\u00E1 odpov\u011B\u010F vyhr\u00E1v\u00E1 \u010Dty\u0159i p\u00EDrka od ka\u017Ed\u00E9ho soupe\u0159e."),
            rule_section(:numbered_balls, "\u010C\u00EDslovan\u00E9 koule",
              "Dva hr\u00E1\u010Di st\u0159\u00EDdav\u011B odeb\u00EDraj\u00ED koule z \u0159ady. Je jich dvan\u00E1ct, s kladn\u00FDmi i z\u00E1porn\u00FDmi hodnotami. Sna\u017E se z\u00EDskat vy\u0161\u0161\u00ED sou\u010Det ne\u017E soupe\u0159.",
              "\u0158adu prohl\u00ED\u017Eej \u0161ipkami. \u010C\u00EDslice 1, 2 a 3 berou jednu, dv\u011B nebo t\u0159i koule ze za\u010D\u00E1tku \u0159ady. Na rozhodnut\u00ED m\u00E1\u0161 minutu; potom vezme\u0161 jednu kouli.",
              "Po rozebr\u00E1n\u00ED v\u0161ech koul\u00ED vyhr\u00E1v\u00E1 vy\u0161\u0161\u00ED sou\u010Det. V\u00EDt\u011Bz bere rozd\u00EDl v\u00FDsledk\u016F v p\u00EDrk\u00E1ch, nejv\u00FD\u0161e deset."),
            rule_section(:count_ducks, "Spo\u010D\u00EDtej kachny",
              "Spo\u010D\u00EDtej kv\u00E1knut\u00ED a po odpo\u010D\u00EDt\u00E1v\u00E1n\u00ED napi\u0161 jejich po\u010Det. Usly\u0161\u00ED\u0161 jich p\u011Bt a\u017E patn\u00E1ct. Kl\u00E1vesou F5 si je m\u016F\u017Ee\u0161 p\u0159ehr\u00E1t znovu.",
              "Na odpov\u011B\u010F m\u00E1\u0161 dva pokusy a 20 sekund. Prvn\u00ED spr\u00E1vn\u00E1 odpov\u011B\u010F vyhr\u00E1v\u00E1 \u010Dty\u0159i p\u00EDrka od ka\u017Ed\u00E9ho soupe\u0159e."),
            rule_section(:rhythm, "Zopakuj rytmus",
              "Zopakuj rytmus kl\u00E1vesami F a J. P\u0159ed za\u010D\u00E1tkem si m\u016F\u017Ee\u0161 oba zvuky vyzkou\u0161et. Enterem nebo mezern\u00EDkem zah\u00E1j\u00ED\u0161 vlastn\u00ED pokus. Zazn\u00ED \u0161est a\u017E deset \u00FAder\u016F.",
              "Po poslechu stiskni Enter a zahraj rytmus. Na zah\u00E1jen\u00ED m\u00E1\u0161 15 sekund a p\u0159ed n\u00EDm si m\u016F\u017Ee\u0161 vzor je\u0161t\u011B jednou poslechnout pomoc\u00ED F5. Pokus je jeden; t\u0159i sekundy bez \u00FAderu ho ukon\u010D\u00ED.",
              "Polovinu hodnocen\u00ED tvo\u0159\u00ED po\u0159ad\u00ED zvuk\u016F, druhou jejich rozestupy. Vyhr\u00E1v\u00E1 nejp\u0159esn\u011Bj\u0161\u00ED zopakov\u00E1n\u00ED. Za ka\u017Ed\u00FDch zapo\u010Dat\u00FDch deset procentn\u00EDch bod\u016F n\u00E1skoku bere v\u00EDt\u011Bz od dan\u00E9ho soupe\u0159e jedno p\u00EDrko."),
            rule_section(:sound_order, "Se\u0159a\u010F zvuky",
              "Sestav stupnici od nejni\u017E\u0161\u00EDho t\u00F3nu k nejvy\u0161\u0161\u00EDmu. Za\u010Dni po odpo\u010D\u00EDt\u00E1v\u00E1n\u00ED. \u010C\u00EDslicemi 1 a\u017E 8 si poslechne\u0161 t\u00F3ny na jednotliv\u00FDch m\u00EDstech.",
              "Pro v\u00FDm\u011Bnu dvou t\u00F3n\u016F stiskni Shift s \u010D\u00EDslic\u00ED prvn\u00EDho m\u00EDsta a pak Shift s \u010D\u00EDslic\u00ED druh\u00E9ho. Po v\u00FDm\u011Bn\u011B zazn\u00ED oba t\u00F3ny.",
              "M\u00E1\u0161 45 sekund. Vyhraje prvn\u00ED hr\u00E1\u010D, kter\u00FD sestav\u00ED celou stupnici. Ka\u017Ed\u00FD soupe\u0159 mu odevzd\u00E1 p\u00EDrko za t\u00F3n na nespr\u00E1vn\u00E9m m\u00EDst\u011B, nejv\u00FD\u0161e p\u011Bt. Pokud \u00FAkol nikdo nedokon\u010D\u00ED, v\u00EDt\u011Bz nen\u00ED."),
            rule_section(:simon, "Simon",
              "Zapamatuj si st\u00E1le del\u0161\u00ED melodii a opakuj ji \u010D\u00EDslicemi 1 a\u017E 5. Pod jedni\u010Dkou je nejni\u017E\u0161\u00ED t\u00F3n, pod p\u011Btkou nejvy\u0161\u0161\u00ED. P\u0159ed za\u010D\u00E1tkem si t\u00F3ny vyzkou\u0161ej a potom potvr\u010F p\u0159ipravenost Enterem nebo mezern\u00EDkem.",
              "Tv\u016Fj pokus za\u010Dne jedn\u00EDm t\u00F3nem, bez \u010Dek\u00E1n\u00ED na ostatn\u00ED. Po ka\u017Ed\u00E9 spr\u00E1vn\u00E9 odpov\u011Bdi p\u0159ibude dal\u0161\u00ED a melodie se trochu zrychl\u00ED. Odpov\u00EDdej v\u017Edy a\u017E po skon\u010Den\u00ED poslechu.",
              "Hraje\u0161 do prvn\u00ED chyby nebo p\u011Bti sekund bez stisku p\u0159i odpov\u00EDd\u00E1n\u00ED. Ka\u017Ed\u00FD dokon\u010D\u00ED vlastn\u00ED pokus. Po\u010D\u00EDt\u00E1 se nejdel\u0161\u00ED cel\u00E1 zopakovan\u00E1 melodie; v\u00EDt\u011Bz bere od ka\u017Ed\u00E9ho soupe\u0159e jedno p\u00EDrko za ka\u017Ed\u00FD t\u00F3n n\u00E1skoku."),
            rule_section(:sound_memory, "Zvukov\u00E9 dvojice",
              "Najdi v\u00EDce p\u00E1r\u016F ne\u017E soupe\u0159. Pod \u010D\u00EDslicemi od 1 po 0 je deset zvuk\u016F tvo\u0159\u00EDc\u00EDch p\u011Bt p\u00E1r\u016F. A\u017E budete p\u0159ipraveni, oba stiskn\u011Bte Enter.",
              "St\u0159\u00EDdav\u011B odkr\u00FDvejte po dvou m\u00EDstech stiskem jejich \u010D\u00EDslic. Poslouchej i soupe\u0159ovy volby a pamatuj si, kde zvuky jsou. Shodn\u00FD p\u00E1r zmiz\u00ED a p\u0159inese bod, neshodn\u00E9 zvuky se znovu skryj\u00ED.",
              "Na tah m\u00E1\u0161 15 sekund. V\u00FDzva skon\u010D\u00ED nalezen\u00EDm v\u0161ech p\u00E1r\u016F nebo po 90 sekund\u00E1ch. V\u00EDt\u011Bz bere tolik p\u00EDrek, o kolik p\u00E1r\u016F na\u0161el v\u00EDce."),
            rule_section(:hit_duck, "Tref kachnu",
              "Poznej, odkud se oz\u00FDv\u00E1 kv\u00E1knut\u00ED, a stiskni odpov\u00EDdaj\u00EDc\u00ED \u010D\u00EDslici od 1 do 9. Jedni\u010Dka je \u00FApln\u011B vlevo, p\u011Btka uprost\u0159ed a dev\u00EDtka \u00FApln\u011B vpravo.",
              "P\u0159ed za\u010D\u00E1tkem si m\u016F\u017Ee\u0161 poslechnout v\u0161echny pozice. Enterem nebo mezern\u00EDkem zah\u00E1j\u00ED\u0161 vlastn\u00ED pokus. Postupn\u011B se objev\u00ED p\u011Bt c\u00EDl\u016F; na ka\u017Ed\u00FD m\u00E1\u0161 t\u0159i sekundy.",
              "Po ka\u017Ed\u00E9m v\u00FDst\u0159elu usly\u0161\u00ED\u0161 kr\u00E1tk\u00E9 hodnocen\u00ED z\u00E1sahu. Dal\u0161\u00ED kachna se ozve po chv\u00EDli.",
              "Hodnocen\u00ED z\u00E1le\u017E\u00ED na tom, jak bl\u00EDzko se tref\u00ED\u0161:",
              "- P\u0159esn\u00FD z\u00E1sah: 100 %.",
              "- Odchylka o jedno m\u00EDsto: 75 %.",
              "- O dv\u011B m\u00EDsta: 50 %.",
              "- O t\u0159i m\u00EDsta: 25 %.",
              "- Ostatn\u00ED st\u0159ely: nula.",
              "Vyhr\u00E1v\u00E1 nejvy\u0161\u0161\u00ED pr\u016Fm\u011Br z p\u011Bti st\u0159el. Za ka\u017Ed\u00FDch zapo\u010Dat\u00FDch deset procentn\u00EDch bod\u016F n\u00E1skoku bere v\u00EDt\u011Bz od dan\u00E9ho soupe\u0159e jedno p\u00EDrko."),
            rule_section(:quiz, "Kv\u00EDzov\u00E1 ot\u00E1zka",
              "Odpov\u011Bz na ot\u00E1zku v\u00FDb\u011Brem jedn\u00E9 ze \u010Dty\u0159 mo\u017Enost\u00ED \u010D\u00EDslic\u00ED od 1 do 4. M\u016F\u017Ee\u0161 tak\u00E9 pou\u017E\u00EDt \u0161ipky a Enter. M\u00E1\u0161 20 sekund.",
              "Ka\u017Ed\u00FD, kdo odpov\u00ED spr\u00E1vn\u011B, dostane od hry \u010Dty\u0159i p\u00EDrka. V\u00FDsledky usly\u0161\u00EDte, a\u017E odpov\u011Bd\u00ED v\u0161ichni nebo vypr\u0161\u00ED \u010Das.",
              "Na ot\u00E1zku v souboji odpov\u00EDdaj\u00ED jeho \u00FA\u010Dastn\u00EDci. Ot\u00E1zka z pole nebo karty Zv\u011Bdavost je pro v\u0161echny, v\u010Detn\u011B zmrzl\u00FDch kachen."),
            rule_section(:audio_ball, "Jeden bod v Audio Ballu",
              "Zahrajte si o jeden bod na norm\u00E1ln\u00ED obt\u00ED\u017Enost. Prvn\u00ED pod\u00E1vaj\u00EDc\u00ED se losuje a v\u00EDt\u011Bz bere soupe\u0159i p\u011Bt p\u00EDrek.",
              "P\u0159ed za\u010D\u00E1tkem si poslechni t\u0159i druhy m\u00ED\u010D\u016F:",
              "- W nebo \u0161ipka nahoru: prvn\u00ED druh.",
              "- D nebo \u0161ipka vlevo: druh\u00FD druh.",
              "- S nebo \u0161ipka dol\u016F: t\u0159et\u00ED druh.",
              "Oba potvr\u010Fte p\u0159ipravenost Enterem nebo mezern\u00EDkem. Kdy\u017E m\u00E1\u0161 m\u00ED\u010D, p\u0159iprav \u00FAder kl\u00E1vesou A nebo \u0161ipkou vpravo a potom ho odpal jednou ze t\u0159\u00ED kl\u00E1ves.",
              "Po ka\u017Ed\u00E9m soupe\u0159ov\u011B odpalu poznej zvuk m\u00ED\u010De a stiskni odpov\u00EDdaj\u00EDc\u00ED obranu. Po \u00FAsp\u011B\u0161n\u00E9m zachycen\u00ED p\u0159iprav\u00ED\u0161 vlastn\u00ED \u00FAder. Ka\u017Ed\u00E9 odp\u00E1len\u00ED m\u00ED\u010D zrychl\u00ED."),
            rule_section(:axel_pong, "Jeden bod v Axel Pongu",
              "Zahrajte jeden bod ve dvouh\u0159e, v re\u017Eimu Classic s norm\u00E1ln\u00ED rychlost\u00ED. Prvn\u00ED pod\u00E1vaj\u00EDc\u00ED se losuje. V\u00EDt\u011Bz bere soupe\u0159i p\u011Bt p\u00EDrek.",
              "A\u017E bude\u0161 p\u0159ipraven, stiskni Enter. Hra za\u010Dne, jakmile p\u0159ipravenost potvrd\u00ED oba hr\u00E1\u010Di.",
              "P\u00E1lku posouvej \u0161ipkami vlevo a vpravo. \u0160ipkou nahoru nebo mezern\u00EDkem pod\u00E1\u0161. Kdy\u017E se m\u00ED\u010D vrac\u00ED, postav mu p\u00E1lku do cesty a stiskni stejnou kl\u00E1vesu, a\u017E bude v dosahu.",
              "Pokud m\u00E1\u0161 zapnut\u00E9 automatick\u00E9 odr\u00E1\u017Een\u00ED, p\u0159i obran\u011B sta\u010D\u00ED postavit p\u00E1lku na spr\u00E1vn\u00E9 m\u00EDsto. Pod\u00E1n\u00ED prov\u00E1d\u00ED\u0161 s\u00E1m."),
            rule_section(:settings, "Nastaven\u00ED z\u00E1vodu",
              "P\u0159ed z\u00E1vodem hostitel zvol\u00ED nastaven\u00ED:",
              "- Po\u010Det kol: jedno a\u017E deset, v\u00FDchoz\u00ED jsou t\u0159i.",
              "- V\u00FDzvy: za\u0161krtni ty, kter\u00E9 chcete hr\u00E1t. Zpo\u010D\u00E1tku jsou povoleny v\u0161echny. Nech alespo\u0148 jednu pro souboj a jednu pro skupinu.",
              "- Ot\u00E1zky: vyber jazyk a sady. V\u00FDchoz\u00ED je obecn\u00E1 sada. Vybran\u00E9 sady maj\u00ED stejnou \u0161anci p\u0159i losov\u00E1n\u00ED a plat\u00ED pro v\u0161echny ot\u00E1zky v z\u00E1vod\u011B."),
            rule_section(:interruptions, "Ulo\u017Een\u00ED a p\u0159eru\u0161en\u00E9 v\u00FDzvy",
              "Z\u00E1vod lze ulo\u017Eit mezi tahy, a\u017E skon\u010D\u00ED v\u00FDzva a ostatn\u00ED ud\u00E1losti spojen\u00E9 s pohybem.",
              "Pokud \u00FA\u010Dastn\u00EDk v\u00FDzvy opust\u00ED st\u016Fl nebo je nahrazen, v\u00FDzva se zru\u0161\u00ED bez ztr\u00E1ty pe\u0159\u00ED."),
            rule_section(:question_reports, "Hl\u00E1\u0161en\u00ED chyb v ot\u00E1zk\u00E1ch",
              "Ctrl+B ozna\u010D\u00ED aktu\u00E1ln\u00ED ot\u00E1zku k nahl\u00E1\u0161en\u00ED, Ctrl+Shift+B tu p\u0159edchoz\u00ED. Plat\u00ED to pro ot\u00E1zky z pol\u00ED, karet i v\u00FDzev. Po odchodu od stolu vyberte \u201EAno\u201C, a\u017E se program zept\u00E1 na hl\u00E1\u0161en\u00ED, popi\u0161te probl\u00E9m a stiskn\u011Bte \u201EOdeslat\u201C. Formul\u00E1\u0159 ukazuje ot\u00E1zku, mo\u017Enosti i odpov\u011B\u010F ozna\u010Denou v sad\u011B jako spr\u00E1vnou."),
            rule_section(:controls, "Zkratky z\u00E1vodu",
              "\u0160ipky: v\u00FDb\u011Br karty nebo hodu na konci seznamu.",
              "Enter: zahr\u00E1n\u00ED vybran\u00E9 karty nebo hod.",
              "Mezern\u00EDk: hod kostkou.",
              "D: popis vybran\u00E9 karty.",
              "C: tvoje pozice, pe\u0159\u00ED a aktivn\u00ED \u00FA\u010Dinky.",
              "S: stav v\u0161ech hr\u00E1\u010D\u016F.",
              "T: aktu\u00E1ln\u00ED tah nebo v\u00FDzva.",
              "V: p\u0159ehled okruhu od pole, na kter\u00E9m stoj\u00ED\u0161.",
              "P: zopakov\u00E1n\u00ED zad\u00E1n\u00ED v\u00FDzvy.",
              "Ctrl+B: ozna\u010Dit aktu\u00E1ln\u00ED ot\u00E1zku k nahl\u00E1\u0161en\u00ED.",
              "Ctrl+Shift+B: ozna\u010Dit p\u0159edchoz\u00ED ot\u00E1zku k nahl\u00E1\u0161en\u00ED.")
          ]
        when "en"
          [
            rule_section(:aim, "The aim of the game",
              "Duck Racing is a game for two to eight players. Race around Peaceful Pond, use cards to help your duck or hold up your rivals, and compete for feathers in challenges. The first duck to complete the agreed number of laps wins.",
              "The track has 30 squares. Each player starts on square 1 with three cards and six feathers per planned lap. The default race lasts three laps, so you start with 18 feathers.",
              "On your final lap, crossing the finish line is enough to win, including when a card moves you across it."),
            rule_section(:turn, "Your turn",
              "You may play one card before rolling on your turn. Browse your hand with the arrow keys and press D to hear a card's effect and feather cost. Press Enter to play it. If you need to choose a player, use the arrows and confirm with Enter.",
              "Press Space to roll, then move forward by the number shown. You can also select the roll at the bottom of your card list and press Enter. An ordinary die has results from one to six.",
              "Resolve what happens on your landing square before the next player takes a turn. If a card or move starts a challenge, finish it before continuing.",
              "- C checks your position, feathers and active effects.",
              "- S reads everyone's race status.",
              "- T tells you whose turn it is."),
            rule_section(:track, "Squares and encounters",
              "Squares can give you cards or feathers, move your duck, make you miss turns or ask a question. Press V to explore the track and hear each square's description, the ducks there and any card left on it.",
              "When you land, the square acts first, then its card, then an encounter with another duck. If the square or card moves you again, continue resolving events at the new square.",
              "Landing with another duck starts a random duel. If several are there, you face the most recent arrival who is not frozen. You can meet even when you are on different laps.",
              "Moving backwards can take you into an earlier lap, but only as far as the start of the race. For example, one step back from square 1 of lap 2 takes you to square 30 of lap 1."),
            rule_section(:cards, "Playing cards",
              "Cards help you race or hinder your opponents. Some cost feathers, and you need enough to pay the full cost before playing them. You can hold as many cards as you collect.",
              "- Cards played on a duck act immediately. They can move it, give or take feathers, make it miss turns or change its die.",
              "- Cards left on a square wait for the next duck to land there, then disappear after taking effect. Your own duck can trigger them too. Feather-stealing cards are the exception: they leave their owner alone and keep waiting. Each square holds one card.",
              "- Other cards let you take cards from opponents or exchange whole hands.",
              "- Challenge starts a duel with a chosen opponent. Super challenge involves all unfrozen ducks. Curiosity asks everyone a quiz question.",
              "A die-changing card replaces the previous change and also applies in dice challenges. Only rolls made in the race use up its remaining rolls."),
            rule_section(:feathers, "Feathers and freezing",
              "You spend feathers on cards and win or lose them in challenges. When you run out, your duck freezes. You keep your cards but miss between one and four of your turns.",
              "The further ahead of the last duck you are, the longer you stay frozen. The distance includes whole laps:",
              "- Up to 9 squares ahead: one turn.",
              "- 10\u201319 squares ahead: two turns.",
              "- 20\u201329 squares ahead: three turns.",
              "- At least 30 squares ahead: four turns.",
              "You receive five feathers when you thaw. If another effect also makes you miss turns, both waits count down together.",
              "If a missed-turn effect starts before you roll, the current turn counts. If it starts after your roll, count from your next turn."),
            rule_section(:challenge_rules, "Challenges",
              "The race pauses while you play a challenge. Some challenges are for two players; others can involve a group. In turn-based challenges, the starting player is chosen at random.",
              "For speed challenges, wait for the countdown to finish before answering. Press P to hear the task again, including while typing a number.",
              "The winner takes feathers from each loser at the challenge's stated rate. If players tie for first place, no feathers change hands. If you owe more than you have, you give up your remaining feathers."),
            rule_section(:rock_paper_scissors, "Rock, paper, scissors",
              "Two players choose rock, paper or scissors with the arrow keys and confirm with Enter. You have 15 seconds.",
              "Rock beats scissors, scissors beat paper, and paper beats rock. The winner takes three feathers. Matching choices tie. If only one player answers, that player wins."),
            rule_section(:dice_duel, "Dice duel",
              "Take turns rolling once each. Press Enter on your turn; if ten seconds pass, the game rolls for you.",
              "You use your current race die, including any card affecting it. The highest roll wins. Each opponent pays the winner the difference between their rolls in feathers."),
            rule_section(:blackjack, "Twenty-one",
              "Start with two cards and try to get as close to 21 as possible without going over. Each player has a separate 52-card deck.",
              "- Cards from 2 to 10 are worth their numbers.",
              "- Jacks, queens and kings are worth ten.",
              "- An ace is worth eleven unless that would take you over 21, in which case it is worth one. Its value then stays fixed.",
              "On your turn, press Space to draw or Enter to stand. Reaching or exceeding 21 also ends your turn, and the next player begins. You have 30 seconds for each decision; running out of time leaves you with your current total.",
              "The highest total of 21 or less wins. Each loser pays the difference between their total and the winner's in feathers. Going over 21 also costs one extra feather for each point over, paid to the game.",
              "For example, with totals of 20 and 24, the loser gives the winner four feathers and loses three more for going over 21. If everyone goes over, only the extra penalties apply."),
            rule_section(:risky_dice, "Risky dice",
              "Roll two dice and keep adding the results. The highest total of 25 or less wins.",
              "Press Enter to roll, then Enter again whenever you want another roll. To stop, select Save result with Down arrow and confirm with Enter. The next player then begins. A total of 25 or more ends your attempt automatically.",
              "You have 30 seconds for each decision. When time runs out, your total is saved; if you have not rolled yet, the game rolls once first. A card changing your race die applies to both dice.",
              "Each loser pays the winner the difference between their totals in feathers. Every point over 25 costs another feather, paid to the game. With 24 against 28, that means four feathers to the winner and three extra lost. If everyone goes over, only these penalties apply."),
            rule_section(:guess_number, "Guess the number",
              "Find the hidden number from 1 to 999. You are told how many digits it has. Type your guesses; after each one, you learn whether the answer is higher or lower. You have ten guesses and two minutes.",
              "Your closest guess counts. Whoever gets closest wins; if two players are equally close to the target, the challenge is a draw.",
              "The winner takes up to five feathers from each opponent. The amount depends on how much closer the winner was. For example, if the target is 47, guesses of 46 and 35 give an advantage of 11.",
              "- One-digit target: an advantage of 1 costs one feather; 2\u20133 costs two; 4 costs three; 5\u20136 costs four; 7 or more costs five.",
              "- Two-digit target: one feather for each started group of 10 in the advantage, up to five feathers.",
              "- Three-digit target: one feather for each started group of 100 in the advantage, up to five feathers.",
              "If you do not submit a guess, you give the winner five feathers. You can only lose feathers you have."),
            rule_section(:copy_number, "Copy the number",
              "Copy the three-digit number as quickly as you can. You have three attempts and 15 seconds. The first correct answer wins four feathers from each opponent."),
            rule_section(:arithmetic, "Mental arithmetic",
              "Work out and type the answer to an addition, subtraction, multiplication or division. You have three attempts and 20 seconds. The first correct answer wins four feathers from each opponent."),
            rule_section(:race_question, "Question about the race",
              "Type the answer to a question about the race: a player's square, lap, feathers or number of cards. You can check these details with C and S.",
              "You have two attempts and 20 seconds. The first correct answer wins four feathers from each opponent."),
            rule_section(:numbered_balls, "Numbered balls",
              "Two players take turns collecting balls from a row of twelve. The values can be positive or negative. Aim to finish with a higher total than your opponent.",
              "Browse the row with the arrow keys. Press 1, 2 or 3 to take that many balls from the front. You have one minute to decide; when it runs out, you take one ball.",
              "Once the row is empty, the higher total wins. The winner takes feathers equal to the difference, up to ten."),
            rule_section(:count_ducks, "Count the ducks",
              "Count the quacks, then type your answer after the countdown. There are between five and fifteen. Press F5 if you want to hear them again.",
              "You have two attempts and 20 seconds to answer. The first correct answer wins four feathers from each opponent."),
            rule_section(:rhythm, "Repeat the rhythm",
              "Repeat a drum pattern with F and J. Try both sounds, then press Enter or Space to start your own attempt. You hear a pattern of six to ten beats.",
              "After listening, press Enter and play the pattern. You have 15 seconds to begin, and can hear it once more with F5 before starting. You get one attempt; a three-second gap between key presses ends it.",
              "Half your score comes from the order of the sounds, and half from the gaps between them. The most accurate performance wins. Each ten percentage points of advantage, rounded up, earns one feather from that opponent."),
            rule_section(:sound_order, "Order the sounds",
              "Arrange a scale from the lowest note to the highest. Begin after the countdown. Keys 1 to 8 play the notes at those positions.",
              "To swap two notes, press Shift with the first position's digit, then Shift with the second. You hear both notes after the swap.",
              "You have 45 seconds. The first complete scale wins. Each opponent pays one feather per note still out of place, up to five. If nobody finishes, there is no winner."),
            rule_section(:simon, "Simon",
              "Remember a growing tune and repeat it with keys 1 to 5. Key 1 plays the lowest tone and 5 the highest. Try the tones before starting, then press Enter or Space when ready.",
              "Your attempt starts with a single note, without waiting for the other players. Each correct repetition adds one note to the tune and makes it a little faster. Wait until playback ends before repeating it.",
              "Keep going until you make a mistake or go five seconds without a key press while answering. Everyone finishes their own attempt. Your longest complete tune is your score; the winner takes one feather from each opponent for every note of advantage."),
            rule_section(:sound_memory, "Sound pairs",
              "Find more pairs than your opponent. Ten sounds, arranged in five pairs, are hidden under the number keys from 1 through 0. Both players press Enter when ready.",
              "Take turns uncovering two positions by pressing their digits. Listen to your opponent's choices too and remember where the sounds are. A matching pair is removed and scores a point; a mismatch is hidden again.",
              "You have 15 seconds per turn. The challenge ends when all pairs are found or after 90 seconds. The winner takes feathers equal to the difference in pairs found."),
            rule_section(:hit_duck, "Hit the duck",
              "Listen for the quack and press its position on keys 1 to 9. Key 1 is far left, 5 is the centre and 9 is far right.",
              "Try all the positions, then press Enter or Space to start your own attempt. Five targets appear in turn, with three seconds to answer each.",
              "After each shot, you hear a short rating before the next duck appears.",
              "Your score depends on how close you get:",
              "- Exact hit: 100%.",
              "- One position away: 75%.",
              "- Two positions away: 50%.",
              "- Three positions away: 25%.",
              "- Other shots: zero.",
              "The highest average across the five shots wins. Each ten percentage points of advantage, rounded up, earns one feather from that opponent."),
            rule_section(:quiz, "Quiz question",
              "Answer a question by pressing 1 to 4 for one of the four choices. You can also select with the arrows and confirm with Enter. You have 20 seconds.",
              "Everyone who answers correctly receives four feathers from the game. Results are revealed once everyone has answered or time runs out.",
              "A duel question is for its participants. A question from a square or Curiosity is for everyone, including frozen ducks."),
            rule_section(:audio_ball, "One point in Audio Ball",
              "Play one point at Normal difficulty. The first server is chosen at random, and the winner takes five feathers from the opponent.",
              "Before starting, try the three ball sounds:",
              "- W or Up arrow: the first type.",
              "- D or Left arrow: the second type.",
              "- S or Down arrow: the third type.",
              "Both players press Enter or Space when ready. When you have the ball, press A or Right arrow to prepare, then one of the three shot keys to send it.",
              "After each opponent's shot, recognise the ball sound and press the matching defence key. A successful defence lets you prepare your next shot. Each return makes the ball faster."),
            rule_section(:axel_pong, "One point in Axel Pong",
              "Play one singles point in Classic mode at Normal speed. The first server is chosen at random. The winner takes five feathers from the opponent.",
              "Press Enter when you are ready. The point starts once both players have confirmed.",
              "Move your paddle with Left and Right arrow. Serve with Up arrow or Space. When the ball returns, move into its path and press the same key when it comes within reach.",
              "If automatic hitting is enabled in your settings, positioning the paddle is enough to defend. You still serve manually."),
            rule_section(:settings, "Choosing race settings",
              "The host chooses these settings before the race:",
              "- Laps: one to ten, with three as the default.",
              "- Challenges: tick the ones you want to include. All are enabled by default. Keep at least one for duels and one for groups.",
              "- Questions: choose the language and question sets. The general set is selected by default. Each selected set has an equal chance of being drawn, for all questions in the race."),
            rule_section(:interruptions, "Saving and interrupted challenges",
              "You can save the race between turns, once the challenge and any other events from the move have finished.",
              "If a challenge participant leaves the table or is replaced, the challenge is cancelled without anyone losing feathers."),
            rule_section(:question_reports, "Reporting questions",
              "Ctrl+B marks the current question for reporting, and Ctrl+Shift+B marks the previous one. This works for questions from squares, cards and challenges. After leaving the table, choose Yes when asked whether you want to report them. Describe the problem and press Send. The form shows the question, its choices and the answer marked as correct in the set."),
            rule_section(:controls, "Race shortcuts",
              "Arrow keys: choose a card or the roll at the end of the list.",
              "Enter: play the selected card or roll.",
              "Space: roll the die.",
              "D: describe the selected card.",
              "C: your position, feathers and active effects.",
              "S: everyone's race status.",
              "T: current turn or challenge.",
              "V: explore the track, starting at your current square.",
              "P: repeat the challenge instructions.",
              "Ctrl+B: mark the current question for reporting.",
              "Ctrl+Shift+B: mark the previous question for reporting.")
          ]
        when "es"
          [
            rule_section(:aim, "Objetivo",
              "En Carrera de patos pueden participar de dos a ocho personas. Da la vuelta al Estanque tranquilo, ay\u00FAdate con las cartas y compite por plumas en los desaf\u00EDos. Gana el primer pato que complete las vueltas acordadas.",
              "El circuito tiene 30 casillas. Cada jugador empieza en la casilla 1 con tres cartas y seis plumas por cada vuelta prevista. La carrera predeterminada es de tres vueltas, as\u00ED que recibes 18 plumas al empezar.",
              "En la \u00FAltima vuelta basta con cruzar la meta, tambi\u00E9n si llegas gracias a una carta."),
            rule_section(:turn, "Tu turno",
              "En tu turno puedes jugar una carta antes de tirar. El\u00EDgela con las flechas y pulsa D para escuchar su efecto y su coste en plumas. Enter juega la carta. Si requiere elegir a un jugador, selecci\u00F3nalo con las flechas y confirma con Enter.",
              "Pulsa Espacio para tirar el dado y avanzar tantas casillas como indique. Tambi\u00E9n puedes seleccionar la tirada al final de la lista, debajo de tus cartas, y pulsar Enter. El dado normal da resultados del uno al seis.",
              "Al llegar se resuelven los efectos de la casilla; despu\u00E9s juega la siguiente persona. Si una carta o un movimiento provoca un desaf\u00EDo, primero lo termin\u00E1is.",
              "- C permite consultar tu posici\u00F3n, tus plumas y los efectos activos.",
              "- S lee la situaci\u00F3n de todos los jugadores.",
              "- T recuerda a qui\u00E9n le toca jugar."),
            rule_section(:track, "Casillas y encuentros",
              "Las casillas pueden dar cartas y plumas, moverte a otro lugar, hacerte perder turnos o plantear preguntas. Con V puedes recorrer el circuito y consultar la descripci\u00F3n de cada casilla, los patos que est\u00E1n all\u00ED y la carta que pueda haber.",
              "Al detenerte, act\u00FAa primero la casilla, despu\u00E9s la carta y, por \u00FAltimo, el encuentro con otro pato. Si la casilla o la carta te desplaza de nuevo, los siguientes efectos se resuelven en el nuevo lugar.",
              "Encontrarte con otro pato inicia un duelo al azar. Si hay varios, te enfrentas al \u00FAltimo que haya llegado y no est\u00E9 congelado. Pod\u00E9is estar en vueltas distintas.",
              "Retroceder puede llevarte a una vuelta anterior, como m\u00E1ximo hasta el inicio de la carrera. Por ejemplo, un paso atr\u00E1s desde la casilla 1 de la segunda vuelta te deja en la 30 de la primera."),
            rule_section(:cards, "C\u00F3mo usar las cartas",
              "Las cartas te ayudan a avanzar o ponen obst\u00E1culos a tus rivales. Algunas cuestan plumas: necesitas tener el importe completo antes de jugarlas. Puedes guardar tantas cartas como consigas.",
              "- Las cartas jugadas sobre un pato act\u00FAan al momento. Pueden desplazarlo, darle o quitarle plumas, hacerle perder turnos o cambiar su dado.",
              "- Las cartas colocadas en una casilla esperan al siguiente pato y desaparecen despu\u00E9s de actuar. Tambi\u00E9n puedes caer en una carta tuya. Las que roban plumas son la excepci\u00F3n: no afectan a su due\u00F1o y siguen esperando. Cada casilla admite una carta.",
              "- Otras cartas permiten quitar cartas a los rivales o intercambiar manos completas.",
              "- Desaf\u00EDo inicia un duelo con el rival elegido. Superdesaf\u00EDo re\u00FAne a todos los patos no congelados. Curiosidad plantea una pregunta de Quiz a todos.",
              "Un cambio de dado sustituye al anterior y tambi\u00E9n se aplica en los desaf\u00EDos con dados. Solo las tiradas de la carrera consumen los usos que le quedan."),
            rule_section(:feathers, "Plumas y congelaci\u00F3n",
              "Con las plumas pagas cartas y compites en los desaf\u00EDos. Si te quedas sin ellas, tu pato se congela. Conservas las cartas, pero pierdes entre uno y cuatro turnos propios.",
              "Cuanto mayor sea tu ventaja sobre el \u00FAltimo pato, m\u00E1s dura la congelaci\u00F3n. Se cuenta toda la distancia, incluidas las vueltas completas:",
              "- Hasta 9 casillas de ventaja: un turno.",
              "- De 10 a 19 casillas: dos turnos.",
              "- De 20 a 29 casillas: tres turnos.",
              "- A partir de 30 casillas: cuatro turnos.",
              "Al descongelarte recibes cinco plumas. Si tambi\u00E9n pierdes turnos por otro efecto, ambos periodos se descuentan a la vez.",
              "Si el efecto comienza antes de tu tirada, el turno actual ya cuenta como perdido. Si comienza despu\u00E9s, se cuenta desde tu pr\u00F3ximo turno."),
            rule_section(:challenge_rules, "Los desaf\u00EDos",
              "La carrera se detiene mientras disput\u00E1is un desaf\u00EDo. Algunos son para dos personas y otros tambi\u00E9n permiten jugar en grupo. En los desaf\u00EDos por turnos se sortea qui\u00E9n empieza.",
              "En las pruebas de rapidez, espera a que termine la cuenta atr\u00E1s para responder. P repite las instrucciones y tambi\u00E9n funciona mientras escribes un n\u00FAmero.",
              "El ganador recibe plumas de cada perdedor seg\u00FAn las reglas del desaf\u00EDo. Si hay empate en el primer puesto, nadie paga. Si debes entregar m\u00E1s plumas de las que tienes, entregas todas las que te quedan."),
            rule_section(:rock_paper_scissors, "Piedra, papel o tijera",
              "En este duelo para dos, elige piedra, papel o tijera con las flechas y confirma con Enter. Tienes 15 segundos.",
              "La piedra vence a la tijera, la tijera al papel y el papel a la piedra. El ganador se lleva tres plumas. Las elecciones iguales empatan. Si solo responde una persona, gana esa persona."),
            rule_section(:dice_duel, "Duelo de dados",
              "Tir\u00E1is por turnos, una vez cada uno. Pulsa Enter cuando te toque. Tienes diez segundos; despu\u00E9s, el juego tira por ti.",
              "Usas tu dado de la carrera, con la carta que lo est\u00E9 modificando. Gana la tirada m\u00E1s alta. Cada rival entrega al ganador tantas plumas como la diferencia entre sus resultados."),
            rule_section(:blackjack, "Veintiuno",
              "Empiezas con dos cartas y buscas acercarte a 21 sin pasarte. Cada jugador utiliza su propia baraja de 52 cartas.",
              "- Las cartas del 2 al 10 valen lo que indica su n\u00FAmero.",
              "- Jota, reina y rey valen diez.",
              "- El as vale once si no hace que superes 21; de lo contrario, vale uno. Ese valor se mantiene hasta el final.",
              "En tu turno, pide carta con Espacio o pl\u00E1ntate con Enter. Llegar a 21 o pasarte tambi\u00E9n termina tu turno y da paso al siguiente jugador. Tienes 30 segundos para cada decisi\u00F3n; si se agotan, te quedas con tu suma actual.",
              "Gana la suma m\u00E1s alta que no supere 21. Cada perdedor paga al ganador la diferencia entre sus resultados en plumas. Adem\u00E1s, pasarse de 21 cuesta una pluma por cada punto de exceso. Estas plumas no las recibe el ganador.",
              "Por ejemplo, con resultados de 20 y 24, quien pierde entrega cuatro plumas al ganador y pierde otras tres por haberse pasado. Si todos superan 21, solo se aplican estas penalizaciones."),
            rule_section(:risky_dice, "Dados arriesgados",
              "Tira dos dados y suma los resultados de tus tiradas. Gana la suma m\u00E1s alta que no supere 25.",
              "Pulsa Enter para tirar y repite cuando quieras otro lanzamiento. Para plantarte, selecciona \u00ABGuardar resultado\u00BB con Flecha abajo y confirma con Enter. Entonces juega la siguiente persona. Una suma de 25 o m\u00E1s termina tu intento autom\u00E1ticamente.",
              "Tienes 30 segundos para cada decisi\u00F3n. Despu\u00E9s se guarda el resultado; si a\u00FAn no has tirado, el juego hace una tirada primero. La carta que modifica tu dado de la carrera afecta aqu\u00ED a los dos dados.",
              "Cada perdedor paga al ganador la diferencia entre sus resultados en plumas. Por cada punto por encima de 25 pierde otra pluma, que no recibe nadie. Con 24 frente a 28 son cuatro plumas para el ganador y tres de penalizaci\u00F3n. Si todos se pasan, solo se aplican las penalizaciones."),
            rule_section(:guess_number, "Adivina el n\u00FAmero",
              "Adivina un n\u00FAmero del 1 al 999. Sabr\u00E1s cu\u00E1ntas cifras tiene. Escribe tus propuestas y recibir\u00E1s una pista despu\u00E9s de cada una: el n\u00FAmero buscado es mayor o menor. Tienes diez intentos y dos minutos.",
              "Cuenta tu respuesta m\u00E1s cercana. Gana quien m\u00E1s se acerque al n\u00FAmero; si dos jugadores quedan igual de cerca, el reto termina en empate.",
              "El ganador recibe hasta cinco plumas de cada rival, seg\u00FAn cu\u00E1nto m\u00E1s se haya acercado. Por ejemplo, si se busca el 47, las respuestas 46 y 35 dan una ventaja de 11.",
              "- N\u00FAmero de una cifra: una ventaja de 1 cuesta una pluma; de 2\u20133, dos; de 4, tres; de 5\u20136, cuatro; y de 7 o m\u00E1s, cinco.",
              "- N\u00FAmero de dos cifras: una pluma por cada 10 de ventaja o fracci\u00F3n, hasta un m\u00E1ximo de cinco.",
              "- N\u00FAmero de tres cifras: una pluma por cada 100 de ventaja o fracci\u00F3n, hasta un m\u00E1ximo de cinco.",
              "Si no respondes, entregas cinco plumas al ganador. Solo puedes perder las plumas que tengas."),
            rule_section(:copy_number, "Copia el n\u00FAmero",
              "Copia el n\u00FAmero de tres cifras lo m\u00E1s r\u00E1pido que puedas. Tienes tres intentos y 15 segundos. La primera respuesta correcta gana cuatro plumas de cada rival."),
            rule_section(:arithmetic, "C\u00E1lculo mental",
              "Calcula y escribe el resultado de una suma, resta, multiplicaci\u00F3n o divisi\u00F3n. Tienes tres intentos y 20 segundos. La primera respuesta correcta gana cuatro plumas de cada rival."),
            rule_section(:race_question, "Pregunta sobre la carrera",
              "Escribe la respuesta a una pregunta sobre la carrera: la casilla o vuelta de un jugador, sus plumas o sus cartas. Puedes consultar estos datos con C y S.",
              "Tienes dos intentos y 20 segundos. La primera respuesta correcta gana cuatro plumas de cada rival."),
            rule_section(:numbered_balls, "Bolas numeradas",
              "Dos jugadores recogen por turnos las bolas de una fila. Hay doce, con valores positivos y negativos. Intenta terminar con una suma mayor que la de tu rival.",
              "Recorre la fila con las flechas. Las teclas 1, 2 y 3 recogen una, dos o tres bolas desde el principio. Tienes un minuto para decidir; despu\u00E9s recoges una bola.",
              "Cuando se acaba la fila, gana la suma m\u00E1s alta. El ganador recibe la diferencia en plumas, hasta un m\u00E1ximo de diez."),
            rule_section(:count_ducks, "Cuenta los patos",
              "Cuenta los graznidos y escribe cu\u00E1ntos has o\u00EDdo cuando termine la cuenta atr\u00E1s. Habr\u00E1 entre cinco y quince. Puedes volver a escucharlos con F5.",
              "Tienes dos intentos y 20 segundos para responder. La primera respuesta correcta gana cuatro plumas de cada rival."),
            rule_section(:rhythm, "Repite el ritmo",
              "Repite un ritmo con F y J. Antes de empezar puedes probar ambos sonidos. Pulsa Enter o Espacio para iniciar tu intento. Sonar\u00E1 un ritmo de seis a diez golpes.",
              "Despu\u00E9s de escuchar, pulsa Enter y toca el ritmo. Tienes 15 segundos para empezar y puedes o\u00EDr el modelo una vez m\u00E1s con F5 antes de hacerlo. Hay un solo intento; tres segundos sin tocar lo terminan.",
              "La mitad de la puntuaci\u00F3n depende del orden de los sonidos y la otra mitad de las pausas entre ellos. Gana la interpretaci\u00F3n m\u00E1s precisa. Por cada diez puntos porcentuales de ventaja, o fracci\u00F3n, el ganador recibe una pluma de ese rival."),
            rule_section(:sound_order, "Ordena los sonidos",
              "Ordena las notas para formar una escala de la m\u00E1s grave a la m\u00E1s aguda. Empieza tras la cuenta atr\u00E1s. Las teclas del 1 al 8 permiten escuchar cada posici\u00F3n.",
              "Para intercambiar dos notas, pulsa Shift con la cifra de la primera posici\u00F3n y despu\u00E9s Shift con la de la segunda. Oir\u00E1s ambas notas despu\u00E9s del cambio.",
              "Tienes 45 segundos. Gana quien complete primero la escala. Cada rival le entrega una pluma por nota mal colocada, hasta cinco. Si nadie termina, no hay ganador."),
            rule_section(:simon, "Sim\u00F3n",
              "Memoriza una melod\u00EDa cada vez m\u00E1s larga y rep\u00EDtela con las teclas del 1 al 5. El 1 corresponde al tono m\u00E1s grave y el 5 al m\u00E1s agudo. Puedes probarlos antes de empezar y confirmar que est\u00E1s listo con Enter o Espacio.",
              "Tu intento empieza con una sola nota, sin esperar a los dem\u00E1s. Cada respuesta correcta a\u00F1ade una nota y acelera un poco la melod\u00EDa. Espera al final de la reproducci\u00F3n para repetirla.",
              "Contin\u00FAas hasta que te equivocas o pasas cinco segundos sin pulsar una tecla al responder. Cada jugador termina su propio intento. Cuenta la melod\u00EDa m\u00E1s larga repetida entera; el ganador recibe de cada rival una pluma por cada nota de ventaja."),
            rule_section(:sound_memory, "Parejas de sonidos",
              "Encuentra m\u00E1s parejas que tu rival. Bajo las teclas del 1 al 0 se esconden diez sonidos que forman cinco parejas. Los dos puls\u00E1is Enter cuando est\u00E9is listos.",
              "Por turnos, destap\u00E1is dos posiciones pulsando sus cifras. Escucha tambi\u00E9n las elecciones del rival y recuerda d\u00F3nde est\u00E1 cada sonido. Una pareja desaparece y da un punto; si los sonidos no coinciden, vuelven a ocultarse.",
              "Tienes 15 segundos por turno. El desaf\u00EDo termina al descubrir todas las parejas o despu\u00E9s de 90 segundos. El ganador recibe tantas plumas como parejas de ventaja tenga."),
            rule_section(:hit_duck, "Acierta al pato",
              "Identifica de d\u00F3nde viene el graznido y pulsa la cifra correspondiente del 1 al 9. El 1 es el extremo izquierdo, el 5 el centro y el 9 el extremo derecho.",
              "Antes de empezar puedes escuchar todas las posiciones. Pulsa Enter o Espacio para iniciar tu intento. Aparecer\u00E1n cinco objetivos seguidos; tienes tres segundos para cada uno.",
              "Despu\u00E9s de cada disparo oir\u00E1s una breve valoraci\u00F3n. El siguiente pato aparecer\u00E1 tras una pausa.",
              "La puntuaci\u00F3n depende de cu\u00E1nto te acerques:",
              "- Acierto exacto: 100 %.",
              "- Error de una posici\u00F3n: 75 %.",
              "- De dos posiciones: 50 %.",
              "- De tres posiciones: 25 %.",
              "- Los dem\u00E1s disparos: cero.",
              "Gana la media m\u00E1s alta de los cinco disparos. Cada diez puntos porcentuales de ventaja, o fracci\u00F3n, dan al ganador una pluma de ese rival."),
            rule_section(:quiz, "Pregunta de Quiz",
              "Responde a una pregunta eligiendo una de sus cuatro opciones con las teclas del 1 al 4. Tambi\u00E9n puedes usar las flechas y Enter. Tienes 20 segundos.",
              "Cada persona que acierte recibe cuatro plumas del juego. Los resultados se anuncian cuando todos responden o se acaba el tiempo.",
              "En un duelo responden sus participantes. Una pregunta de casilla o de la carta Curiosidad es para todos, incluidos los patos congelados."),
            rule_section(:audio_ball, "Un punto en Audio Ball",
              "Jug\u00E1is un punto en dificultad Normal. El primer saque se sortea y el ganador recibe cinco plumas de su rival.",
              "Antes de empezar, escucha los tres tipos de pelota:",
              "- W o Flecha arriba: primer tipo.",
              "- D o Flecha izquierda: segundo tipo.",
              "- S o Flecha abajo: tercer tipo.",
              "Los dos confirm\u00E1is que est\u00E1is listos con Enter o Espacio. Cuando tengas la pelota, prepara el golpe con A o Flecha derecha y l\u00E1nzala con una de las tres teclas.",
              "Despu\u00E9s de cada golpe rival, reconoce el sonido de la pelota y pulsa la defensa correspondiente. Si la paras, prepara tu siguiente golpe. Cada devoluci\u00F3n acelera la pelota."),
            rule_section(:axel_pong, "Un punto en Axel Pong",
              "Jug\u00E1is un punto individual en modo Classic y a velocidad Normal. El primer saque se sortea. El ganador recibe cinco plumas de su rival.",
              "Pulsa Enter cuando est\u00E9s listo. El punto empieza cuando los dos jugadores hayan confirmado.",
              "Mueve la raqueta con Flecha izquierda y Flecha derecha. Saca con Flecha arriba o Espacio. Cuando vuelva la pelota, col\u00F3cate en su trayectoria y pulsa la misma tecla al tenerla al alcance.",
              "Si tienes activada la devoluci\u00F3n autom\u00E1tica, para defender basta con colocar la raqueta. El saque lo haces t\u00FA."),
            rule_section(:settings, "Ajustes de la carrera",
              "Antes de la carrera, el anfitri\u00F3n elige los ajustes:",
              "- Vueltas: de una a diez; tres de forma predeterminada.",
              "- Desaf\u00EDos: marca los que quer\u00E1is jugar. Todos est\u00E1n activados al principio. Deja al menos uno para duelos y otro para grupos.",
              "- Preguntas: elige el idioma y los conjuntos. El conjunto general viene marcado de inicio. Todos los seleccionados tienen las mismas probabilidades de salir y se usan para cualquier pregunta de la carrera."),
            rule_section(:interruptions, "Guardar y cancelar desaf\u00EDos",
              "Puedes guardar la carrera entre turnos, una vez terminados el desaf\u00EDo y los dem\u00E1s efectos del movimiento.",
              "Si un participante del desaf\u00EDo abandona la mesa o es sustituido, el desaf\u00EDo se cancela sin p\u00E9rdida de plumas."),
            rule_section(:question_reports, "Avisar de errores en las preguntas",
              "Ctrl+B marca la pregunta actual y Ctrl+Shift+B la anterior. Sirve para las preguntas de casillas, cartas y desaf\u00EDos. Al salir de la mesa, elige \u00ABS\u00ED\u00BB cuando se te pregunte si quieres enviar los avisos. Describe el problema y pulsa \u00ABEnviar\u00BB. El formulario muestra la pregunta, las opciones y la respuesta que el conjunto considera correcta."),
            rule_section(:controls, "Atajos de la carrera",
              "Flechas: elegir una carta o la tirada al final de la lista.",
              "Enter: jugar la carta seleccionada o tirar.",
              "Espacio: tirar el dado.",
              "D: descripci\u00F3n de la carta seleccionada.",
              "C: tu posici\u00F3n, plumas y efectos activos.",
              "S: situaci\u00F3n de todos los jugadores.",
              "T: turno o desaf\u00EDo actual.",
              "V: recorrer el circuito desde tu casilla actual.",
              "P: repetir las instrucciones del desaf\u00EDo.",
              "Ctrl+B: marcar la pregunta actual para avisar de un error.",
              "Ctrl+Shift+B: marcar la pregunta anterior para avisar de un error.")
          ]
        when "pl"
          [
            rule_section(:aim, "Cel gry",
              "W Wy\u015Bcigach kaczek mo\u017Ce uczestniczy\u0107 od dw\u00F3ch do o\u015Bmiu os\u00F3b. Okr\u0105\u017Casz Spokojny staw, pomagasz sobie kartami i rywalizujesz z innymi w wyzwaniach. Wygrywa pierwsza kaczka, kt\u00F3ra pokona ustalon\u0105 liczb\u0119 okr\u0105\u017Ce\u0144.",
              "Plansza ma 30 p\u00F3l. Zaczynacie na polu 1, ka\u017Cdy z trzema kartami i sze\u015Bcioma pi\u00F3rami za ka\u017Cde zaplanowane okr\u0105\u017Cenie. Domy\u015Blnie gracie trzy okr\u0105\u017Cenia, wi\u0119c na start dostajesz 18 pi\u00F3r.",
              "Na ostatnim okr\u0105\u017Ceniu wystarczy przekroczy\u0107 met\u0119, r\u00F3wnie\u017C dzi\u0119ki karcie przesuwaj\u0105cej kaczk\u0119."),
            rule_section(:turn, "Przebieg tury",
              "W swojej turze mo\u017Cesz zagra\u0107 jedn\u0105 kart\u0119 przed rzutem ko\u015Bci\u0105. Wybierz j\u0105 strza\u0142kami; klawisz D odczyta jej dzia\u0142anie i koszt w pi\u00F3rach. Enterem zagrywasz kart\u0119. Je\u015Bli wymaga wskazania gracza, wybierz go strza\u0142kami i zatwierd\u017A Enterem.",
              "Naci\u015Bnij Spacj\u0119, \u017Ceby rzuci\u0107 ko\u015Bci\u0105 i przesun\u0105\u0107 si\u0119 o wyrzucon\u0105 liczb\u0119 p\u00F3l. Rzut mo\u017Cesz te\u017C wybra\u0107 Enterem na ko\u0144cu listy, pod kartami. Zwyk\u0142a ko\u015B\u0107 ma od jednego do sze\u015Bciu oczek.",
              "Po ruchu rozgrywacie zdarzenia z pola, na kt\u00F3rym si\u0119 zatrzymasz. Dopiero potem zaczyna nast\u0119pny gracz. Je\u015Bli karta lub ruch wywo\u0142a wyzwanie, najpierw je ko\u0144czycie.",
              "- C przypomina twoj\u0105 pozycj\u0119, liczb\u0119 pi\u00F3r i dzia\u0142aj\u0105ce na ciebie efekty.",
              "- S podaje sytuacj\u0119 wszystkich graczy.",
              "- T przypomina, kto ma teraz wykona\u0107 ruch."),
            rule_section(:track, "Pola i spotkania",
              "Pola mog\u0105 dawa\u0107 karty i pi\u00F3ra, przesuwa\u0107 kaczk\u0119, zatrzymywa\u0107 j\u0105 na kilka tur albo zadawa\u0107 pytania. Plansz\u0119 przejrzysz pod liter\u0105 V. Przy ka\u017Cdym polu znajdziesz jego opis, stoj\u0105ce na nim kaczki i pozostawion\u0105 kart\u0119.",
              "Po zatrzymaniu najpierw dzia\u0142a pole, potem le\u017C\u0105ca na nim karta, a na ko\u0144cu spotykasz inn\u0105 kaczk\u0119. Je\u017Celi pole lub karta przeniesie ci\u0119 dalej, dalsze zdarzenia rozgrywacie ju\u017C w nowym miejscu.",
              "Spotkanie z inn\u0105 kaczk\u0105 rozpoczyna losowy pojedynek. Gdy na polu jest ich kilka, zmierzysz si\u0119 z ostatni\u0105 przyby\u0142\u0105, kt\u00F3ra nie jest zamro\u017Cona. Numer okr\u0105\u017Cenia nie ma znaczenia.",
              "Cofni\u0119cie mo\u017Ce przenie\u015B\u0107 ci\u0119 na poprzednie okr\u0105\u017Cenie, najwy\u017Cej do pocz\u0105tku wy\u015Bcigu. Na przyk\u0142ad jedno pole wstecz z pola 1 drugiego okr\u0105\u017Cenia prowadzi na pole 30 pierwszego."),
            rule_section(:cards, "Zagrywanie kart",
              "Karty pomagaj\u0105 w wy\u015Bcigu lub przeszkadzaj\u0105 rywalom. Niekt\u00F3re kosztuj\u0105 pi\u00F3ra \u2014 aby je zagra\u0107, musisz mie\u0107 pe\u0142n\u0105 wymagan\u0105 liczb\u0119. W r\u0119ce mo\u017Cesz mie\u0107 dowolnie wiele kart.",
              "- Karty zagrane na kaczk\u0119 dzia\u0142aj\u0105 od razu. Mog\u0105 j\u0105 przesun\u0105\u0107, da\u0107 lub zabra\u0107 pi\u00F3ra, zatrzyma\u0107 na kilka tur albo zmieni\u0107 jej ko\u015B\u0107.",
              "- Karty pozostawione na polu czekaj\u0105 na nast\u0119pn\u0105 kaczk\u0119 i po zadzia\u0142aniu znikaj\u0105. Mo\u017Cesz trafi\u0107 tak\u017Ce na w\u0142asn\u0105 kart\u0119. Wyj\u0105tkiem s\u0105 karty kradn\u0105ce pi\u00F3ra: omijaj\u0105 w\u0142a\u015Bciciela i czekaj\u0105 dalej. Na polu mo\u017Ce le\u017Ce\u0107 jedna karta.",
              "- Inne karty pozwalaj\u0105 zabiera\u0107 karty przeciwnikom lub wymienia\u0107 si\u0119 wszystkimi kartami.",
              "- \u201EWyzwanie\u201D rozpoczyna pojedynek z wybran\u0105 osob\u0105, a \u201ESuperwyzwanie\u201D obejmuje wszystkie niezamro\u017Cone kaczki. \u201ECiekawo\u015B\u0107\u201D zadaje pytanie z quizu wszystkim.",
              "Zmiana ko\u015Bci zast\u0119puje poprzedni\u0105 i obowi\u0105zuje r\u00F3wnie\u017C w wyzwaniach z ko\u015B\u0107mi. Jej dzia\u0142anie skracaj\u0105 tylko rzuty wykonywane podczas wy\u015Bcigu."),
            rule_section(:feathers, "Pi\u00F3ra i zamro\u017Cenie",
              "Pi\u00F3rami p\u0142acisz za karty i rozliczasz wyniki wyzwa\u0144. Gdy zostaniesz bez pi\u00F3r, twoja kaczka zamarza. Zachowujesz karty, ale pomijasz od jednej do czterech swoich tur.",
              "Czas zamro\u017Cenia zale\u017Cy od odleg\u0142o\u015Bci od ostatniej kaczki, z uwzgl\u0119dnieniem pe\u0142nych okr\u0105\u017Ce\u0144:",
              "- Przewaga do 9 p\u00F3l: jedna tura.",
              "- Od 10 do 19 p\u00F3l: dwie tury.",
              "- Od 20 do 29 p\u00F3l: trzy tury.",
              "- Co najmniej 30 p\u00F3l: cztery tury.",
              "Po odmro\u017Ceniu dostajesz pi\u0119\u0107 pi\u00F3r. Je\u015Bli musisz pomija\u0107 tury tak\u017Ce z innego powodu, obie przerwy odliczaj\u0105 si\u0119 r\u00F3wnocze\u015Bnie.",
              "Przerwa rozpocz\u0119ta przed rzutem obejmuje ju\u017C bie\u017C\u0105c\u0105 tur\u0119. Je\u015Bli powstanie po rzucie, zacznie si\u0119 od twojej nast\u0119pnej tury."),
            rule_section(:challenge_rules, "Wyzwania",
              "Na czas wyzwania przerywacie wy\u015Bcig. Niekt\u00F3re zadania s\u0105 przeznaczone dla dw\u00F3ch os\u00F3b, inne tak\u017Ce dla wi\u0119kszej grupy. W wyzwaniach turowych losujecie, kto zaczyna.",
              "Przed zadaniem na szybko\u015B\u0107 us\u0142yszysz odliczanie. Odpowiadaj po jego zako\u0144czeniu. Klawisz P przypomina tre\u015B\u0107 zadania; dzia\u0142a r\u00F3wnie\u017C podczas wpisywania liczb.",
              "Zwyci\u0119zca zabiera pi\u00F3ra ka\u017Cdemu przegranemu wed\u0142ug zasad danego wyzwania. Je\u015Bli kilka os\u00F3b uzyska najlepszy wynik, nikt nie przekazuje pi\u00F3r. Kto ma ich mniej, ni\u017C powinien odda\u0107, traci ca\u0142y sw\u00F3j zapas."),
            rule_section(:rock_paper_scissors, "Kamie\u0144, papier, no\u017Cyce",
              "W pojedynku dla dw\u00F3ch os\u00F3b wybierz strza\u0142kami kamie\u0144, papier albo no\u017Cyce i zatwierd\u017A Enterem. Masz 15 sekund.",
              "Kamie\u0144 pokonuje no\u017Cyce, no\u017Cyce papier, a papier kamie\u0144. Zwyci\u0119zca zabiera trzy pi\u00F3ra. Jednakowe wybory oznaczaj\u0105 remis. Je\u015Bli odpowie tylko jedna osoba, to ona wygrywa."),
            rule_section(:dice_duel, "Pojedynek na ko\u015Bci",
              "Rzucacie po kolei, ka\u017Cdy raz. W swojej turze naci\u015Bnij Enter. Masz dziesi\u0119\u0107 sekund; po tym czasie gra rzuci za ciebie.",
              "U\u017Cywasz swojej ko\u015Bci z wy\u015Bcigu, z uwzgl\u0119dnieniem dzia\u0142aj\u0105cej na ni\u0105 karty. Najwy\u017Cszy wynik wygrywa. Zwyci\u0119zca zabiera ka\u017Cdemu przeciwnikowi tyle pi\u00F3r, ile wynosi r\u00F3\u017Cnica ich wynik\u00F3w."),
            rule_section(:blackjack, "Oczko",
              "Dostajesz dwie karty i starasz si\u0119 zbli\u017Cy\u0107 ich sum\u0119 do 21, nie przekraczaj\u0105c tej liczby. Ka\u017Cdy gra w\u0142asn\u0105 tali\u0105 52 kart.",
              "- Karty od 2 do 10 s\u0105 warte tyle punkt\u00F3w, ile wynosi ich numer.",
              "- Walet, dama i kr\u00F3l s\u0105 warte po dziesi\u0119\u0107.",
              "- As otrzymuje warto\u015B\u0107 jedena\u015Bcie, je\u015Bli nie spowoduje przekroczenia 21, a w przeciwnym razie jeden. Ta warto\u015B\u0107 pozostaje do ko\u0144ca wyzwania.",
              "W swojej turze dobieraj Spacj\u0105 albo zako\u0144cz dobieranie Enterem. Twoja tura ko\u0144czy si\u0119 r\u00F3wnie\u017C przy sumie 21 lub wy\u017Cszej. Wtedy zaczyna nast\u0119pny gracz. Na ka\u017Cd\u0105 decyzj\u0119 masz 30 sekund; po ich up\u0142ywie zostajesz z obecn\u0105 sum\u0105.",
              "Wygrywa najwy\u017Csza suma do 21. Ka\u017Cdy przegrany oddaje zwyci\u0119zcy tyle pi\u00F3r, ile wynosi r\u00F3\u017Cnica ich wynik\u00F3w. Przekroczenie 21 kosztuje dodatkowo jedno pi\u00F3ro za ka\u017Cdy punkt ponad limit. Te pi\u00F3ra nie trafiaj\u0105 do zwyci\u0119zcy.",
              "Na przyk\u0142ad przy wynikach 20 i 24 przegrany oddaje zwyci\u0119zcy cztery pi\u00F3ra i traci jeszcze trzy za przekroczenie 21. Je\u015Bli wszyscy przekrocz\u0105 limit, p\u0142ac\u0105 tylko za przekroczenie."),
            rule_section(:risky_dice, "Ryzykowne ko\u015Bci",
              "Rzucaj dwiema ko\u015B\u0107mi i dodawaj wyniki kolejnych rzut\u00F3w. Wygrywa najwy\u017Csza suma nieprzekraczaj\u0105ca 25.",
              "Enterem wykonujesz pierwszy rzut i ka\u017Cdy nast\u0119pny. \u017Beby sko\u0144czy\u0107, strza\u0142k\u0105 w d\u00F3\u0142 wybierz \u201EZapisz wynik\u201D i zatwierd\u017A Enterem. Dopiero wtedy zaczyna nast\u0119pna osoba. Suma 25 lub wy\u017Csza ko\u0144czy twoj\u0105 pr\u00F3b\u0119 automatycznie.",
              "Na decyzj\u0119 masz 30 sekund. Po ich up\u0142ywie zapisujesz wynik; je\u015Bli jeszcze nie rzuci\u0142e\u015B, gra najpierw wykona jeden rzut. Karta zmieniaj\u0105ca twoj\u0105 ko\u015B\u0107 dzia\u0142a tu na obie ko\u015Bci.",
              "Przegrany oddaje zwyci\u0119zcy r\u00F3\u017Cnic\u0119 wynik\u00F3w w pi\u00F3rach. Za ka\u017Cdy punkt ponad 25 traci jeszcze jedno pi\u00F3ro na rzecz gry. Przy wynikach 24 i 28 s\u0105 to cztery pi\u00F3ra dla zwyci\u0119zcy i trzy dodatkowej kary. Je\u015Bli wszyscy przekrocz\u0105 limit, pozostaj\u0105 tylko te kary."),
            rule_section(:guess_number, "Zgadnij liczb\u0119",
              "Odgadnij liczb\u0119 od 1 do 999. Us\u0142yszysz, ile ma cyfr. Wpisuj swoje propozycje, a po ka\u017Cdej otrzymasz wskaz\u00F3wk\u0119: szukana liczba jest wi\u0119ksza albo mniejsza. Masz dziesi\u0119\u0107 pr\u00F3b i dwie minuty.",
              "Liczy si\u0119 twoja najbli\u017Csza odpowied\u017A. Wygrywa osoba, kt\u00F3ra by\u0142a najbli\u017Cej szukanej liczby. Je\u015Bli dwie osoby s\u0105 r\u00F3wnie blisko, wyzwanie ko\u0144czy si\u0119 remisem.",
              "Zwyci\u0119zca zabiera ka\u017Cdemu przeciwnikowi do pi\u0119ciu pi\u00F3r. Ich liczba zale\u017Cy od tego, o ile bli\u017Cej by\u0142 zwyci\u0119zca. Na przyk\u0142ad przy szukanej liczbie 47 odpowiedzi 46 i 35 daj\u0105 przewag\u0119 11.",
              "- Liczba jednocyfrowa: przewaga 1 oznacza jedno pi\u00F3ro, 2\u20133 \u2014 dwa, 4 \u2014 trzy, 5\u20136 \u2014 cztery, a od 7 wzwy\u017C \u2014 pi\u0119\u0107.",
              "- Liczba dwucyfrowa: jedno pi\u00F3ro za ka\u017Cde rozpocz\u0119te 10 przewagi, najwy\u017Cej pi\u0119\u0107 pi\u00F3r.",
              "- Liczba trzycyfrowa: jedno pi\u00F3ro za ka\u017Cde rozpocz\u0119te 100 przewagi, najwy\u017Cej pi\u0119\u0107 pi\u00F3r.",
              "Brak odpowiedzi oznacza oddanie zwyci\u0119zcy pi\u0119ciu pi\u00F3r. Mo\u017Cesz straci\u0107 tylko tyle pi\u00F3r, ile masz."),
            rule_section(:copy_number, "Przepisz liczb\u0119",
              "Jak najszybciej przepisz podan\u0105 trzycyfrow\u0105 liczb\u0119. Masz trzy pr\u00F3by i 15 sekund. Pierwsza poprawna odpowied\u017A wygrywa cztery pi\u00F3ra od ka\u017Cdego przeciwnika."),
            rule_section(:arithmetic, "Rachunek w pami\u0119ci",
              "Oblicz i wpisz wynik dodawania, odejmowania, mno\u017Cenia albo dzielenia. Masz trzy pr\u00F3by i 20 sekund. Pierwsza poprawna odpowied\u017A wygrywa cztery pi\u00F3ra od ka\u017Cdego przeciwnika."),
            rule_section(:race_question, "Pytanie o wy\u015Bcig",
              "Wpisz odpowied\u017A na pytanie o sytuacj\u0119 w wy\u015Bcigu: pozycj\u0119 gracza, jego okr\u0105\u017Cenie, liczb\u0119 pi\u00F3r lub kart. Mo\u017Cesz sprawdzi\u0107 te informacje klawiszami C i S.",
              "Masz dwie pr\u00F3by i 20 sekund. Pierwsza poprawna odpowied\u017A wygrywa cztery pi\u00F3ra od ka\u017Cdego przeciwnika."),
            rule_section(:numbered_balls, "Kule z liczbami",
              "Dwie osoby na zmian\u0119 zabieraj\u0105 kule z rz\u0119du. Jest ich dwana\u015Bcie, z dodatnimi i ujemnymi warto\u015Bciami. Postaraj si\u0119 zebra\u0107 wy\u017Csz\u0105 sum\u0119 ni\u017C przeciwnik.",
              "Przejrzyj rz\u0105d strza\u0142kami. Cyfry 1, 2 i 3 zabieraj\u0105 odpowiednio jedn\u0105, dwie lub trzy kule z jego pocz\u0105tku. Na decyzj\u0119 masz minut\u0119; po jej up\u0142ywie bierzesz jedn\u0105 kul\u0119.",
              "Po zabraniu wszystkich kul wygrywa wy\u017Csza suma. Zwyci\u0119zca odbiera przeciwnikowi r\u00F3\u017Cnic\u0119 wynik\u00F3w w pi\u00F3rach, najwy\u017Cej dziesi\u0119\u0107."),
            rule_section(:count_ducks, "Policz kaczki",
              "Policz kwakania, a po odliczaniu wpisz ich liczb\u0119. Us\u0142yszysz od pi\u0119ciu do pi\u0119tnastu odg\u0142os\u00F3w. Klawiszem F5 mo\u017Cesz pos\u0142ucha\u0107 ich ponownie.",
              "Masz dwie pr\u00F3by i 20 sekund na odpowied\u017A. Pierwsza poprawna wygrywa cztery pi\u00F3ra od ka\u017Cdego przeciwnika."),
            rule_section(:rhythm, "Powt\u00F3rz rytm",
              "Powt\u00F3rz us\u0142yszany rytm klawiszami F i J. Przed rozpocz\u0119ciem mo\u017Cesz wypr\u00F3bowa\u0107 oba d\u017Awi\u0119ki. Enterem lub Spacj\u0105 rozpocznij w\u0142asn\u0105 pr\u00F3b\u0119. Us\u0142yszysz od sze\u015Bciu do dziesi\u0119ciu uderze\u0144.",
              "Po ods\u0142uchu naci\u015Bnij Enter i zagraj rytm. Masz 15 sekund na rozpocz\u0119cie, a wcze\u015Bniej mo\u017Cesz jeszcze raz pos\u0142ucha\u0107 wzoru klawiszem F5. Pr\u00F3ba jest jedna; trzy sekundy bez uderzenia j\u0105 ko\u0144cz\u0105.",
              "Po\u0142owa oceny zale\u017Cy od kolejno\u015Bci d\u017Awi\u0119k\u00F3w, a po\u0142owa od odst\u0119p\u00F3w mi\u0119dzy nimi. Wygrywa najdok\u0142adniejsze powt\u00F3rzenie. Za ka\u017Cde rozpocz\u0119te dziesi\u0119\u0107 punkt\u00F3w procentowych przewagi zwyci\u0119zca zabiera przeciwnikowi jedno pi\u00F3ro."),
            rule_section(:sound_order, "Uporz\u0105dkuj d\u017Awi\u0119ki",
              "U\u0142\u00F3\u017C gam\u0119 od najni\u017Cszego d\u017Awi\u0119ku do najwy\u017Cszego. Zacznij po odliczaniu. Cyfry od 1 do 8 pozwalaj\u0105 ods\u0142ucha\u0107 kolejne miejsca.",
              "\u017Beby zamieni\u0107 dwa d\u017Awi\u0119ki, naci\u015Bnij Shift z cyfr\u0105 pierwszego miejsca, a potem Shift z cyfr\u0105 drugiego. Po zamianie us\u0142yszysz oba d\u017Awi\u0119ki.",
              "Masz 45 sekund. Pierwsza osoba, kt\u00F3ra u\u0142o\u017Cy ca\u0142\u0105 gam\u0119, wygrywa. Ka\u017Cdy przeciwnik oddaje jej po jednym pi\u00F3rze za d\u017Awi\u0119k na z\u0142ym miejscu, najwy\u017Cej pi\u0119\u0107. Je\u015Bli nikt nie uko\u0144czy zadania, nie ma zwyci\u0119zcy."),
            rule_section(:simon, "Simon",
              "Zapami\u0119tuj coraz d\u0142u\u017Csz\u0105 melodi\u0119 i powtarzaj j\u0105 cyframi od 1 do 5. Pod 1 jest najni\u017Cszy ton, pod 5 najwy\u017Cszy. Przed rozpocz\u0119ciem mo\u017Cesz je wypr\u00F3bowa\u0107, a potem rozpocz\u0105\u0107 w\u0142asn\u0105 pr\u00F3b\u0119 Enterem lub Spacj\u0105.",
              "Zaczynasz od jednego d\u017Awi\u0119ku, nie czekaj\u0105c na pozosta\u0142ych. Po ka\u017Cdej poprawnej odpowiedzi melodia wyd\u0142u\u017Ca si\u0119 o kolejny i nieco przyspiesza. Wpisuj odpowied\u017A po zako\u0144czeniu ods\u0142uchu.",
              "Grasz do pierwszej pomy\u0142ki lub pi\u0119ciu sekund bez naci\u015Bni\u0119cia klawisza podczas odpowiadania. Ka\u017Cdy ko\u0144czy w\u0142asn\u0105 pr\u00F3b\u0119. Liczy si\u0119 najd\u0142u\u017Csza melodia powt\u00F3rzona w ca\u0142o\u015Bci; zwyci\u0119zca zabiera ka\u017Cdemu przeciwnikowi po jednym pi\u00F3rze za d\u017Awi\u0119k przewagi."),
            rule_section(:sound_memory, "Pary d\u017Awi\u0119k\u00F3w",
              "Znajd\u017A wi\u0119cej par ni\u017C przeciwnik. Pod cyframi od 1 do 0 ukryto dziesi\u0119\u0107 d\u017Awi\u0119k\u00F3w tworz\u0105cych pi\u0119\u0107 par. Oboje naciskacie Enter, gdy jeste\u015Bcie gotowi.",
              "Na zmian\u0119 odkrywacie po dwa miejsca, naciskaj\u0105c ich cyfry. S\u0142uchaj r\u00F3wnie\u017C wybor\u00F3w przeciwnika i zapami\u0119tuj po\u0142o\u017Cenie d\u017Awi\u0119k\u00F3w. Trafiona para znika i daje punkt, a nietrafione d\u017Awi\u0119ki ponownie si\u0119 chowaj\u0105.",
              "Na tur\u0119 masz 15 sekund. Wyzwanie ko\u0144czy si\u0119 po odkryciu wszystkich par albo po 90 sekundach. Zwyci\u0119zca zabiera tyle pi\u00F3r, o ile wi\u0119cej par znalaz\u0142."),
            rule_section(:hit_duck, "Traf kaczk\u0119",
              "Rozpoznaj, sk\u0105d dochodzi kwakanie, i naci\u015Bnij odpowiedni\u0105 cyfr\u0119 od 1 do 9. Jedynka oznacza skrajn\u0105 lew\u0105 stron\u0119, pi\u0105tka \u015Brodek, a dziewi\u0105tka skrajn\u0105 praw\u0105.",
              "Przed rozpocz\u0119ciem mo\u017Cesz ods\u0142ucha\u0107 wszystkie pozycje. Enterem lub Spacj\u0105 rozpocznij w\u0142asn\u0105 pr\u00F3b\u0119. Pojawi si\u0119 kolejno pi\u0119\u0107 cel\u00F3w; na ka\u017Cdy masz trzy sekundy.",
              "Po ka\u017Cdym strzale us\u0142yszysz kr\u00F3tk\u0105 ocen\u0119 trafienia, a nast\u0119pna kaczka pojawi si\u0119 po chwili przerwy.",
              "Punkty zale\u017C\u0105 od tego, jak blisko trafisz:",
              "- Dok\u0142adne trafienie: 100%.",
              "- Pomy\u0142ka o jedno miejsce: 75%.",
              "- O dwa miejsca: 50%.",
              "- O trzy miejsca: 25%.",
              "- Pozosta\u0142e strza\u0142y: zero.",
              "Wygrywa najwy\u017Csza \u015Brednia z pi\u0119ciu strza\u0142\u00F3w. Za ka\u017Cde rozpocz\u0119te dziesi\u0119\u0107 punkt\u00F3w procentowych przewagi zwyci\u0119zca zabiera przeciwnikowi jedno pi\u00F3ro."),
            rule_section(:quiz, "Pytanie z quizu",
              "Odpowiedz na pytanie, wybieraj\u0105c jedn\u0105 z czterech odpowiedzi cyfr\u0105 od 1 do 4. Mo\u017Cesz te\u017C u\u017Cy\u0107 strza\u0142ek i Entera. Masz 20 sekund.",
              "Ka\u017Cda osoba, kt\u00F3ra odpowie poprawnie, dostaje od gry cztery pi\u00F3ra. Wynik poznajecie, gdy wszyscy odpowiedz\u0105 lub sko\u0144czy si\u0119 czas.",
              "Pytanie w pojedynku dotyczy jego uczestnik\u00F3w. Na pytanie z pola lub karty \u201ECiekawo\u015B\u0107\u201D odpowiadaj\u0105 wszyscy, tak\u017Ce zamro\u017Cone kaczki."),
            rule_section(:audio_ball, "Punkt w Audio Ballu",
              "Rozegrajcie jeden punkt na poziomie Normalnym. Pierwszy serwuj\u0105cy jest losowany, a zwyci\u0119zca zabiera przeciwnikowi pi\u0119\u0107 pi\u00F3r.",
              "Przed rozpocz\u0119ciem pos\u0142uchaj trzech rodzaj\u00F3w pi\u0142ki:",
              "- W lub strza\u0142ka w g\u00F3r\u0119: pierwszy rodzaj.",
              "- D lub strza\u0142ka w lewo: drugi rodzaj.",
              "- S lub strza\u0142ka w d\u00F3\u0142: trzeci rodzaj.",
              "Oboje potwierdzacie gotowo\u015B\u0107 Enterem lub Spacj\u0105. Gdy masz pi\u0142k\u0119, przygotuj uderzenie klawiszem A lub strza\u0142k\u0105 w prawo, a nast\u0119pnie wybierz jego rodzaj jednym z trzech klawiszy.",
              "Po ka\u017Cdym uderzeniu przeciwnika rozpoznaj d\u017Awi\u0119k pi\u0142ki i naci\u015Bnij odpowiadaj\u0105cy mu klawisz obrony. Po udanej obronie przygotowujesz w\u0142asne uderzenie. Z ka\u017Cdym odbiciem pi\u0142ka przyspiesza."),
            rule_section(:axel_pong, "Punkt w Axel Pongu",
              "Rozegrajcie jeden punkt singla w trybie Classic z pr\u0119dko\u015Bci\u0105 Normaln\u0105. Pierwszy serwuj\u0105cy jest losowany. Zwyci\u0119zca zabiera przeciwnikowi pi\u0119\u0107 pi\u00F3r.",
              "Naci\u015Bnij Enter, gdy b\u0119dziesz gotowy. Gra rozpocznie si\u0119 po potwierdzeniu przez obu graczy.",
              "Strza\u0142kami w lewo i w prawo przesuwasz rakietk\u0119. Strza\u0142k\u0105 w g\u00F3r\u0119 lub Spacj\u0105 serwujesz. Gdy pi\u0142ka wraca, ustaw rakietk\u0119 na jej drodze i naci\u015Bnij ten sam klawisz, kiedy znajdzie si\u0119 w zasi\u0119gu odbicia.",
              "Je\u015Bli masz w\u0142\u0105czone automatyczne odbijanie, podczas obrony wystarczy ustawi\u0107 rakietk\u0119. Serwis wykonujesz sam."),
            rule_section(:settings, "Ustawienia wy\u015Bcigu",
              "Przed gr\u0105 gospodarz wybiera ustawienia wy\u015Bcigu:",
              "- Liczba okr\u0105\u017Ce\u0144: od jednego do dziesi\u0119ciu, domy\u015Blnie trzy.",
              "- Wyzwania: zaznacz te, kt\u00F3re maj\u0105 si\u0119 pojawia\u0107. Domy\u015Blnie w\u0142\u0105czone s\u0105 wszystkie. Pozostaw co najmniej jedno dla pojedynku i jedno dla grupy.",
              "- Pytania: wybierz j\u0119zyk i zestawy. Domy\u015Blnie zaznaczony jest zestaw og\u00F3lny. Zaznaczone zestawy maj\u0105 r\u00F3wne szanse losowania i dotycz\u0105 wszystkich pyta\u0144 w wy\u015Bcigu."),
            rule_section(:interruptions, "Zapisywanie i przerwane wyzwania",
              "Wy\u015Bcig mo\u017Cesz zapisa\u0107 pomi\u0119dzy turami, gdy zako\u0144cz\u0105 si\u0119 wyzwanie i pozosta\u0142e zdarzenia z ruchu.",
              "Je\u015Bli uczestnik wyzwania opu\u015Bci st\u00F3\u0142 lub zostanie zast\u0105piony, wyzwanie zostaje anulowane bez utraty pi\u00F3r."),
            rule_section(:question_reports, "Zg\u0142aszanie pyta\u0144",
              "Ctrl+B oznacza bie\u017C\u0105ce pytanie do zg\u0142oszenia, a Ctrl+Shift+B poprzednie. Dzia\u0142a to przy pytaniach z p\u00F3l, kart i wyzwa\u0144. Po opuszczeniu sto\u0142u wybierz \u201ETak\u201D, gdy program zapyta o zg\u0142oszenia, opisz problem i naci\u015Bnij \u201EWy\u015Blij\u201D. Formularz pokazuje pytanie, odpowiedzi i wskazan\u0105 w zestawie poprawn\u0105 odpowied\u017A."),
            rule_section(:controls, "Skr\u00F3ty wy\u015Bcigu",
              "Strza\u0142ki: wyb\u00F3r karty lub rzutu na ko\u0144cu listy.",
              "Enter: zagranie wybranej karty lub rzut.",
              "Spacja: rzut ko\u015Bci\u0105.",
              "D: opis wybranej karty.",
              "C: twoja pozycja, pi\u00F3ra i dzia\u0142aj\u0105ce efekty.",
              "S: sytuacja wszystkich graczy.",
              "T: bie\u017C\u0105ca tura lub wyzwanie.",
              "V: przegl\u0105d planszy od pola, na kt\u00F3rym stoisz.",
              "P: przypomnienie tre\u015Bci wyzwania.",
              "Ctrl+B \u2014 oznacz bie\u017C\u0105ce pytanie do zg\u0142oszenia.",
              "Ctrl+Shift+B \u2014 oznacz poprzednie pytanie do zg\u0142oszenia.")
          ]
        when "ru"
          [
            rule_section(:aim, "\u0426\u0435\u043B\u044C \u0438\u0433\u0440\u044B",
              "\u0412 \u0423\u0442\u0438\u043D\u044B\u0445 \u0433\u043E\u043D\u043A\u0430\u0445 \u043C\u043E\u0433\u0443\u0442 \u0443\u0447\u0430\u0441\u0442\u0432\u043E\u0432\u0430\u0442\u044C \u043E\u0442 \u0434\u0432\u0443\u0445 \u0434\u043E \u0432\u043E\u0441\u044C\u043C\u0438 \u0438\u0433\u0440\u043E\u043A\u043E\u0432. \u0412\u0435\u0434\u0438\u0442\u0435 \u0443\u0442\u043A\u0443 \u0432\u043E\u043A\u0440\u0443\u0433 \u0422\u0438\u0445\u043E\u0433\u043E \u043F\u0440\u0443\u0434\u0430, \u043F\u043E\u043C\u043E\u0433\u0430\u0439\u0442\u0435 \u0441\u0435\u0431\u0435 \u043A\u0430\u0440\u0442\u0430\u043C\u0438 \u0438 \u0441\u043E\u0441\u0442\u044F\u0437\u0430\u0439\u0442\u0435\u0441\u044C \u0441 \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A\u0430\u043C\u0438 \u0437\u0430 \u043F\u0435\u0440\u044C\u044F. \u041F\u043E\u0431\u0435\u0436\u0434\u0430\u0435\u0442 \u0442\u043E\u0442, \u043A\u0442\u043E \u043F\u0435\u0440\u0432\u044B\u043C \u043F\u0440\u043E\u0439\u0434\u0451\u0442 \u0437\u0430\u0434\u0430\u043D\u043D\u043E\u0435 \u0447\u0438\u0441\u043B\u043E \u043A\u0440\u0443\u0433\u043E\u0432.",
              "\u041D\u0430 \u0442\u0440\u0430\u0441\u0441\u0435 30 \u043A\u043B\u0435\u0442\u043E\u043A. \u041A\u0430\u0436\u0434\u044B\u0439 \u043D\u0430\u0447\u0438\u043D\u0430\u0435\u0442 \u0441 \u043A\u043B\u0435\u0442\u043A\u0438 1, \u0442\u0440\u0451\u0445 \u043A\u0430\u0440\u0442 \u0438 \u0448\u0435\u0441\u0442\u0438 \u043F\u0435\u0440\u044C\u0435\u0432 \u0437\u0430 \u043A\u0430\u0436\u0434\u044B\u0439 \u0437\u0430\u043F\u043B\u0430\u043D\u0438\u0440\u043E\u0432\u0430\u043D\u043D\u044B\u0439 \u043A\u0440\u0443\u0433. \u041F\u043E \u0443\u043C\u043E\u043B\u0447\u0430\u043D\u0438\u044E \u043A\u0440\u0443\u0433\u043E\u0432 \u0442\u0440\u0438, \u043F\u043E\u044D\u0442\u043E\u043C\u0443 \u043D\u0430 \u0441\u0442\u0430\u0440\u0442\u0435 \u0432\u044B \u043F\u043E\u043B\u0443\u0447\u0430\u0435\u0442\u0435 18 \u043F\u0435\u0440\u044C\u0435\u0432.",
              "\u041D\u0430 \u043F\u043E\u0441\u043B\u0435\u0434\u043D\u0435\u043C \u043A\u0440\u0443\u0433\u0435 \u0434\u043E\u0441\u0442\u0430\u0442\u043E\u0447\u043D\u043E \u043F\u0435\u0440\u0435\u0441\u0435\u0447\u044C \u0444\u0438\u043D\u0438\u0448\u043D\u0443\u044E \u0447\u0435\u0440\u0442\u0443, \u0432 \u0442\u043E\u043C \u0447\u0438\u0441\u043B\u0435 \u0441 \u043F\u043E\u043C\u043E\u0449\u044C\u044E \u043A\u0430\u0440\u0442\u044B."),
            rule_section(:turn, "\u0412\u0430\u0448 \u0445\u043E\u0434",
              "\u0412 \u0441\u0432\u043E\u0439 \u0445\u043E\u0434 \u043F\u0435\u0440\u0435\u0434 \u0431\u0440\u043E\u0441\u043A\u043E\u043C \u043C\u043E\u0436\u043D\u043E \u0441\u044B\u0433\u0440\u0430\u0442\u044C \u043E\u0434\u043D\u0443 \u043A\u0430\u0440\u0442\u0443. \u0412\u044B\u0431\u0435\u0440\u0438\u0442\u0435 \u0435\u0451 \u0441\u0442\u0440\u0435\u043B\u043A\u0430\u043C\u0438; \u043A\u043B\u0430\u0432\u0438\u0448\u0430 D \u0437\u0430\u0447\u0438\u0442\u0430\u0435\u0442 \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0435 \u0438 \u0441\u0442\u043E\u0438\u043C\u043E\u0441\u0442\u044C \u0432 \u043F\u0435\u0440\u044C\u044F\u0445. \u0427\u0442\u043E\u0431\u044B \u0441\u044B\u0433\u0440\u0430\u0442\u044C \u043A\u0430\u0440\u0442\u0443, \u043D\u0430\u0436\u043C\u0438\u0442\u0435 Enter. \u0415\u0441\u043B\u0438 \u043D\u0443\u0436\u043D\u043E \u0443\u043A\u0430\u0437\u0430\u0442\u044C \u0438\u0433\u0440\u043E\u043A\u0430, \u0432\u044B\u0431\u0435\u0440\u0438\u0442\u0435 \u0435\u0433\u043E \u0441\u0442\u0440\u0435\u043B\u043A\u0430\u043C\u0438 \u0438 \u043F\u043E\u0434\u0442\u0432\u0435\u0440\u0434\u0438\u0442\u0435 Enter.",
              "\u041D\u0430\u0436\u043C\u0438\u0442\u0435 \u041F\u0440\u043E\u0431\u0435\u043B, \u0447\u0442\u043E\u0431\u044B \u0431\u0440\u043E\u0441\u0438\u0442\u044C \u043A\u0443\u0431\u0438\u043A \u0438 \u043F\u0440\u043E\u0439\u0442\u0438 \u0432\u044B\u043F\u0430\u0432\u0448\u0435\u0435 \u0447\u0438\u0441\u043B\u043E \u043A\u043B\u0435\u0442\u043E\u043A. \u0411\u0440\u043E\u0441\u043E\u043A \u043C\u043E\u0436\u043D\u043E \u0442\u0430\u043A\u0436\u0435 \u0432\u044B\u0431\u0440\u0430\u0442\u044C \u0432 \u043A\u043E\u043D\u0446\u0435 \u0441\u043F\u0438\u0441\u043A\u0430 \u043F\u043E\u0434 \u043A\u0430\u0440\u0442\u0430\u043C\u0438 \u0438 \u043F\u043E\u0434\u0442\u0432\u0435\u0440\u0434\u0438\u0442\u044C Enter. \u041E\u0431\u044B\u0447\u043D\u044B\u0439 \u043A\u0443\u0431\u0438\u043A \u0434\u0430\u0451\u0442 \u043E\u0442 \u043E\u0434\u043D\u043E\u0433\u043E \u0434\u043E \u0448\u0435\u0441\u0442\u0438 \u043E\u0447\u043A\u043E\u0432.",
              "\u041F\u043E\u0441\u043B\u0435 \u043F\u0435\u0440\u0435\u043C\u0435\u0449\u0435\u043D\u0438\u044F \u043F\u0440\u043E\u0438\u0441\u0445\u043E\u0434\u044F\u0442 \u0441\u043E\u0431\u044B\u0442\u0438\u044F \u043A\u043B\u0435\u0442\u043A\u0438, \u043D\u0430 \u043A\u043E\u0442\u043E\u0440\u043E\u0439 \u0432\u044B \u043E\u0441\u0442\u0430\u043D\u043E\u0432\u0438\u043B\u0438\u0441\u044C. \u0417\u0430\u0442\u0435\u043C \u0445\u043E\u0434\u0438\u0442 \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0438\u0439 \u0438\u0433\u0440\u043E\u043A. \u0415\u0441\u043B\u0438 \u043A\u0430\u0440\u0442\u0430 \u0438\u043B\u0438 \u043F\u0435\u0440\u0435\u043C\u0435\u0449\u0435\u043D\u0438\u0435 \u0432\u044B\u0437\u0432\u0430\u043B\u0438 \u0438\u0441\u043F\u044B\u0442\u0430\u043D\u0438\u0435, \u0441\u043D\u0430\u0447\u0430\u043B\u0430 \u0437\u0430\u0432\u0435\u0440\u0448\u0438\u0442\u0435 \u0435\u0433\u043E.",
              "- C \u0441\u043E\u043E\u0431\u0449\u0430\u0435\u0442 \u0432\u0430\u0448\u0443 \u043F\u043E\u0437\u0438\u0446\u0438\u044E, \u043F\u0435\u0440\u044C\u044F \u0438 \u0434\u0435\u0439\u0441\u0442\u0432\u0443\u044E\u0449\u0438\u0435 \u044D\u0444\u0444\u0435\u043A\u0442\u044B.",
              "- S \u0437\u0430\u0447\u0438\u0442\u044B\u0432\u0430\u0435\u0442 \u043F\u043E\u043B\u043E\u0436\u0435\u043D\u0438\u0435 \u0432\u0441\u0435\u0445 \u0438\u0433\u0440\u043E\u043A\u043E\u0432.",
              "- T \u043D\u0430\u043F\u043E\u043C\u0438\u043D\u0430\u0435\u0442, \u0447\u0435\u0439 \u0441\u0435\u0439\u0447\u0430\u0441 \u0445\u043E\u0434."),
            rule_section(:track, "\u041A\u043B\u0435\u0442\u043A\u0438 \u0438 \u0432\u0441\u0442\u0440\u0435\u0447\u0438",
              "\u041A\u043B\u0435\u0442\u043A\u0438 \u043C\u043E\u0433\u0443\u0442 \u0434\u0430\u0432\u0430\u0442\u044C \u043A\u0430\u0440\u0442\u044B \u0438 \u043F\u0435\u0440\u044C\u044F, \u043F\u0435\u0440\u0435\u043C\u0435\u0449\u0430\u0442\u044C \u0443\u0442\u043A\u0443, \u0437\u0430\u0441\u0442\u0430\u0432\u043B\u044F\u0442\u044C \u043F\u0440\u043E\u043F\u0443\u0441\u043A\u0430\u0442\u044C \u0445\u043E\u0434\u044B \u0438\u043B\u0438 \u0437\u0430\u0434\u0430\u0432\u0430\u0442\u044C \u0432\u043E\u043F\u0440\u043E\u0441\u044B. \u041D\u0430\u0436\u043C\u0438\u0442\u0435 V, \u0447\u0442\u043E\u0431\u044B \u043F\u0440\u043E\u0441\u043C\u043E\u0442\u0440\u0435\u0442\u044C \u0442\u0440\u0430\u0441\u0441\u0443. \u0423 \u043A\u0430\u0436\u0434\u043E\u0439 \u043A\u043B\u0435\u0442\u043A\u0438 \u0435\u0441\u0442\u044C \u043E\u043F\u0438\u0441\u0430\u043D\u0438\u0435, \u0441\u043F\u0438\u0441\u043E\u043A \u0441\u0442\u043E\u044F\u0449\u0438\u0445 \u043D\u0430 \u043D\u0435\u0439 \u0443\u0442\u043E\u043A \u0438 \u043E\u0441\u0442\u0430\u0432\u043B\u0435\u043D\u043D\u0430\u044F \u043A\u0430\u0440\u0442\u0430.",
              "\u041F\u0440\u0438 \u043E\u0441\u0442\u0430\u043D\u043E\u0432\u043A\u0435 \u0441\u043D\u0430\u0447\u0430\u043B\u0430 \u0434\u0435\u0439\u0441\u0442\u0432\u0443\u0435\u0442 \u043A\u043B\u0435\u0442\u043A\u0430, \u0437\u0430\u0442\u0435\u043C \u043A\u0430\u0440\u0442\u0430 \u043D\u0430 \u043D\u0435\u0439, \u0430 \u043F\u043E\u0441\u043B\u0435 \u044D\u0442\u043E\u0433\u043E \u043F\u0440\u043E\u0438\u0441\u0445\u043E\u0434\u0438\u0442 \u0432\u0441\u0442\u0440\u0435\u0447\u0430 \u0441 \u0434\u0440\u0443\u0433\u043E\u0439 \u0443\u0442\u043A\u043E\u0439. \u0415\u0441\u043B\u0438 \u043A\u043B\u0435\u0442\u043A\u0430 \u0438\u043B\u0438 \u043A\u0430\u0440\u0442\u0430 \u043F\u0435\u0440\u0435\u043C\u0435\u0441\u0442\u0438\u043B\u0430 \u0432\u0430\u0441 \u0434\u0430\u043B\u044C\u0448\u0435, \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0438\u0435 \u0441\u043E\u0431\u044B\u0442\u0438\u044F \u0440\u0430\u0437\u044B\u0433\u0440\u044B\u0432\u0430\u044E\u0442\u0441\u044F \u0443\u0436\u0435 \u043D\u0430 \u043D\u043E\u0432\u043E\u043C \u043C\u0435\u0441\u0442\u0435.",
              "\u0412\u0441\u0442\u0440\u0435\u0447\u0430 \u0441 \u0434\u0440\u0443\u0433\u043E\u0439 \u0443\u0442\u043A\u043E\u0439 \u0432\u044B\u0437\u044B\u0432\u0430\u0435\u0442 \u0441\u043B\u0443\u0447\u0430\u0439\u043D\u044B\u0439 \u043F\u043E\u0435\u0434\u0438\u043D\u043E\u043A. \u0415\u0441\u043B\u0438 \u0443\u0442\u043E\u043A \u043D\u0435\u0441\u043A\u043E\u043B\u044C\u043A\u043E, \u0432\u0430\u0448\u0438\u043C \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A\u043E\u043C \u0441\u0442\u0430\u043D\u0435\u0442 \u043F\u043E\u0441\u043B\u0435\u0434\u043D\u044F\u044F \u043F\u0440\u0438\u0431\u044B\u0432\u0448\u0430\u044F \u0438\u0437 \u043D\u0435\u0437\u0430\u043C\u0451\u0440\u0437\u0448\u0438\u0445. \u041D\u043E\u043C\u0435\u0440 \u043A\u0440\u0443\u0433\u0430 \u0437\u043D\u0430\u0447\u0435\u043D\u0438\u044F \u043D\u0435 \u0438\u043C\u0435\u0435\u0442.",
              "\u041E\u0442\u0441\u0442\u0443\u043F\u043B\u0435\u043D\u0438\u0435 \u043C\u043E\u0436\u0435\u0442 \u0432\u0435\u0440\u043D\u0443\u0442\u044C \u0432\u0430\u0441 \u043D\u0430 \u043F\u0440\u0435\u0434\u044B\u0434\u0443\u0449\u0438\u0439 \u043A\u0440\u0443\u0433, \u0432\u043F\u043B\u043E\u0442\u044C \u0434\u043E \u043D\u0430\u0447\u0430\u043B\u0430 \u0433\u043E\u043D\u043A\u0438. \u041D\u0430\u043F\u0440\u0438\u043C\u0435\u0440, \u0448\u0430\u0433 \u043D\u0430\u0437\u0430\u0434 \u0441 \u043A\u043B\u0435\u0442\u043A\u0438 1 \u0432\u0442\u043E\u0440\u043E\u0433\u043E \u043A\u0440\u0443\u0433\u0430 \u0432\u0435\u0434\u0451\u0442 \u043D\u0430 \u043A\u043B\u0435\u0442\u043A\u0443 30 \u043F\u0435\u0440\u0432\u043E\u0433\u043E."),
            rule_section(:cards, "\u041A\u0430\u0440\u0442\u044B",
              "\u041A\u0430\u0440\u0442\u044B \u043F\u043E\u043C\u043E\u0433\u0430\u044E\u0442 \u0432\u0430\u043C \u0432 \u0433\u043E\u043D\u043A\u0435 \u0438\u043B\u0438 \u043C\u0435\u0448\u0430\u044E\u0442 \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A\u0430\u043C. \u041D\u0435\u043A\u043E\u0442\u043E\u0440\u044B\u0435 \u0441\u0442\u043E\u044F\u0442 \u043F\u0435\u0440\u044C\u0435\u0432: \u0447\u0442\u043E\u0431\u044B \u0441\u044B\u0433\u0440\u0430\u0442\u044C \u0442\u0430\u043A\u0443\u044E \u043A\u0430\u0440\u0442\u0443, \u043D\u0443\u0436\u043D\u043E \u0438\u043C\u0435\u0442\u044C \u0432\u0441\u044E \u0443\u043A\u0430\u0437\u0430\u043D\u043D\u0443\u044E \u0441\u0443\u043C\u043C\u0443. \u0412 \u0440\u0443\u043A\u0435 \u043C\u043E\u0436\u043D\u043E \u0434\u0435\u0440\u0436\u0430\u0442\u044C \u0441\u043A\u043E\u043B\u044C\u043A\u043E \u0443\u0433\u043E\u0434\u043D\u043E \u043A\u0430\u0440\u0442.",
              "- \u041A\u0430\u0440\u0442\u044B, \u0441\u044B\u0433\u0440\u0430\u043D\u043D\u044B\u0435 \u043D\u0430 \u0443\u0442\u043A\u0443, \u0434\u0435\u0439\u0441\u0442\u0432\u0443\u044E\u0442 \u0441\u0440\u0430\u0437\u0443. \u041E\u043D\u0438 \u043C\u043E\u0433\u0443\u0442 \u043F\u0435\u0440\u0435\u043C\u0435\u0441\u0442\u0438\u0442\u044C \u0435\u0451, \u0434\u0430\u0442\u044C \u0438\u043B\u0438 \u043E\u0442\u043D\u044F\u0442\u044C \u043F\u0435\u0440\u044C\u044F, \u0437\u0430\u0434\u0435\u0440\u0436\u0430\u0442\u044C \u043D\u0430 \u043D\u0435\u0441\u043A\u043E\u043B\u044C\u043A\u043E \u0445\u043E\u0434\u043E\u0432 \u0438\u043B\u0438 \u0438\u0437\u043C\u0435\u043D\u0438\u0442\u044C \u043A\u0443\u0431\u0438\u043A.",
              "- \u041A\u0430\u0440\u0442\u0430 \u043D\u0430 \u043A\u043B\u0435\u0442\u043A\u0435 \u0436\u0434\u0451\u0442 \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0443\u044E \u0443\u0442\u043A\u0443 \u0438 \u0438\u0441\u0447\u0435\u0437\u0430\u0435\u0442 \u043F\u043E\u0441\u043B\u0435 \u0441\u0440\u0430\u0431\u0430\u0442\u044B\u0432\u0430\u043D\u0438\u044F. \u041F\u043E\u043F\u0430\u0441\u0442\u044C \u043C\u043E\u0436\u043D\u043E \u0438 \u043D\u0430 \u0441\u0432\u043E\u044E \u043A\u0430\u0440\u0442\u0443. \u0418\u0441\u043A\u043B\u044E\u0447\u0435\u043D\u0438\u0435 \u2014 \u043A\u0430\u0440\u0442\u044B, \u043A\u0440\u0430\u0434\u0443\u0449\u0438\u0435 \u043F\u0435\u0440\u044C\u044F: \u043E\u043D\u0438 \u043F\u0440\u043E\u043F\u0443\u0441\u043A\u0430\u044E\u0442 \u0432\u043B\u0430\u0434\u0435\u043B\u044C\u0446\u0430 \u0438 \u043F\u0440\u043E\u0434\u043E\u043B\u0436\u0430\u044E\u0442 \u0436\u0434\u0430\u0442\u044C. \u041D\u0430 \u043A\u043B\u0435\u0442\u043A\u0435 \u043F\u043E\u043C\u0435\u0449\u0430\u0435\u0442\u0441\u044F \u043E\u0434\u043D\u0430 \u043A\u0430\u0440\u0442\u0430.",
              "- \u0414\u0440\u0443\u0433\u0438\u0435 \u043A\u0430\u0440\u0442\u044B \u043F\u043E\u0437\u0432\u043E\u043B\u044F\u044E\u0442 \u0437\u0430\u0431\u0438\u0440\u0430\u0442\u044C \u043A\u0430\u0440\u0442\u044B \u0443 \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A\u043E\u0432 \u0438\u043B\u0438 \u043E\u0431\u043C\u0435\u043D\u0438\u0432\u0430\u0442\u044C\u0441\u044F \u0432\u0441\u0435\u043C\u0438 \u043A\u0430\u0440\u0442\u0430\u043C\u0438 \u0432 \u0440\u0443\u043A\u0435.",
              "- \u0418\u0441\u043F\u044B\u0442\u0430\u043D\u0438\u0435 \u0432\u044B\u0437\u044B\u0432\u0430\u0435\u0442 \u0432\u044B\u0431\u0440\u0430\u043D\u043D\u043E\u0433\u043E \u0438\u0433\u0440\u043E\u043A\u0430 \u043D\u0430 \u043F\u043E\u0435\u0434\u0438\u043D\u043E\u043A. \u0421\u0443\u043F\u0435\u0440\u0438\u0441\u043F\u044B\u0442\u0430\u043D\u0438\u0435 \u0441\u043E\u0431\u0438\u0440\u0430\u0435\u0442 \u0432\u0441\u0435\u0445 \u043D\u0435\u0437\u0430\u043C\u0451\u0440\u0437\u0448\u0438\u0445 \u0443\u0442\u043E\u043A. \u041B\u044E\u0431\u043E\u043F\u044B\u0442\u0441\u0442\u0432\u043E \u0437\u0430\u0434\u0430\u0451\u0442 \u0432\u043E\u043F\u0440\u043E\u0441 \u0432\u0438\u043A\u0442\u043E\u0440\u0438\u043D\u044B \u0432\u0441\u0435\u043C.",
              "\u041D\u043E\u0432\u043E\u0435 \u0438\u0437\u043C\u0435\u043D\u0435\u043D\u0438\u0435 \u043A\u0443\u0431\u0438\u043A\u0430 \u0437\u0430\u043C\u0435\u043D\u044F\u0435\u0442 \u043F\u0440\u0435\u0434\u044B\u0434\u0443\u0449\u0435\u0435 \u0438 \u0434\u0435\u0439\u0441\u0442\u0432\u0443\u0435\u0442 \u0442\u0430\u043A\u0436\u0435 \u0432 \u0438\u0441\u043F\u044B\u0442\u0430\u043D\u0438\u044F\u0445 \u0441 \u043A\u0443\u0431\u0438\u043A\u0430\u043C\u0438. \u041E\u0441\u0442\u0430\u0432\u0448\u0435\u0435\u0441\u044F \u0447\u0438\u0441\u043B\u043E \u0431\u0440\u043E\u0441\u043A\u043E\u0432 \u044D\u0442\u043E\u0433\u043E \u044D\u0444\u0444\u0435\u043A\u0442\u0430 \u0443\u043C\u0435\u043D\u044C\u0448\u0430\u0435\u0442\u0441\u044F \u0442\u043E\u043B\u044C\u043A\u043E \u043F\u0440\u0438 \u0431\u0440\u043E\u0441\u043A\u0430\u0445 \u0432 \u0433\u043E\u043D\u043A\u0435."),
            rule_section(:feathers, "\u041F\u0435\u0440\u044C\u044F \u0438 \u0437\u0430\u043C\u0435\u0440\u0437\u0430\u043D\u0438\u0435",
              "\u041F\u0435\u0440\u044C\u044F \u043D\u0443\u0436\u043D\u044B \u0434\u043B\u044F \u043E\u043F\u043B\u0430\u0442\u044B \u043A\u0430\u0440\u0442; \u0438\u0445 \u0442\u0430\u043A\u0436\u0435 \u0432\u044B\u0438\u0433\u0440\u044B\u0432\u0430\u044E\u0442 \u0438 \u0442\u0435\u0440\u044F\u044E\u0442 \u0432 \u0438\u0441\u043F\u044B\u0442\u0430\u043D\u0438\u044F\u0445. \u0411\u0435\u0437 \u043F\u0435\u0440\u044C\u0435\u0432 \u0443\u0442\u043A\u0430 \u0437\u0430\u043C\u0435\u0440\u0437\u0430\u0435\u0442. \u041A\u0430\u0440\u0442\u044B \u043E\u0441\u0442\u0430\u044E\u0442\u0441\u044F \u0443 \u0432\u0430\u0441, \u043D\u043E \u0432\u044B \u043F\u0440\u043E\u043F\u0443\u0441\u043A\u0430\u0435\u0442\u0435 \u043E\u0442 \u043E\u0434\u043D\u043E\u0433\u043E \u0434\u043E \u0447\u0435\u0442\u044B\u0440\u0451\u0445 \u0441\u0432\u043E\u0438\u0445 \u0445\u043E\u0434\u043E\u0432.",
              "\u0427\u0435\u043C \u0431\u043E\u043B\u044C\u0448\u0435 \u043E\u0442\u0440\u044B\u0432 \u043E\u0442 \u043F\u043E\u0441\u043B\u0435\u0434\u043D\u0435\u0439 \u0443\u0442\u043A\u0438, \u0442\u0435\u043C \u0434\u043E\u043B\u044C\u0448\u0435 \u0434\u043B\u0438\u0442\u0441\u044F \u0437\u0430\u043C\u0435\u0440\u0437\u0430\u043D\u0438\u0435. \u0423\u0447\u0438\u0442\u044B\u0432\u0430\u0435\u0442\u0441\u044F \u0432\u0441\u044F \u0434\u0438\u0441\u0442\u0430\u043D\u0446\u0438\u044F, \u0432\u043A\u043B\u044E\u0447\u0430\u044F \u043F\u043E\u043B\u043D\u044B\u0435 \u043A\u0440\u0443\u0433\u0438:",
              "- \u0414\u043E 9 \u043A\u043B\u0435\u0442\u043E\u043A \u043E\u0442\u0440\u044B\u0432\u0430: \u043E\u0434\u0438\u043D \u0445\u043E\u0434.",
              "- \u041E\u0442 10 \u0434\u043E 19 \u043A\u043B\u0435\u0442\u043E\u043A: \u0434\u0432\u0430 \u0445\u043E\u0434\u0430.",
              "- \u041E\u0442 20 \u0434\u043E 29 \u043A\u043B\u0435\u0442\u043E\u043A: \u0442\u0440\u0438 \u0445\u043E\u0434\u0430.",
              "- \u041E\u0442 30 \u043A\u043B\u0435\u0442\u043E\u043A: \u0447\u0435\u0442\u044B\u0440\u0435 \u0445\u043E\u0434\u0430.",
              "\u041A\u043E\u0433\u0434\u0430 \u0443\u0442\u043A\u0430 \u043E\u0442\u0442\u0430\u0435\u0442, \u0432\u044B \u043F\u043E\u043B\u0443\u0447\u0438\u0442\u0435 \u043F\u044F\u0442\u044C \u043F\u0435\u0440\u044C\u0435\u0432. \u0415\u0441\u043B\u0438 \u043F\u0440\u043E\u043F\u0443\u0441\u043A\u0430\u0435\u0442\u0435 \u0445\u043E\u0434\u044B \u0435\u0449\u0451 \u043F\u043E \u043A\u0430\u043A\u043E\u0439-\u0442\u043E \u043F\u0440\u0438\u0447\u0438\u043D\u0435, \u043E\u0431\u0430 \u0441\u0440\u043E\u043A\u0430 \u043E\u0442\u0441\u0447\u0438\u0442\u044B\u0432\u0430\u044E\u0442\u0441\u044F \u043E\u0434\u043D\u043E\u0432\u0440\u0435\u043C\u0435\u043D\u043D\u043E.",
              "\u0415\u0441\u043B\u0438 \u0437\u0430\u0434\u0435\u0440\u0436\u043A\u0430 \u043D\u0430\u0447\u0438\u043D\u0430\u0435\u0442\u0441\u044F \u0434\u043E \u0432\u0430\u0448\u0435\u0433\u043E \u0431\u0440\u043E\u0441\u043A\u0430, \u0442\u0435\u043A\u0443\u0449\u0438\u0439 \u0445\u043E\u0434 \u0443\u0436\u0435 \u0437\u0430\u0441\u0447\u0438\u0442\u044B\u0432\u0430\u0435\u0442\u0441\u044F. \u0415\u0441\u043B\u0438 \u043F\u043E\u0441\u043B\u0435 \u0431\u0440\u043E\u0441\u043A\u0430 \u2014 \u043E\u0442\u0441\u0447\u0451\u0442 \u0438\u0434\u0451\u0442 \u0441 \u0432\u0430\u0448\u0435\u0433\u043E \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0435\u0433\u043E \u0445\u043E\u0434\u0430."),
            rule_section(:challenge_rules, "\u0418\u0441\u043F\u044B\u0442\u0430\u043D\u0438\u044F",
              "\u041D\u0430 \u0432\u0440\u0435\u043C\u044F \u0438\u0441\u043F\u044B\u0442\u0430\u043D\u0438\u044F \u0433\u043E\u043D\u043A\u0430 \u043E\u0441\u0442\u0430\u043D\u0430\u0432\u043B\u0438\u0432\u0430\u0435\u0442\u0441\u044F. \u041E\u0434\u043D\u0438 \u0437\u0430\u0434\u0430\u043D\u0438\u044F \u043F\u0440\u0435\u0434\u043D\u0430\u0437\u043D\u0430\u0447\u0435\u043D\u044B \u0434\u043B\u044F \u0434\u0432\u043E\u0438\u0445, \u0434\u0440\u0443\u0433\u0438\u0435 \u043F\u043E\u0434\u0445\u043E\u0434\u044F\u0442 \u0438 \u0434\u043B\u044F \u0433\u0440\u0443\u043F\u043F\u044B. \u0412 \u0438\u0441\u043F\u044B\u0442\u0430\u043D\u0438\u044F\u0445 \u0441 \u043F\u043E\u043E\u0447\u0435\u0440\u0451\u0434\u043D\u044B\u043C\u0438 \u0445\u043E\u0434\u0430\u043C\u0438 \u043F\u0435\u0440\u0432\u044B\u0439 \u0438\u0433\u0440\u043E\u043A \u043E\u043F\u0440\u0435\u0434\u0435\u043B\u044F\u0435\u0442\u0441\u044F \u0441\u043B\u0443\u0447\u0430\u0439\u043D\u043E.",
              "\u0412 \u0437\u0430\u0434\u0430\u043D\u0438\u044F\u0445 \u043D\u0430 \u0441\u043A\u043E\u0440\u043E\u0441\u0442\u044C \u043E\u0442\u0432\u0435\u0447\u0430\u0439\u0442\u0435 \u043F\u043E\u0441\u043B\u0435 \u043E\u043A\u043E\u043D\u0447\u0430\u043D\u0438\u044F \u043E\u0431\u0440\u0430\u0442\u043D\u043E\u0433\u043E \u043E\u0442\u0441\u0447\u0451\u0442\u0430. \u041A\u043B\u0430\u0432\u0438\u0448\u0430 P \u043F\u043E\u0432\u0442\u043E\u0440\u044F\u0435\u0442 \u0437\u0430\u0434\u0430\u043D\u0438\u0435; \u043E\u043D\u0430 \u0440\u0430\u0431\u043E\u0442\u0430\u0435\u0442 \u0438 \u0432\u043E \u0432\u0440\u0435\u043C\u044F \u0432\u0432\u043E\u0434\u0430 \u0447\u0438\u0441\u043B\u0430.",
              "\u041F\u043E\u0431\u0435\u0434\u0438\u0442\u0435\u043B\u044C \u0437\u0430\u0431\u0438\u0440\u0430\u0435\u0442 \u043F\u0435\u0440\u044C\u044F \u0443 \u043A\u0430\u0436\u0434\u043E\u0433\u043E \u043F\u0440\u043E\u0438\u0433\u0440\u0430\u0432\u0448\u0435\u0433\u043E \u043F\u043E \u043F\u0440\u0430\u0432\u0438\u043B\u0430\u043C \u0438\u0441\u043F\u044B\u0442\u0430\u043D\u0438\u044F. \u041F\u0440\u0438 \u043D\u0438\u0447\u044C\u0435\u0439 \u043D\u0430 \u043F\u0435\u0440\u0432\u043E\u043C \u043C\u0435\u0441\u0442\u0435 \u043F\u0435\u0440\u044C\u044F \u043D\u0435 \u043F\u0435\u0440\u0435\u0434\u0430\u044E\u0442\u0441\u044F. \u0415\u0441\u043B\u0438 \u0443 \u0432\u0430\u0441 \u043C\u0435\u043D\u044C\u0448\u0435 \u043F\u0435\u0440\u044C\u0435\u0432, \u0447\u0435\u043C \u043D\u0443\u0436\u043D\u043E \u043E\u0442\u0434\u0430\u0442\u044C, \u0432\u044B \u0442\u0435\u0440\u044F\u0435\u0442\u0435 \u0432\u0435\u0441\u044C \u043E\u0441\u0442\u0430\u0442\u043E\u043A."),
            rule_section(:rock_paper_scissors, "\u041A\u0430\u043C\u0435\u043D\u044C, \u043D\u043E\u0436\u043D\u0438\u0446\u044B, \u0431\u0443\u043C\u0430\u0433\u0430",
              "\u0412 \u043F\u043E\u0435\u0434\u0438\u043D\u043A\u0435 \u0434\u043B\u044F \u0434\u0432\u043E\u0438\u0445 \u0432\u044B\u0431\u0435\u0440\u0438\u0442\u0435 \u0441\u0442\u0440\u0435\u043B\u043A\u0430\u043C\u0438 \u043A\u0430\u043C\u0435\u043D\u044C, \u0431\u0443\u043C\u0430\u0433\u0443 \u0438\u043B\u0438 \u043D\u043E\u0436\u043D\u0438\u0446\u044B \u0438 \u043F\u043E\u0434\u0442\u0432\u0435\u0440\u0434\u0438\u0442\u0435 Enter. \u0423 \u0432\u0430\u0441 15 \u0441\u0435\u043A\u0443\u043D\u0434.",
              "\u041A\u0430\u043C\u0435\u043D\u044C \u043F\u043E\u0431\u0435\u0436\u0434\u0430\u0435\u0442 \u043D\u043E\u0436\u043D\u0438\u0446\u044B, \u043D\u043E\u0436\u043D\u0438\u0446\u044B \u2014 \u0431\u0443\u043C\u0430\u0433\u0443, \u0430 \u0431\u0443\u043C\u0430\u0433\u0430 \u2014 \u043A\u0430\u043C\u0435\u043D\u044C. \u041F\u043E\u0431\u0435\u0434\u0438\u0442\u0435\u043B\u044C \u0437\u0430\u0431\u0438\u0440\u0430\u0435\u0442 \u0442\u0440\u0438 \u043F\u0435\u0440\u0430. \u041E\u0434\u0438\u043D\u0430\u043A\u043E\u0432\u044B\u0435 \u0444\u0438\u0433\u0443\u0440\u044B \u0434\u0430\u044E\u0442 \u043D\u0438\u0447\u044C\u044E. \u0415\u0441\u043B\u0438 \u043E\u0442\u0432\u0435\u0442\u0438\u0442 \u0442\u043E\u043B\u044C\u043A\u043E \u043E\u0434\u0438\u043D \u0438\u0433\u0440\u043E\u043A, \u043E\u043D \u043F\u043E\u0431\u0435\u0436\u0434\u0430\u0435\u0442."),
            rule_section(:dice_duel, "\u041F\u043E\u0435\u0434\u0438\u043D\u043E\u043A \u043D\u0430 \u043A\u0443\u0431\u0438\u043A\u0430\u0445",
              "\u0411\u0440\u043E\u0441\u0430\u0439\u0442\u0435 \u043F\u043E \u043E\u0447\u0435\u0440\u0435\u0434\u0438, \u043A\u0430\u0436\u0434\u044B\u0439 \u043F\u043E \u043E\u0434\u043D\u043E\u043C\u0443 \u0440\u0430\u0437\u0443. \u0412 \u0441\u0432\u043E\u0439 \u0445\u043E\u0434 \u043D\u0430\u0436\u043C\u0438\u0442\u0435 Enter. \u0427\u0435\u0440\u0435\u0437 \u0434\u0435\u0441\u044F\u0442\u044C \u0441\u0435\u043A\u0443\u043D\u0434 \u0438\u0433\u0440\u0430 \u0431\u0440\u043E\u0441\u0438\u0442 \u0437\u0430 \u0432\u0430\u0441.",
              "\u0418\u0441\u043F\u043E\u043B\u044C\u0437\u0443\u0435\u0442\u0441\u044F \u0432\u0430\u0448 \u043A\u0443\u0431\u0438\u043A \u0438\u0437 \u0433\u043E\u043D\u043A\u0438 \u0441 \u0434\u0435\u0439\u0441\u0442\u0432\u0443\u044E\u0449\u0435\u0439 \u043D\u0430 \u043D\u0435\u0433\u043E \u043A\u0430\u0440\u0442\u043E\u0439. \u041F\u043E\u0431\u0435\u0436\u0434\u0430\u0435\u0442 \u043D\u0430\u0438\u0431\u043E\u043B\u044C\u0448\u0438\u0439 \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442. \u041A\u0430\u0436\u0434\u044B\u0439 \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A \u043E\u0442\u0434\u0430\u0451\u0442 \u043F\u043E\u0431\u0435\u0434\u0438\u0442\u0435\u043B\u044E \u0440\u0430\u0437\u043D\u0438\u0446\u0443 \u043C\u0435\u0436\u0434\u0443 \u0438\u0445 \u0431\u0440\u043E\u0441\u043A\u0430\u043C\u0438 \u0432 \u043F\u0435\u0440\u044C\u044F\u0445."),
            rule_section(:blackjack, "\u0414\u0432\u0430\u0434\u0446\u0430\u0442\u044C \u043E\u0434\u043D\u043E",
              "\u0412\u044B \u043F\u043E\u043B\u0443\u0447\u0430\u0435\u0442\u0435 \u0434\u0432\u0435 \u043A\u0430\u0440\u0442\u044B \u0438 \u0441\u0442\u0430\u0440\u0430\u0435\u0442\u0435\u0441\u044C \u043F\u0440\u0438\u0431\u043B\u0438\u0437\u0438\u0442\u044C \u0438\u0445 \u0441\u0443\u043C\u043C\u0443 \u043A 21, \u043D\u0435 \u043F\u0440\u0435\u0432\u044B\u0441\u0438\u0432 \u0435\u0451. \u0423 \u043A\u0430\u0436\u0434\u043E\u0433\u043E \u0438\u0433\u0440\u043E\u043A\u0430 \u0441\u0432\u043E\u044F \u043A\u043E\u043B\u043E\u0434\u0430 \u0438\u0437 52 \u043A\u0430\u0440\u0442.",
              "- \u041A\u0430\u0440\u0442\u044B \u043E\u0442 2 \u0434\u043E 10 \u0434\u0430\u044E\u0442 \u0441\u0442\u043E\u043B\u044C\u043A\u043E \u043E\u0447\u043A\u043E\u0432, \u0441\u043A\u043E\u043B\u044C\u043A\u043E \u043D\u0430 \u043D\u0438\u0445 \u0443\u043A\u0430\u0437\u0430\u043D\u043E.",
              "- \u0412\u0430\u043B\u0435\u0442, \u0434\u0430\u043C\u0430 \u0438 \u043A\u043E\u0440\u043E\u043B\u044C \u0434\u0430\u044E\u0442 \u043F\u043E \u0434\u0435\u0441\u044F\u0442\u044C.",
              "- \u0422\u0443\u0437 \u043F\u043E\u043B\u0443\u0447\u0430\u0435\u0442 \u0437\u043D\u0430\u0447\u0435\u043D\u0438\u0435 \u043E\u0434\u0438\u043D\u043D\u0430\u0434\u0446\u0430\u0442\u044C, \u0435\u0441\u043B\u0438 \u0441\u0443\u043C\u043C\u0430 \u043D\u0435 \u043F\u0440\u0435\u0432\u044B\u0441\u0438\u0442 21, \u0438\u043D\u0430\u0447\u0435 \u2014 \u043E\u0434\u043D\u043E. \u042D\u0442\u043E \u0437\u043D\u0430\u0447\u0435\u043D\u0438\u0435 \u0441\u043E\u0445\u0440\u0430\u043D\u044F\u0435\u0442\u0441\u044F \u0434\u043E \u043A\u043E\u043D\u0446\u0430 \u0438\u0441\u043F\u044B\u0442\u0430\u043D\u0438\u044F.",
              "\u0412 \u0441\u0432\u043E\u0439 \u0445\u043E\u0434 \u0434\u043E\u0431\u0438\u0440\u0430\u0439\u0442\u0435 \u043A\u0430\u0440\u0442\u044B \u041F\u0440\u043E\u0431\u0435\u043B\u043E\u043C \u0438\u043B\u0438 \u043E\u0441\u0442\u0430\u043D\u043E\u0432\u0438\u0442\u0435\u0441\u044C \u043A\u043B\u0430\u0432\u0438\u0448\u0435\u0439 Enter. \u0421\u0443\u043C\u043C\u0430 21 \u0438\u043B\u0438 \u0431\u043E\u043B\u044C\u0448\u0435 \u0442\u043E\u0436\u0435 \u0437\u0430\u0432\u0435\u0440\u0448\u0430\u0435\u0442 \u0432\u0430\u0448 \u0445\u043E\u0434, \u043F\u043E\u0441\u043B\u0435 \u0447\u0435\u0433\u043E \u043D\u0430\u0447\u0438\u043D\u0430\u0435\u0442 \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0438\u0439 \u0438\u0433\u0440\u043E\u043A. \u041D\u0430 \u043A\u0430\u0436\u0434\u043E\u0435 \u0440\u0435\u0448\u0435\u043D\u0438\u0435 \u0435\u0441\u0442\u044C 30 \u0441\u0435\u043A\u0443\u043D\u0434; \u043A\u043E\u0433\u0434\u0430 \u043E\u043D\u0438 \u0438\u0441\u0442\u0435\u043A\u0430\u044E\u0442, \u0432\u044B \u043E\u0441\u0442\u0430\u0451\u0442\u0435\u0441\u044C \u0441 \u0442\u0435\u043A\u0443\u0449\u0435\u0439 \u0441\u0443\u043C\u043C\u043E\u0439.",
              "\u041F\u043E\u0431\u0435\u0436\u0434\u0430\u0435\u0442 \u043D\u0430\u0438\u0431\u043E\u043B\u044C\u0448\u0430\u044F \u0441\u0443\u043C\u043C\u0430 \u0434\u043E 21 \u0432\u043A\u043B\u044E\u0447\u0438\u0442\u0435\u043B\u044C\u043D\u043E. \u041A\u0430\u0436\u0434\u044B\u0439 \u043F\u0440\u043E\u0438\u0433\u0440\u0430\u0432\u0448\u0438\u0439 \u043E\u0442\u0434\u0430\u0451\u0442 \u043F\u043E\u0431\u0435\u0434\u0438\u0442\u0435\u043B\u044E \u0440\u0430\u0437\u043D\u0438\u0446\u0443 \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442\u043E\u0432 \u0432 \u043F\u0435\u0440\u044C\u044F\u0445. \u0417\u0430 \u043A\u0430\u0436\u0434\u043E\u0435 \u043E\u0447\u043A\u043E \u0441\u0432\u0435\u0440\u0445 21 \u043E\u043D \u0434\u043E\u043F\u043E\u043B\u043D\u0438\u0442\u0435\u043B\u044C\u043D\u043E \u0442\u0435\u0440\u044F\u0435\u0442 \u043E\u0434\u043D\u043E \u043F\u0435\u0440\u043E. \u042D\u0442\u0438 \u043F\u0435\u0440\u044C\u044F \u043F\u043E\u0431\u0435\u0434\u0438\u0442\u0435\u043B\u044C \u043D\u0435 \u043F\u043E\u043B\u0443\u0447\u0430\u0435\u0442.",
              "\u041D\u0430\u043F\u0440\u0438\u043C\u0435\u0440, \u043F\u0440\u0438 \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442\u0430\u0445 20 \u0438 24 \u043F\u0440\u043E\u0438\u0433\u0440\u0430\u0432\u0448\u0438\u0439 \u043E\u0442\u0434\u0430\u0441\u0442 \u043F\u043E\u0431\u0435\u0434\u0438\u0442\u0435\u043B\u044E \u0447\u0435\u0442\u044B\u0440\u0435 \u043F\u0435\u0440\u0430 \u0438 \u043F\u043E\u0442\u0435\u0440\u044F\u0435\u0442 \u0435\u0449\u0451 \u0442\u0440\u0438 \u0437\u0430 \u043F\u0435\u0440\u0435\u0431\u043E\u0440. \u0415\u0441\u043B\u0438 \u043F\u0435\u0440\u0435\u0431\u0440\u0430\u043B\u0438 \u0432\u0441\u0435, \u043E\u0441\u0442\u0430\u044E\u0442\u0441\u044F \u0442\u043E\u043B\u044C\u043A\u043E \u0448\u0442\u0440\u0430\u0444\u044B \u0437\u0430 \u043F\u0435\u0440\u0435\u0431\u043E\u0440."),
            rule_section(:risky_dice, "\u0420\u0438\u0441\u043A\u043E\u0432\u0430\u043D\u043D\u044B\u0435 \u043A\u0443\u0431\u0438\u043A\u0438",
              "\u0411\u0440\u043E\u0441\u0430\u0439\u0442\u0435 \u0434\u0432\u0430 \u043A\u0443\u0431\u0438\u043A\u0430 \u0438 \u0441\u043A\u043B\u0430\u0434\u044B\u0432\u0430\u0439\u0442\u0435 \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442\u044B \u0431\u0440\u043E\u0441\u043A\u043E\u0432. \u041F\u043E\u0431\u0435\u0436\u0434\u0430\u0435\u0442 \u043D\u0430\u0438\u0431\u043E\u043B\u044C\u0448\u0430\u044F \u0441\u0443\u043C\u043C\u0430, \u043D\u0435 \u043F\u0440\u0435\u0432\u044B\u0448\u0430\u044E\u0449\u0430\u044F 25.",
              "\u041D\u0430\u0436\u0438\u043C\u0430\u0439\u0442\u0435 Enter \u0434\u043B\u044F \u043F\u0435\u0440\u0432\u043E\u0433\u043E \u0438 \u043A\u0430\u0436\u0434\u043E\u0433\u043E \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0435\u0433\u043E \u0431\u0440\u043E\u0441\u043A\u0430. \u0427\u0442\u043E\u0431\u044B \u043E\u0441\u0442\u0430\u043D\u043E\u0432\u0438\u0442\u044C\u0441\u044F, \u0432\u044B\u0431\u0435\u0440\u0438\u0442\u0435 \u0441\u0442\u0440\u0435\u043B\u043A\u043E\u0439 \u0432\u043D\u0438\u0437 \u00AB\u0417\u0430\u043F\u0438\u0441\u0430\u0442\u044C \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442\u00BB \u0438 \u043F\u043E\u0434\u0442\u0432\u0435\u0440\u0434\u0438\u0442\u0435 Enter. \u041F\u043E\u0441\u043B\u0435 \u044D\u0442\u043E\u0433\u043E \u043D\u0430\u0447\u0438\u043D\u0430\u0435\u0442 \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0438\u0439 \u0438\u0433\u0440\u043E\u043A. \u041F\u0440\u0438 \u0441\u0443\u043C\u043C\u0435 25 \u0438\u043B\u0438 \u0431\u043E\u043B\u044C\u0448\u0435 \u0432\u0430\u0448\u0430 \u043F\u043E\u043F\u044B\u0442\u043A\u0430 \u0437\u0430\u043A\u0430\u043D\u0447\u0438\u0432\u0430\u0435\u0442\u0441\u044F \u0430\u0432\u0442\u043E\u043C\u0430\u0442\u0438\u0447\u0435\u0441\u043A\u0438.",
              "\u041D\u0430 \u0440\u0435\u0448\u0435\u043D\u0438\u0435 \u0435\u0441\u0442\u044C 30 \u0441\u0435\u043A\u0443\u043D\u0434. \u0417\u0430\u0442\u0435\u043C \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442 \u0437\u0430\u043F\u0438\u0441\u044B\u0432\u0430\u0435\u0442\u0441\u044F; \u0435\u0441\u043B\u0438 \u0432\u044B \u0435\u0449\u0451 \u043D\u0435 \u0431\u0440\u043E\u0441\u0430\u043B\u0438, \u0438\u0433\u0440\u0430 \u0441\u043D\u0430\u0447\u0430\u043B\u0430 \u0432\u044B\u043F\u043E\u043B\u043D\u0438\u0442 \u043E\u0434\u0438\u043D \u0431\u0440\u043E\u0441\u043E\u043A. \u041A\u0430\u0440\u0442\u0430, \u043C\u0435\u043D\u044F\u044E\u0449\u0430\u044F \u0432\u0430\u0448 \u043A\u0443\u0431\u0438\u043A \u0432 \u0433\u043E\u043D\u043A\u0435, \u0437\u0434\u0435\u0441\u044C \u0434\u0435\u0439\u0441\u0442\u0432\u0443\u0435\u0442 \u043D\u0430 \u043E\u0431\u0430 \u043A\u0443\u0431\u0438\u043A\u0430.",
              "\u041F\u0440\u043E\u0438\u0433\u0440\u0430\u0432\u0448\u0438\u0439 \u043E\u0442\u0434\u0430\u0451\u0442 \u043F\u043E\u0431\u0435\u0434\u0438\u0442\u0435\u043B\u044E \u0440\u0430\u0437\u043D\u0438\u0446\u0443 \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442\u043E\u0432 \u0432 \u043F\u0435\u0440\u044C\u044F\u0445. \u0417\u0430 \u043A\u0430\u0436\u0434\u043E\u0435 \u043E\u0447\u043A\u043E \u0441\u0432\u0435\u0440\u0445 25 \u043E\u043D \u0442\u0435\u0440\u044F\u0435\u0442 \u0435\u0449\u0451 \u043E\u0434\u043D\u043E \u043F\u0435\u0440\u043E \u0432 \u043F\u043E\u043B\u044C\u0437\u0443 \u0438\u0433\u0440\u044B. \u041F\u0440\u0438 \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442\u0430\u0445 24 \u0438 28 \u044D\u0442\u043E \u0447\u0435\u0442\u044B\u0440\u0435 \u043F\u0435\u0440\u0430 \u043F\u043E\u0431\u0435\u0434\u0438\u0442\u0435\u043B\u044E \u0438 \u0442\u0440\u0438 \u0448\u0442\u0440\u0430\u0444\u043D\u044B\u0445. \u0415\u0441\u043B\u0438 \u043F\u0435\u0440\u0435\u0431\u0440\u0430\u043B\u0438 \u0432\u0441\u0435, \u043E\u0441\u0442\u0430\u044E\u0442\u0441\u044F \u0442\u043E\u043B\u044C\u043A\u043E \u0448\u0442\u0440\u0430\u0444\u044B."),
            rule_section(:guess_number, "\u0423\u0433\u0430\u0434\u0430\u0439\u0442\u0435 \u0447\u0438\u0441\u043B\u043E",
              "\u0423\u0433\u0430\u0434\u0430\u0439\u0442\u0435 \u0447\u0438\u0441\u043B\u043E \u043E\u0442 1 \u0434\u043E 999. \u0412\u044B \u0443\u0437\u043D\u0430\u0435\u0442\u0435, \u0441\u043A\u043E\u043B\u044C\u043A\u043E \u0432 \u043D\u0451\u043C \u0446\u0438\u0444\u0440. \u0412\u0432\u043E\u0434\u0438\u0442\u0435 \u0441\u0432\u043E\u0438 \u0432\u0430\u0440\u0438\u0430\u043D\u0442\u044B; \u043F\u043E\u0441\u043B\u0435 \u043A\u0430\u0436\u0434\u043E\u0433\u043E \u0438\u0433\u0440\u0430 \u043F\u043E\u0434\u0441\u043A\u0430\u0436\u0435\u0442, \u0431\u043E\u043B\u044C\u0448\u0435 \u0438\u043B\u0438 \u043C\u0435\u043D\u044C\u0448\u0435 \u0437\u0430\u0433\u0430\u0434\u0430\u043D\u043D\u043E\u0435 \u0447\u0438\u0441\u043B\u043E. \u0423 \u0432\u0430\u0441 \u0434\u0435\u0441\u044F\u0442\u044C \u043F\u043E\u043F\u044B\u0442\u043E\u043A \u0438 \u0434\u0432\u0435 \u043C\u0438\u043D\u0443\u0442\u044B.",
              "\u0423\u0447\u0438\u0442\u044B\u0432\u0430\u0435\u0442\u0441\u044F \u0432\u0430\u0448 \u0431\u043B\u0438\u0436\u0430\u0439\u0448\u0438\u0439 \u043E\u0442\u0432\u0435\u0442. \u041F\u043E\u0431\u0435\u0436\u0434\u0430\u0435\u0442 \u0442\u043E\u0442, \u043A\u0442\u043E \u043E\u043A\u0430\u0437\u0430\u043B\u0441\u044F \u0431\u043B\u0438\u0436\u0435 \u0432\u0441\u0435\u0445 \u043A \u0437\u0430\u0433\u0430\u0434\u0430\u043D\u043D\u043E\u043C\u0443 \u0447\u0438\u0441\u043B\u0443. \u0415\u0441\u043B\u0438 \u0434\u0432\u0430 \u0438\u0433\u0440\u043E\u043A\u0430 \u043E\u0434\u0438\u043D\u0430\u043A\u043E\u0432\u043E \u0431\u043B\u0438\u0437\u043A\u0438 \u043A \u043D\u0435\u043C\u0443, \u043E\u0431\u044A\u044F\u0432\u043B\u044F\u0435\u0442\u0441\u044F \u043D\u0438\u0447\u044C\u044F.",
              "\u041F\u043E\u0431\u0435\u0434\u0438\u0442\u0435\u043B\u044C \u0437\u0430\u0431\u0438\u0440\u0430\u0435\u0442 \u0443 \u043A\u0430\u0436\u0434\u043E\u0433\u043E \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A\u0430 \u043D\u0435 \u0431\u043E\u043B\u044C\u0448\u0435 \u043F\u044F\u0442\u0438 \u043F\u0435\u0440\u044C\u0435\u0432. \u041A\u043E\u043B\u0438\u0447\u0435\u0441\u0442\u0432\u043E \u0437\u0430\u0432\u0438\u0441\u0438\u0442 \u043E\u0442 \u0442\u043E\u0433\u043E, \u043D\u0430\u0441\u043A\u043E\u043B\u044C\u043A\u043E \u0442\u043E\u0447\u043D\u0435\u0435 \u0431\u044B\u043B \u0435\u0433\u043E \u043E\u0442\u0432\u0435\u0442. \u041D\u0430\u043F\u0440\u0438\u043C\u0435\u0440, \u043F\u0440\u0438 \u0437\u0430\u0433\u0430\u0434\u0430\u043D\u043D\u043E\u043C \u0447\u0438\u0441\u043B\u0435 47 \u043E\u0442\u0432\u0435\u0442\u044B 46 \u0438 35 \u0434\u0430\u044E\u0442 \u043F\u0440\u0435\u0438\u043C\u0443\u0449\u0435\u0441\u0442\u0432\u043E 11.",
              "- \u041E\u0434\u043D\u043E\u0437\u043D\u0430\u0447\u043D\u043E\u0435 \u0447\u0438\u0441\u043B\u043E: \u043F\u0440\u0435\u0438\u043C\u0443\u0449\u0435\u0441\u0442\u0432\u043E 1 \u0441\u0442\u043E\u0438\u0442 \u043E\u0434\u043D\u043E\u0433\u043E \u043F\u0435\u0440\u0430; 2\u20133 \u2014 \u0434\u0432\u0443\u0445; 4 \u2014 \u0442\u0440\u0451\u0445; 5\u20136 \u2014 \u0447\u0435\u0442\u044B\u0440\u0451\u0445; \u043E\u0442 7 \u0438 \u0432\u044B\u0448\u0435 \u2014 \u043F\u044F\u0442\u0438.",
              "- \u0414\u0432\u0443\u0437\u043D\u0430\u0447\u043D\u043E\u0435 \u0447\u0438\u0441\u043B\u043E: \u043E\u0434\u043D\u043E \u043F\u0435\u0440\u043E \u0437\u0430 \u043A\u0430\u0436\u0434\u044B\u0435 10 \u0435\u0434\u0438\u043D\u0438\u0446 \u043F\u0440\u0435\u0438\u043C\u0443\u0449\u0435\u0441\u0442\u0432\u0430 \u0441 \u043E\u043A\u0440\u0443\u0433\u043B\u0435\u043D\u0438\u0435\u043C \u0432\u0432\u0435\u0440\u0445, \u043D\u043E \u043D\u0435 \u0431\u043E\u043B\u044C\u0448\u0435 \u043F\u044F\u0442\u0438 \u043F\u0435\u0440\u044C\u0435\u0432.",
              "- \u0422\u0440\u0451\u0445\u0437\u043D\u0430\u0447\u043D\u043E\u0435 \u0447\u0438\u0441\u043B\u043E: \u043E\u0434\u043D\u043E \u043F\u0435\u0440\u043E \u0437\u0430 \u043A\u0430\u0436\u0434\u044B\u0435 100 \u0435\u0434\u0438\u043D\u0438\u0446 \u043F\u0440\u0435\u0438\u043C\u0443\u0449\u0435\u0441\u0442\u0432\u0430 \u0441 \u043E\u043A\u0440\u0443\u0433\u043B\u0435\u043D\u0438\u0435\u043C \u0432\u0432\u0435\u0440\u0445, \u043D\u043E \u043D\u0435 \u0431\u043E\u043B\u044C\u0448\u0435 \u043F\u044F\u0442\u0438 \u043F\u0435\u0440\u044C\u0435\u0432.",
              "\u0415\u0441\u043B\u0438 \u0432\u044B \u043D\u0435 \u043E\u0442\u0432\u0435\u0442\u0438\u043B\u0438, \u0442\u043E \u043E\u0442\u0434\u0430\u0451\u0442\u0435 \u043F\u043E\u0431\u0435\u0434\u0438\u0442\u0435\u043B\u044E \u043F\u044F\u0442\u044C \u043F\u0435\u0440\u044C\u0435\u0432. \u041F\u043E\u0442\u0435\u0440\u044F\u0442\u044C \u043C\u043E\u0436\u043D\u043E \u0442\u043E\u043B\u044C\u043A\u043E \u0442\u0435 \u043F\u0435\u0440\u044C\u044F, \u043A\u043E\u0442\u043E\u0440\u044B\u0435 \u0443 \u0432\u0430\u0441 \u0435\u0441\u0442\u044C."),
            rule_section(:copy_number, "\u041F\u0435\u0440\u0435\u043F\u0438\u0448\u0438\u0442\u0435 \u0447\u0438\u0441\u043B\u043E",
              "\u041A\u0430\u043A \u043C\u043E\u0436\u043D\u043E \u0431\u044B\u0441\u0442\u0440\u0435\u0435 \u043F\u0435\u0440\u0435\u043F\u0438\u0448\u0438\u0442\u0435 \u0443\u043A\u0430\u0437\u0430\u043D\u043D\u043E\u0435 \u0442\u0440\u0451\u0445\u0437\u043D\u0430\u0447\u043D\u043E\u0435 \u0447\u0438\u0441\u043B\u043E. \u0423 \u0432\u0430\u0441 \u0442\u0440\u0438 \u043F\u043E\u043F\u044B\u0442\u043A\u0438 \u0438 15 \u0441\u0435\u043A\u0443\u043D\u0434. \u041F\u0435\u0440\u0432\u044B\u0439 \u043F\u0440\u0430\u0432\u0438\u043B\u044C\u043D\u044B\u0439 \u043E\u0442\u0432\u0435\u0442 \u043F\u0440\u0438\u043D\u043E\u0441\u0438\u0442 \u043F\u043E \u0447\u0435\u0442\u044B\u0440\u0435 \u043F\u0435\u0440\u0430 \u043E\u0442 \u043A\u0430\u0436\u0434\u043E\u0433\u043E \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A\u0430."),
            rule_section(:arithmetic, "\u0423\u0441\u0442\u043D\u044B\u0439 \u0441\u0447\u0451\u0442",
              "\u0412\u044B\u0447\u0438\u0441\u043B\u0438\u0442\u0435 \u0438 \u0432\u0432\u0435\u0434\u0438\u0442\u0435 \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442 \u0441\u043B\u043E\u0436\u0435\u043D\u0438\u044F, \u0432\u044B\u0447\u0438\u0442\u0430\u043D\u0438\u044F, \u0443\u043C\u043D\u043E\u0436\u0435\u043D\u0438\u044F \u0438\u043B\u0438 \u0434\u0435\u043B\u0435\u043D\u0438\u044F. \u0423 \u0432\u0430\u0441 \u0442\u0440\u0438 \u043F\u043E\u043F\u044B\u0442\u043A\u0438 \u0438 20 \u0441\u0435\u043A\u0443\u043D\u0434. \u041F\u0435\u0440\u0432\u044B\u0439 \u043F\u0440\u0430\u0432\u0438\u043B\u044C\u043D\u044B\u0439 \u043E\u0442\u0432\u0435\u0442 \u043F\u0440\u0438\u043D\u043E\u0441\u0438\u0442 \u043F\u043E \u0447\u0435\u0442\u044B\u0440\u0435 \u043F\u0435\u0440\u0430 \u043E\u0442 \u043A\u0430\u0436\u0434\u043E\u0433\u043E \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A\u0430."),
            rule_section(:race_question, "\u0412\u043E\u043F\u0440\u043E\u0441 \u043E \u0433\u043E\u043D\u043A\u0435",
              "\u0412\u0432\u0435\u0434\u0438\u0442\u0435 \u043E\u0442\u0432\u0435\u0442 \u043D\u0430 \u0432\u043E\u043F\u0440\u043E\u0441 \u043E \u0433\u043E\u043D\u043A\u0435: \u043A\u043B\u0435\u0442\u043A\u0435 \u0438\u043B\u0438 \u043A\u0440\u0443\u0433\u0435 \u0438\u0433\u0440\u043E\u043A\u0430, \u0447\u0438\u0441\u043B\u0435 \u0435\u0433\u043E \u043F\u0435\u0440\u044C\u0435\u0432 \u0438\u043B\u0438 \u043A\u0430\u0440\u0442. \u042D\u0442\u0438 \u0441\u0432\u0435\u0434\u0435\u043D\u0438\u044F \u043C\u043E\u0436\u043D\u043E \u043F\u0440\u043E\u0432\u0435\u0440\u0438\u0442\u044C \u043A\u043B\u0430\u0432\u0438\u0448\u0430\u043C\u0438 C \u0438 S.",
              "\u0423 \u0432\u0430\u0441 \u0434\u0432\u0435 \u043F\u043E\u043F\u044B\u0442\u043A\u0438 \u0438 20 \u0441\u0435\u043A\u0443\u043D\u0434. \u041F\u0435\u0440\u0432\u044B\u0439 \u043F\u0440\u0430\u0432\u0438\u043B\u044C\u043D\u044B\u0439 \u043E\u0442\u0432\u0435\u0442 \u043F\u0440\u0438\u043D\u043E\u0441\u0438\u0442 \u043F\u043E \u0447\u0435\u0442\u044B\u0440\u0435 \u043F\u0435\u0440\u0430 \u043E\u0442 \u043A\u0430\u0436\u0434\u043E\u0433\u043E \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A\u0430."),
            rule_section(:numbered_balls, "\u0428\u0430\u0440\u044B \u0441 \u0447\u0438\u0441\u043B\u0430\u043C\u0438",
              "\u0414\u0432\u0430 \u0438\u0433\u0440\u043E\u043A\u0430 \u043F\u043E \u043E\u0447\u0435\u0440\u0435\u0434\u0438 \u0431\u0435\u0440\u0443\u0442 \u0448\u0430\u0440\u044B \u0438\u0437 \u0440\u044F\u0434\u0430. \u0412\u0441\u0435\u0433\u043E \u0448\u0430\u0440\u043E\u0432 \u0434\u0432\u0435\u043D\u0430\u0434\u0446\u0430\u0442\u044C, \u0441 \u043F\u043E\u043B\u043E\u0436\u0438\u0442\u0435\u043B\u044C\u043D\u044B\u043C\u0438 \u0438 \u043E\u0442\u0440\u0438\u0446\u0430\u0442\u0435\u043B\u044C\u043D\u044B\u043C\u0438 \u0437\u043D\u0430\u0447\u0435\u043D\u0438\u044F\u043C\u0438. \u041F\u043E\u0441\u0442\u0430\u0440\u0430\u0439\u0442\u0435\u0441\u044C \u043D\u0430\u0431\u0440\u0430\u0442\u044C \u0431\u043E\u043B\u044C\u0448\u0443\u044E \u0441\u0443\u043C\u043C\u0443, \u0447\u0435\u043C \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A.",
              "\u041F\u0440\u043E\u0441\u043C\u0430\u0442\u0440\u0438\u0432\u0430\u0439\u0442\u0435 \u0440\u044F\u0434 \u0441\u0442\u0440\u0435\u043B\u043A\u0430\u043C\u0438. \u041A\u043B\u0430\u0432\u0438\u0448\u0438 1, 2 \u0438 3 \u0431\u0435\u0440\u0443\u0442 \u043E\u0434\u0438\u043D, \u0434\u0432\u0430 \u0438\u043B\u0438 \u0442\u0440\u0438 \u0448\u0430\u0440\u0430 \u0441 \u043D\u0430\u0447\u0430\u043B\u0430 \u0440\u044F\u0434\u0430. \u041D\u0430 \u0440\u0435\u0448\u0435\u043D\u0438\u0435 \u0435\u0441\u0442\u044C \u043C\u0438\u043D\u0443\u0442\u0430; \u0437\u0430\u0442\u0435\u043C \u0432\u044B \u0431\u0435\u0440\u0451\u0442\u0435 \u043E\u0434\u0438\u043D \u0448\u0430\u0440.",
              "\u041A\u043E\u0433\u0434\u0430 \u0432\u0441\u0435 \u0448\u0430\u0440\u044B \u0440\u0430\u0437\u043E\u0431\u0440\u0430\u043D\u044B, \u043F\u043E\u0431\u0435\u0436\u0434\u0430\u0435\u0442 \u0431\u043E\u043B\u044C\u0448\u0430\u044F \u0441\u0443\u043C\u043C\u0430. \u041F\u043E\u0431\u0435\u0434\u0438\u0442\u0435\u043B\u044C \u043F\u043E\u043B\u0443\u0447\u0430\u0435\u0442 \u0440\u0430\u0437\u043D\u0438\u0446\u0443 \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442\u043E\u0432 \u0432 \u043F\u0435\u0440\u044C\u044F\u0445, \u043D\u043E \u043D\u0435 \u0431\u043E\u043B\u044C\u0448\u0435 \u0434\u0435\u0441\u044F\u0442\u0438."),
            rule_section(:count_ducks, "\u041F\u043E\u0441\u0447\u0438\u0442\u0430\u0439\u0442\u0435 \u0443\u0442\u043E\u043A",
              "\u041F\u043E\u0441\u0447\u0438\u0442\u0430\u0439\u0442\u0435 \u043A\u0440\u044F\u043A\u0430\u043D\u044C\u044F, \u0430 \u043F\u043E\u0441\u043B\u0435 \u043E\u0431\u0440\u0430\u0442\u043D\u043E\u0433\u043E \u043E\u0442\u0441\u0447\u0451\u0442\u0430 \u0432\u0432\u0435\u0434\u0438\u0442\u0435 \u0438\u0445 \u0447\u0438\u0441\u043B\u043E. \u0412\u044B \u0443\u0441\u043B\u044B\u0448\u0438\u0442\u0435 \u043E\u0442 \u043F\u044F\u0442\u0438 \u0434\u043E \u043F\u044F\u0442\u043D\u0430\u0434\u0446\u0430\u0442\u0438 \u0437\u0432\u0443\u043A\u043E\u0432. \u041A\u043B\u0430\u0432\u0438\u0448\u0430 F5 \u043F\u043E\u0437\u0432\u043E\u043B\u044F\u0435\u0442 \u043F\u043E\u0441\u043B\u0443\u0448\u0430\u0442\u044C \u0438\u0445 \u0435\u0449\u0451 \u0440\u0430\u0437.",
              "\u041D\u0430 \u043E\u0442\u0432\u0435\u0442 \u0435\u0441\u0442\u044C \u0434\u0432\u0435 \u043F\u043E\u043F\u044B\u0442\u043A\u0438 \u0438 20 \u0441\u0435\u043A\u0443\u043D\u0434. \u041F\u0435\u0440\u0432\u044B\u0439 \u043F\u0440\u0430\u0432\u0438\u043B\u044C\u043D\u044B\u0439 \u043E\u0442\u0432\u0435\u0442 \u043F\u0440\u0438\u043D\u043E\u0441\u0438\u0442 \u043F\u043E \u0447\u0435\u0442\u044B\u0440\u0435 \u043F\u0435\u0440\u0430 \u043E\u0442 \u043A\u0430\u0436\u0434\u043E\u0433\u043E \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A\u0430."),
            rule_section(:rhythm, "\u041F\u043E\u0432\u0442\u043E\u0440\u0438\u0442\u0435 \u0440\u0438\u0442\u043C",
              "\u041F\u043E\u0432\u0442\u043E\u0440\u0438\u0442\u0435 \u0440\u0438\u0442\u043C \u043A\u043B\u0430\u0432\u0438\u0448\u0430\u043C\u0438 F \u0438 J. \u041F\u0435\u0440\u0435\u0434 \u043D\u0430\u0447\u0430\u043B\u043E\u043C \u043C\u043E\u0436\u043D\u043E \u043F\u043E\u043F\u0440\u043E\u0431\u043E\u0432\u0430\u0442\u044C \u043E\u0431\u0430 \u0437\u0432\u0443\u043A\u0430. \u041D\u0430\u0436\u043C\u0438\u0442\u0435 Enter \u0438\u043B\u0438 \u041F\u0440\u043E\u0431\u0435\u043B, \u0447\u0442\u043E\u0431\u044B \u043D\u0430\u0447\u0430\u0442\u044C \u0441\u0432\u043E\u044E \u043F\u043E\u043F\u044B\u0442\u043A\u0443. \u041F\u0440\u043E\u0437\u0432\u0443\u0447\u0438\u0442 \u043E\u0442 \u0448\u0435\u0441\u0442\u0438 \u0434\u043E \u0434\u0435\u0441\u044F\u0442\u0438 \u0443\u0434\u0430\u0440\u043E\u0432.",
              "\u041F\u043E\u0441\u043B\u0435 \u043F\u0440\u043E\u0441\u043B\u0443\u0448\u0438\u0432\u0430\u043D\u0438\u044F \u043D\u0430\u0436\u043C\u0438\u0442\u0435 Enter \u0438 \u0441\u044B\u0433\u0440\u0430\u0439\u0442\u0435 \u0440\u0438\u0442\u043C. \u041D\u0430 \u043D\u0430\u0447\u0430\u043B\u043E \u043F\u043E\u043F\u044B\u0442\u043A\u0438 \u0435\u0441\u0442\u044C 15 \u0441\u0435\u043A\u0443\u043D\u0434; \u0434\u043E \u044D\u0442\u043E\u0433\u043E \u043C\u043E\u0436\u043D\u043E \u0435\u0449\u0451 \u0440\u0430\u0437 \u043F\u043E\u0441\u043B\u0443\u0448\u0430\u0442\u044C \u043E\u0431\u0440\u0430\u0437\u0435\u0446 \u043A\u043B\u0430\u0432\u0438\u0448\u0435\u0439 F5. \u041F\u043E\u043F\u044B\u0442\u043A\u0430 \u043E\u0434\u043D\u0430, \u0438 \u0442\u0440\u0438 \u0441\u0435\u043A\u0443\u043D\u0434\u044B \u0431\u0435\u0437 \u0443\u0434\u0430\u0440\u0430 \u0435\u0451 \u0437\u0430\u0432\u0435\u0440\u0448\u0430\u044E\u0442.",
              "\u041F\u043E\u043B\u043E\u0432\u0438\u043D\u0430 \u043E\u0446\u0435\u043D\u043A\u0438 \u0437\u0430\u0432\u0438\u0441\u0438\u0442 \u043E\u0442 \u043F\u043E\u0440\u044F\u0434\u043A\u0430 \u0437\u0432\u0443\u043A\u043E\u0432, \u0434\u0440\u0443\u0433\u0430\u044F \u043F\u043E\u043B\u043E\u0432\u0438\u043D\u0430 \u2014 \u043E\u0442 \u043F\u0440\u043E\u043C\u0435\u0436\u0443\u0442\u043A\u043E\u0432 \u043C\u0435\u0436\u0434\u0443 \u043D\u0438\u043C\u0438. \u041F\u043E\u0431\u0435\u0436\u0434\u0430\u0435\u0442 \u0441\u0430\u043C\u043E\u0435 \u0442\u043E\u0447\u043D\u043E\u0435 \u043F\u043E\u0432\u0442\u043E\u0440\u0435\u043D\u0438\u0435. \u0417\u0430 \u043A\u0430\u0436\u0434\u044B\u0435 \u043F\u043E\u043B\u043D\u044B\u0435 \u0438\u043B\u0438 \u043D\u0435\u043F\u043E\u043B\u043D\u044B\u0435 \u0434\u0435\u0441\u044F\u0442\u044C \u043F\u0440\u043E\u0446\u0435\u043D\u0442\u043D\u044B\u0445 \u043F\u0443\u043D\u043A\u0442\u043E\u0432 \u043F\u0440\u0435\u0438\u043C\u0443\u0449\u0435\u0441\u0442\u0432\u0430 \u043F\u043E\u0431\u0435\u0434\u0438\u0442\u0435\u043B\u044C \u0437\u0430\u0431\u0438\u0440\u0430\u0435\u0442 \u0443 \u044D\u0442\u043E\u0433\u043E \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A\u0430 \u043E\u0434\u043D\u043E \u043F\u0435\u0440\u043E."),
            rule_section(:sound_order, "\u0420\u0430\u0441\u043F\u043E\u043B\u043E\u0436\u0438\u0442\u0435 \u0437\u0432\u0443\u043A\u0438 \u043F\u043E \u0432\u044B\u0441\u043E\u0442\u0435",
              "\u0421\u043E\u0431\u0435\u0440\u0438\u0442\u0435 \u0433\u0430\u043C\u043C\u0443 \u043E\u0442 \u0441\u0430\u043C\u043E\u0439 \u043D\u0438\u0437\u043A\u043E\u0439 \u043D\u043E\u0442\u044B \u043A \u0441\u0430\u043C\u043E\u0439 \u0432\u044B\u0441\u043E\u043A\u043E\u0439. \u041D\u0430\u0447\u0438\u043D\u0430\u0439\u0442\u0435 \u043F\u043E\u0441\u043B\u0435 \u043E\u0431\u0440\u0430\u0442\u043D\u043E\u0433\u043E \u043E\u0442\u0441\u0447\u0451\u0442\u0430. \u041A\u043B\u0430\u0432\u0438\u0448\u0438 \u043E\u0442 1 \u0434\u043E 8 \u0432\u043E\u0441\u043F\u0440\u043E\u0438\u0437\u0432\u043E\u0434\u044F\u0442 \u043D\u043E\u0442\u044B \u043D\u0430 \u0441\u043E\u043E\u0442\u0432\u0435\u0442\u0441\u0442\u0432\u0443\u044E\u0449\u0438\u0445 \u043C\u0435\u0441\u0442\u0430\u0445.",
              "\u0427\u0442\u043E\u0431\u044B \u043F\u043E\u043C\u0435\u043D\u044F\u0442\u044C \u0434\u0432\u0435 \u043D\u043E\u0442\u044B \u043C\u0435\u0441\u0442\u0430\u043C\u0438, \u043D\u0430\u0436\u043C\u0438\u0442\u0435 Shift \u0441 \u0446\u0438\u0444\u0440\u043E\u0439 \u043F\u0435\u0440\u0432\u043E\u0439 \u043F\u043E\u0437\u0438\u0446\u0438\u0438, \u0437\u0430\u0442\u0435\u043C Shift \u0441 \u0446\u0438\u0444\u0440\u043E\u0439 \u0432\u0442\u043E\u0440\u043E\u0439. \u041F\u043E\u0441\u043B\u0435 \u043F\u0435\u0440\u0435\u0441\u0442\u0430\u043D\u043E\u0432\u043A\u0438 \u0432\u044B \u0443\u0441\u043B\u044B\u0448\u0438\u0442\u0435 \u043E\u0431\u0435 \u043D\u043E\u0442\u044B.",
              "\u0423 \u0432\u0430\u0441 45 \u0441\u0435\u043A\u0443\u043D\u0434. \u041F\u043E\u0431\u0435\u0436\u0434\u0430\u0435\u0442 \u0442\u043E\u0442, \u043A\u0442\u043E \u043F\u0435\u0440\u0432\u044B\u043C \u0441\u043E\u0431\u0435\u0440\u0451\u0442 \u0432\u0441\u044E \u0433\u0430\u043C\u043C\u0443. \u041A\u0430\u0436\u0434\u044B\u0439 \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A \u043E\u0442\u0434\u0430\u0451\u0442 \u0435\u043C\u0443 \u043F\u043E \u043F\u0435\u0440\u0443 \u0437\u0430 \u043D\u043E\u0442\u0443 \u043D\u0435 \u043D\u0430 \u0441\u0432\u043E\u0451\u043C \u043C\u0435\u0441\u0442\u0435, \u043D\u043E \u043D\u0435 \u0431\u043E\u043B\u044C\u0448\u0435 \u043F\u044F\u0442\u0438. \u0415\u0441\u043B\u0438 \u043D\u0438\u043A\u0442\u043E \u043D\u0435 \u0441\u043F\u0440\u0430\u0432\u0438\u0442\u0441\u044F, \u043F\u043E\u0431\u0435\u0434\u0438\u0442\u0435\u043B\u044F \u043D\u0435\u0442."),
            rule_section(:simon, "\u0421\u0430\u0439\u043C\u043E\u043D",
              "\u0417\u0430\u043F\u043E\u043C\u0438\u043D\u0430\u0439\u0442\u0435 \u0432\u0441\u0451 \u0431\u043E\u043B\u0435\u0435 \u0434\u043B\u0438\u043D\u043D\u0443\u044E \u043C\u0435\u043B\u043E\u0434\u0438\u044E \u0438 \u043F\u043E\u0432\u0442\u043E\u0440\u044F\u0439\u0442\u0435 \u0435\u0451 \u0446\u0438\u0444\u0440\u0430\u043C\u0438 \u043E\u0442 1 \u0434\u043E 5. \u041F\u043E\u0434 \u0435\u0434\u0438\u043D\u0438\u0446\u0435\u0439 \u2014 \u0441\u0430\u043C\u044B\u0439 \u043D\u0438\u0437\u043A\u0438\u0439 \u0442\u043E\u043D, \u043F\u043E\u0434 \u043F\u044F\u0442\u0451\u0440\u043A\u043E\u0439 \u2014 \u0441\u0430\u043C\u044B\u0439 \u0432\u044B\u0441\u043E\u043A\u0438\u0439. \u041F\u0435\u0440\u0435\u0434 \u043D\u0430\u0447\u0430\u043B\u043E\u043C \u043C\u043E\u0436\u043D\u043E \u043F\u043E\u043F\u0440\u043E\u0431\u043E\u0432\u0430\u0442\u044C \u0437\u0432\u0443\u043A\u0438, \u0437\u0430\u0442\u0435\u043C \u043F\u043E\u0434\u0442\u0432\u0435\u0440\u0434\u0438\u0442\u044C \u0433\u043E\u0442\u043E\u0432\u043D\u043E\u0441\u0442\u044C \u043A\u043B\u0430\u0432\u0438\u0448\u0435\u0439 Enter \u0438\u043B\u0438 \u041F\u0440\u043E\u0431\u0435\u043B\u043E\u043C.",
              "\u0412\u0430\u0448\u0430 \u043F\u043E\u043F\u044B\u0442\u043A\u0430 \u043D\u0430\u0447\u0438\u043D\u0430\u0435\u0442\u0441\u044F \u0441 \u043E\u0434\u043D\u043E\u0439 \u043D\u043E\u0442\u044B, \u0431\u0435\u0437 \u043E\u0436\u0438\u0434\u0430\u043D\u0438\u044F \u043E\u0441\u0442\u0430\u043B\u044C\u043D\u044B\u0445 \u0438\u0433\u0440\u043E\u043A\u043E\u0432. \u041F\u043E\u0441\u043B\u0435 \u043A\u0430\u0436\u0434\u043E\u0433\u043E \u043F\u0440\u0430\u0432\u0438\u043B\u044C\u043D\u043E\u0433\u043E \u043E\u0442\u0432\u0435\u0442\u0430 \u0434\u043E\u0431\u0430\u0432\u043B\u044F\u0435\u0442\u0441\u044F \u0435\u0449\u0451 \u043E\u0434\u043D\u0430, \u0430 \u043C\u0435\u043B\u043E\u0434\u0438\u044F \u043D\u0435\u043C\u043D\u043E\u0433\u043E \u0443\u0441\u043A\u043E\u0440\u044F\u0435\u0442\u0441\u044F. \u041F\u043E\u0432\u0442\u043E\u0440\u044F\u0439\u0442\u0435 \u0435\u0451 \u043F\u043E\u0441\u043B\u0435 \u043E\u043A\u043E\u043D\u0447\u0430\u043D\u0438\u044F \u043F\u0440\u043E\u0441\u043B\u0443\u0448\u0438\u0432\u0430\u043D\u0438\u044F.",
              "\u0418\u0433\u0440\u0430\u0439\u0442\u0435 \u0434\u043E \u043F\u0435\u0440\u0432\u043E\u0439 \u043E\u0448\u0438\u0431\u043A\u0438 \u0438\u043B\u0438 \u043F\u044F\u0442\u0438 \u0441\u0435\u043A\u0443\u043D\u0434 \u0431\u0435\u0437 \u043D\u0430\u0436\u0430\u0442\u0438\u044F \u0432\u043E \u0432\u0440\u0435\u043C\u044F \u043E\u0442\u0432\u0435\u0442\u0430. \u041A\u0430\u0436\u0434\u044B\u0439 \u0437\u0430\u0432\u0435\u0440\u0448\u0430\u0435\u0442 \u0441\u0432\u043E\u044E \u043F\u043E\u043F\u044B\u0442\u043A\u0443. \u0421\u0447\u0438\u0442\u0430\u0435\u0442\u0441\u044F \u0441\u0430\u043C\u0430\u044F \u0434\u043B\u0438\u043D\u043D\u0430\u044F \u043C\u0435\u043B\u043E\u0434\u0438\u044F, \u043F\u043E\u0432\u0442\u043E\u0440\u0451\u043D\u043D\u0430\u044F \u0446\u0435\u043B\u0438\u043A\u043E\u043C; \u0437\u0430 \u043A\u0430\u0436\u0434\u0443\u044E \u043D\u043E\u0442\u0443 \u043F\u0440\u0435\u0438\u043C\u0443\u0449\u0435\u0441\u0442\u0432\u0430 \u043F\u043E\u0431\u0435\u0434\u0438\u0442\u0435\u043B\u044C \u0437\u0430\u0431\u0438\u0440\u0430\u0435\u0442 \u0443 \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A\u0430 \u043E\u0434\u043D\u043E \u043F\u0435\u0440\u043E."),
            rule_section(:sound_memory, "\u0417\u0432\u0443\u043A\u043E\u0432\u044B\u0435 \u043F\u0430\u0440\u044B",
              "\u041D\u0430\u0439\u0434\u0438\u0442\u0435 \u0431\u043E\u043B\u044C\u0448\u0435 \u043F\u0430\u0440, \u0447\u0435\u043C \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A. \u041F\u043E\u0434 \u0446\u0438\u0444\u0440\u0430\u043C\u0438 \u043E\u0442 1 \u0434\u043E 0 \u0441\u043A\u0440\u044B\u0442\u044B \u0434\u0435\u0441\u044F\u0442\u044C \u0437\u0432\u0443\u043A\u043E\u0432, \u0441\u043E\u0441\u0442\u0430\u0432\u043B\u044F\u044E\u0449\u0438\u0445 \u043F\u044F\u0442\u044C \u043F\u0430\u0440. \u041E\u0431\u0430 \u0438\u0433\u0440\u043E\u043A\u0430 \u043D\u0430\u0436\u0438\u043C\u0430\u044E\u0442 Enter, \u043A\u043E\u0433\u0434\u0430 \u0433\u043E\u0442\u043E\u0432\u044B.",
              "\u041F\u043E \u043E\u0447\u0435\u0440\u0435\u0434\u0438 \u043E\u0442\u043A\u0440\u044B\u0432\u0430\u0439\u0442\u0435 \u0434\u0432\u0430 \u043C\u0435\u0441\u0442\u0430, \u043D\u0430\u0436\u0438\u043C\u0430\u044F \u0438\u0445 \u0446\u0438\u0444\u0440\u044B. \u0421\u043B\u0443\u0448\u0430\u0439\u0442\u0435 \u0438 \u0432\u044B\u0431\u043E\u0440 \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A\u0430, \u0437\u0430\u043F\u043E\u043C\u0438\u043D\u0430\u044F \u0440\u0430\u0441\u043F\u043E\u043B\u043E\u0436\u0435\u043D\u0438\u0435 \u0437\u0432\u0443\u043A\u043E\u0432. \u0421\u043E\u0432\u043F\u0430\u0432\u0448\u0430\u044F \u043F\u0430\u0440\u0430 \u0438\u0441\u0447\u0435\u0437\u0430\u0435\u0442 \u0438 \u043F\u0440\u0438\u043D\u043E\u0441\u0438\u0442 \u043E\u0447\u043A\u043E, \u0430 \u0440\u0430\u0437\u043D\u044B\u0435 \u0437\u0432\u0443\u043A\u0438 \u0441\u043D\u043E\u0432\u0430 \u0441\u043A\u0440\u044B\u0432\u0430\u044E\u0442\u0441\u044F.",
              "\u041D\u0430 \u0445\u043E\u0434 \u0435\u0441\u0442\u044C 15 \u0441\u0435\u043A\u0443\u043D\u0434. \u0418\u0441\u043F\u044B\u0442\u0430\u043D\u0438\u0435 \u0437\u0430\u043A\u0430\u043D\u0447\u0438\u0432\u0430\u0435\u0442\u0441\u044F, \u043A\u043E\u0433\u0434\u0430 \u043D\u0430\u0439\u0434\u0435\u043D\u044B \u0432\u0441\u0435 \u043F\u0430\u0440\u044B \u0438\u043B\u0438 \u043F\u0440\u043E\u0448\u043B\u043E 90 \u0441\u0435\u043A\u0443\u043D\u0434. \u041F\u043E\u0431\u0435\u0434\u0438\u0442\u0435\u043B\u044C \u0437\u0430\u0431\u0438\u0440\u0430\u0435\u0442 \u0441\u0442\u043E\u043B\u044C\u043A\u043E \u043F\u0435\u0440\u044C\u0435\u0432, \u043D\u0430 \u0441\u043A\u043E\u043B\u044C\u043A\u043E \u043F\u0430\u0440 \u0443 \u043D\u0435\u0433\u043E \u0431\u043E\u043B\u044C\u0448\u0435."),
            rule_section(:hit_duck, "\u041F\u043E\u043F\u0430\u0434\u0438\u0442\u0435 \u0432 \u0443\u0442\u043A\u0443",
              "\u041E\u043F\u0440\u0435\u0434\u0435\u043B\u0438\u0442\u0435, \u043E\u0442\u043A\u0443\u0434\u0430 \u0434\u043E\u043D\u043E\u0441\u0438\u0442\u0441\u044F \u043A\u0440\u044F\u043A\u0430\u043D\u044C\u0435, \u0438 \u043D\u0430\u0436\u043C\u0438\u0442\u0435 \u043D\u0443\u0436\u043D\u0443\u044E \u0446\u0438\u0444\u0440\u0443 \u043E\u0442 1 \u0434\u043E 9. \u0415\u0434\u0438\u043D\u0438\u0446\u0430 \u2014 \u043A\u0440\u0430\u0439\u043D\u044F\u044F \u043B\u0435\u0432\u0430\u044F \u043F\u043E\u0437\u0438\u0446\u0438\u044F, \u043F\u044F\u0442\u0451\u0440\u043A\u0430 \u2014 \u0441\u0435\u0440\u0435\u0434\u0438\u043D\u0430, \u0434\u0435\u0432\u044F\u0442\u043A\u0430 \u2014 \u043A\u0440\u0430\u0439\u043D\u044F\u044F \u043F\u0440\u0430\u0432\u0430\u044F.",
              "\u041F\u0435\u0440\u0435\u0434 \u043D\u0430\u0447\u0430\u043B\u043E\u043C \u043C\u043E\u0436\u043D\u043E \u043F\u043E\u0441\u043B\u0443\u0448\u0430\u0442\u044C \u0432\u0441\u0435 \u043F\u043E\u0437\u0438\u0446\u0438\u0438. \u041D\u0430\u0436\u043C\u0438\u0442\u0435 Enter \u0438\u043B\u0438 \u041F\u0440\u043E\u0431\u0435\u043B, \u0447\u0442\u043E\u0431\u044B \u043D\u0430\u0447\u0430\u0442\u044C \u0441\u0432\u043E\u044E \u043F\u043E\u043F\u044B\u0442\u043A\u0443. \u041F\u043E\u0441\u043B\u0435\u0434\u043E\u0432\u0430\u0442\u0435\u043B\u044C\u043D\u043E \u043F\u043E\u044F\u0432\u044F\u0442\u0441\u044F \u043F\u044F\u0442\u044C \u0446\u0435\u043B\u0435\u0439; \u043D\u0430 \u043A\u0430\u0436\u0434\u0443\u044E \u0435\u0441\u0442\u044C \u0442\u0440\u0438 \u0441\u0435\u043A\u0443\u043D\u0434\u044B.",
              "\u041F\u043E\u0441\u043B\u0435 \u043A\u0430\u0436\u0434\u043E\u0433\u043E \u0432\u044B\u0441\u0442\u0440\u0435\u043B\u0430 \u0432\u044B \u0443\u0441\u043B\u044B\u0448\u0438\u0442\u0435 \u043A\u0440\u0430\u0442\u043A\u0443\u044E \u043E\u0446\u0435\u043D\u043A\u0443 \u043F\u043E\u043F\u0430\u0434\u0430\u043D\u0438\u044F, \u0430 \u043F\u043E\u0441\u043B\u0435 \u043D\u0435\u0431\u043E\u043B\u044C\u0448\u043E\u0439 \u043F\u0430\u0443\u0437\u044B \u043F\u043E\u044F\u0432\u0438\u0442\u0441\u044F \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0430\u044F \u0443\u0442\u043A\u0430.",
              "\u041E\u0446\u0435\u043D\u043A\u0430 \u0437\u0430\u0432\u0438\u0441\u0438\u0442 \u043E\u0442 \u0442\u043E\u0433\u043E, \u043D\u0430\u0441\u043A\u043E\u043B\u044C\u043A\u043E \u0431\u043B\u0438\u0437\u043A\u043E \u0432\u044B \u043F\u043E\u043F\u0430\u043B\u0438:",
              "- \u0422\u043E\u0447\u043D\u043E\u0435 \u043F\u043E\u043F\u0430\u0434\u0430\u043D\u0438\u0435: 100 %.",
              "- \u041E\u0448\u0438\u0431\u043A\u0430 \u043D\u0430 \u043E\u0434\u043D\u0443 \u043F\u043E\u0437\u0438\u0446\u0438\u044E: 75 %.",
              "- \u041D\u0430 \u0434\u0432\u0435 \u043F\u043E\u0437\u0438\u0446\u0438\u0438: 50 %.",
              "- \u041D\u0430 \u0442\u0440\u0438 \u043F\u043E\u0437\u0438\u0446\u0438\u0438: 25 %.",
              "- \u041E\u0441\u0442\u0430\u043B\u044C\u043D\u044B\u0435 \u0432\u044B\u0441\u0442\u0440\u0435\u043B\u044B: \u043D\u043E\u043B\u044C.",
              "\u041F\u043E\u0431\u0435\u0436\u0434\u0430\u0435\u0442 \u043D\u0430\u0438\u0431\u043E\u043B\u044C\u0448\u0438\u0439 \u0441\u0440\u0435\u0434\u043D\u0438\u0439 \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442 \u043F\u044F\u0442\u0438 \u0432\u044B\u0441\u0442\u0440\u0435\u043B\u043E\u0432. \u0417\u0430 \u043A\u0430\u0436\u0434\u044B\u0435 \u043F\u043E\u043B\u043D\u044B\u0435 \u0438\u043B\u0438 \u043D\u0435\u043F\u043E\u043B\u043D\u044B\u0435 \u0434\u0435\u0441\u044F\u0442\u044C \u043F\u0440\u043E\u0446\u0435\u043D\u0442\u043D\u044B\u0445 \u043F\u0443\u043D\u043A\u0442\u043E\u0432 \u043F\u0440\u0435\u0438\u043C\u0443\u0449\u0435\u0441\u0442\u0432\u0430 \u043F\u043E\u0431\u0435\u0434\u0438\u0442\u0435\u043B\u044C \u0437\u0430\u0431\u0438\u0440\u0430\u0435\u0442 \u0443 \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A\u0430 \u043E\u0434\u043D\u043E \u043F\u0435\u0440\u043E."),
            rule_section(:quiz, "\u0412\u043E\u043F\u0440\u043E\u0441 \u0432\u0438\u043A\u0442\u043E\u0440\u0438\u043D\u044B",
              "\u041E\u0442\u0432\u0435\u0442\u044C\u0442\u0435 \u043D\u0430 \u0432\u043E\u043F\u0440\u043E\u0441, \u0432\u044B\u0431\u0440\u0430\u0432 \u043E\u0434\u0438\u043D \u0438\u0437 \u0447\u0435\u0442\u044B\u0440\u0451\u0445 \u0432\u0430\u0440\u0438\u0430\u043D\u0442\u043E\u0432 \u0446\u0438\u0444\u0440\u043E\u0439 \u043E\u0442 1 \u0434\u043E 4. \u041C\u043E\u0436\u043D\u043E \u0442\u0430\u043A\u0436\u0435 \u0432\u044B\u0431\u0440\u0430\u0442\u044C \u043E\u0442\u0432\u0435\u0442 \u0441\u0442\u0440\u0435\u043B\u043A\u0430\u043C\u0438 \u0438 \u043D\u0430\u0436\u0430\u0442\u044C Enter. \u0423 \u0432\u0430\u0441 20 \u0441\u0435\u043A\u0443\u043D\u0434.",
              "\u041A\u0430\u0436\u0434\u044B\u0439 \u043E\u0442\u0432\u0435\u0442\u0438\u0432\u0448\u0438\u0439 \u043F\u0440\u0430\u0432\u0438\u043B\u044C\u043D\u043E \u043F\u043E\u043B\u0443\u0447\u0430\u0435\u0442 \u0447\u0435\u0442\u044B\u0440\u0435 \u043F\u0435\u0440\u0430 \u043E\u0442 \u0438\u0433\u0440\u044B. \u0420\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442\u044B \u043E\u0431\u044A\u044F\u0432\u043B\u044F\u044E\u0442\u0441\u044F, \u043A\u043E\u0433\u0434\u0430 \u043E\u0442\u0432\u0435\u0442\u044F\u0442 \u0432\u0441\u0435 \u0438\u043B\u0438 \u0437\u0430\u043A\u043E\u043D\u0447\u0438\u0442\u0441\u044F \u0432\u0440\u0435\u043C\u044F.",
              "\u041D\u0430 \u0432\u043E\u043F\u0440\u043E\u0441 \u0432 \u043F\u043E\u0435\u0434\u0438\u043D\u043A\u0435 \u043E\u0442\u0432\u0435\u0447\u0430\u044E\u0442 \u0435\u0433\u043E \u0443\u0447\u0430\u0441\u0442\u043D\u0438\u043A\u0438. \u0412\u043E\u043F\u0440\u043E\u0441 \u0441 \u043A\u043B\u0435\u0442\u043A\u0438 \u0438\u043B\u0438 \u043A\u0430\u0440\u0442\u044B \u041B\u044E\u0431\u043E\u043F\u044B\u0442\u0441\u0442\u0432\u043E \u043F\u0440\u0435\u0434\u043D\u0430\u0437\u043D\u0430\u0447\u0435\u043D \u0432\u0441\u0435\u043C, \u0432\u043A\u043B\u044E\u0447\u0430\u044F \u0437\u0430\u043C\u0451\u0440\u0437\u0448\u0438\u0445 \u0443\u0442\u043E\u043A."),
            rule_section(:audio_ball, "\u041E\u0434\u0438\u043D \u0440\u043E\u0437\u044B\u0433\u0440\u044B\u0448 \u0432 Audio Ball",
              "\u0421\u044B\u0433\u0440\u0430\u0439\u0442\u0435 \u0434\u043E \u043E\u0434\u043D\u043E\u0433\u043E \u043E\u0447\u043A\u0430 \u043D\u0430 \u043E\u0431\u044B\u0447\u043D\u043E\u0439 \u0441\u043B\u043E\u0436\u043D\u043E\u0441\u0442\u0438. \u041F\u0435\u0440\u0432\u044B\u0439 \u043F\u043E\u0434\u0430\u044E\u0449\u0438\u0439 \u043E\u043F\u0440\u0435\u0434\u0435\u043B\u044F\u0435\u0442\u0441\u044F \u0441\u043B\u0443\u0447\u0430\u0439\u043D\u043E, \u0430 \u043F\u043E\u0431\u0435\u0434\u0438\u0442\u0435\u043B\u044C \u0437\u0430\u0431\u0438\u0440\u0430\u0435\u0442 \u0443 \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A\u0430 \u043F\u044F\u0442\u044C \u043F\u0435\u0440\u044C\u0435\u0432.",
              "\u041F\u0435\u0440\u0435\u0434 \u043D\u0430\u0447\u0430\u043B\u043E\u043C \u043F\u043E\u0441\u043B\u0443\u0448\u0430\u0439\u0442\u0435 \u0442\u0440\u0438 \u0432\u0438\u0434\u0430 \u043C\u044F\u0447\u0430:",
              "- W \u0438\u043B\u0438 \u0421\u0442\u0440\u0435\u043B\u043A\u0430 \u0432\u0432\u0435\u0440\u0445: \u043F\u0435\u0440\u0432\u044B\u0439 \u0432\u0438\u0434.",
              "- D \u0438\u043B\u0438 \u0421\u0442\u0440\u0435\u043B\u043A\u0430 \u0432\u043B\u0435\u0432\u043E: \u0432\u0442\u043E\u0440\u043E\u0439 \u0432\u0438\u0434.",
              "- S \u0438\u043B\u0438 \u0421\u0442\u0440\u0435\u043B\u043A\u0430 \u0432\u043D\u0438\u0437: \u0442\u0440\u0435\u0442\u0438\u0439 \u0432\u0438\u0434.",
              "\u041E\u0431\u0430 \u0438\u0433\u0440\u043E\u043A\u0430 \u043F\u043E\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0430\u044E\u0442 \u0433\u043E\u0442\u043E\u0432\u043D\u043E\u0441\u0442\u044C \u043A\u043B\u0430\u0432\u0438\u0448\u0435\u0439 Enter \u0438\u043B\u0438 \u041F\u0440\u043E\u0431\u0435\u043B\u043E\u043C. \u041F\u043E\u043B\u0443\u0447\u0438\u0432 \u043C\u044F\u0447, \u043F\u043E\u0434\u0433\u043E\u0442\u043E\u0432\u044C\u0442\u0435 \u0443\u0434\u0430\u0440 \u043A\u043B\u0430\u0432\u0438\u0448\u0435\u0439 A \u0438\u043B\u0438 \u0421\u0442\u0440\u0435\u043B\u043A\u043E\u0439 \u0432\u043F\u0440\u0430\u0432\u043E, \u0437\u0430\u0442\u0435\u043C \u043E\u0442\u043F\u0440\u0430\u0432\u044C\u0442\u0435 \u0435\u0433\u043E \u043E\u0434\u043D\u043E\u0439 \u0438\u0437 \u0442\u0440\u0451\u0445 \u043A\u043B\u0430\u0432\u0438\u0448.",
              "\u041F\u043E\u0441\u043B\u0435 \u043A\u0430\u0436\u0434\u043E\u0433\u043E \u0443\u0434\u0430\u0440\u0430 \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A\u0430 \u043E\u043F\u0440\u0435\u0434\u0435\u043B\u0438\u0442\u0435 \u0442\u0438\u043F \u043C\u044F\u0447\u0430 \u043F\u043E \u0437\u0432\u0443\u043A\u0443 \u0438 \u043D\u0430\u0436\u043C\u0438\u0442\u0435 \u0441\u043E\u043E\u0442\u0432\u0435\u0442\u0441\u0442\u0432\u0443\u044E\u0449\u0443\u044E \u043A\u043B\u0430\u0432\u0438\u0448\u0443 \u0437\u0430\u0449\u0438\u0442\u044B. \u041E\u0441\u0442\u0430\u043D\u043E\u0432\u0438\u0432 \u043C\u044F\u0447, \u043F\u043E\u0434\u0433\u043E\u0442\u043E\u0432\u044C\u0442\u0435 \u0441\u0432\u043E\u0439 \u0443\u0434\u0430\u0440. \u0421 \u043A\u0430\u0436\u0434\u044B\u043C \u043E\u0442\u0431\u0438\u0432\u0430\u043D\u0438\u0435\u043C \u043C\u044F\u0447 \u0443\u0441\u043A\u043E\u0440\u044F\u0435\u0442\u0441\u044F."),
            rule_section(:axel_pong, "\u041E\u0434\u0438\u043D \u0440\u043E\u0437\u044B\u0433\u0440\u044B\u0448 \u0432 Axel Pong",
              "\u0421\u044B\u0433\u0440\u0430\u0439\u0442\u0435 \u043E\u0434\u0438\u043D \u0440\u043E\u0437\u044B\u0433\u0440\u044B\u0448 \u043E\u0434\u0438\u043D \u043D\u0430 \u043E\u0434\u0438\u043D \u0432 \u0440\u0435\u0436\u0438\u043C\u0435 Classic \u043D\u0430 \u043E\u0431\u044B\u0447\u043D\u043E\u0439 \u0441\u043A\u043E\u0440\u043E\u0441\u0442\u0438. \u041F\u0435\u0440\u0432\u044B\u0439 \u043F\u043E\u0434\u0430\u044E\u0449\u0438\u0439 \u043E\u043F\u0440\u0435\u0434\u0435\u043B\u044F\u0435\u0442\u0441\u044F \u0441\u043B\u0443\u0447\u0430\u0439\u043D\u043E. \u041F\u043E\u0431\u0435\u0434\u0438\u0442\u0435\u043B\u044C \u0437\u0430\u0431\u0438\u0440\u0430\u0435\u0442 \u0443 \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A\u0430 \u043F\u044F\u0442\u044C \u043F\u0435\u0440\u044C\u0435\u0432.",
              "\u041D\u0430\u0436\u043C\u0438\u0442\u0435 Enter, \u043A\u043E\u0433\u0434\u0430 \u0431\u0443\u0434\u0435\u0442\u0435 \u0433\u043E\u0442\u043E\u0432\u044B. \u0418\u0433\u0440\u0430 \u043D\u0430\u0447\u043D\u0451\u0442\u0441\u044F \u043F\u043E\u0441\u043B\u0435 \u043F\u043E\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0435\u043D\u0438\u044F \u043E\u0431\u043E\u0438\u0445 \u0438\u0433\u0440\u043E\u043A\u043E\u0432.",
              "\u041F\u0435\u0440\u0435\u0434\u0432\u0438\u0433\u0430\u0439\u0442\u0435 \u0440\u0430\u043A\u0435\u0442\u043A\u0443 \u0441\u0442\u0440\u0435\u043B\u043A\u0430\u043C\u0438 \u0432\u043B\u0435\u0432\u043E \u0438 \u0432\u043F\u0440\u0430\u0432\u043E. \u041F\u043E\u0434\u0430\u0432\u0430\u0439\u0442\u0435 \u0421\u0442\u0440\u0435\u043B\u043A\u043E\u0439 \u0432\u0432\u0435\u0440\u0445 \u0438\u043B\u0438 \u041F\u0440\u043E\u0431\u0435\u043B\u043E\u043C. \u041A\u043E\u0433\u0434\u0430 \u043C\u044F\u0447 \u0432\u0435\u0440\u043D\u0451\u0442\u0441\u044F, \u043F\u043E\u0441\u0442\u0430\u0432\u044C\u0442\u0435 \u0440\u0430\u043A\u0435\u0442\u043A\u0443 \u043D\u0430 \u0435\u0433\u043E \u043F\u0443\u0442\u0438 \u0438 \u043D\u0430\u0436\u043C\u0438\u0442\u0435 \u0442\u0443 \u0436\u0435 \u043A\u043B\u0430\u0432\u0438\u0448\u0443, \u043A\u043E\u0433\u0434\u0430 \u043E\u043D \u043E\u043A\u0430\u0436\u0435\u0442\u0441\u044F \u0432 \u043F\u0440\u0435\u0434\u0435\u043B\u0430\u0445 \u0434\u043E\u0441\u044F\u0433\u0430\u0435\u043C\u043E\u0441\u0442\u0438.",
              "\u0415\u0441\u043B\u0438 \u0432\u043A\u043B\u044E\u0447\u0435\u043D\u043E \u0430\u0432\u0442\u043E\u043C\u0430\u0442\u0438\u0447\u0435\u0441\u043A\u043E\u0435 \u043E\u0442\u0431\u0438\u0432\u0430\u043D\u0438\u0435, \u043F\u0440\u0438 \u0437\u0430\u0449\u0438\u0442\u0435 \u0434\u043E\u0441\u0442\u0430\u0442\u043E\u0447\u043D\u043E \u043F\u0440\u0430\u0432\u0438\u043B\u044C\u043D\u043E \u043F\u043E\u0441\u0442\u0430\u0432\u0438\u0442\u044C \u0440\u0430\u043A\u0435\u0442\u043A\u0443. \u041F\u043E\u0434\u0430\u0447\u0443 \u0432\u044B \u0432\u044B\u043F\u043E\u043B\u043D\u044F\u0435\u0442\u0435 \u0441\u0430\u043C\u0438."),
            rule_section(:settings, "\u041D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0438 \u0433\u043E\u043D\u043A\u0438",
              "\u041F\u0435\u0440\u0435\u0434 \u0433\u043E\u043D\u043A\u043E\u0439 \u0445\u043E\u0437\u044F\u0438\u043D \u0441\u0442\u043E\u043B\u0430 \u0432\u044B\u0431\u0438\u0440\u0430\u0435\u0442 \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0438:",
              "- \u041A\u0440\u0443\u0433\u0438: \u043E\u0442 \u043E\u0434\u043D\u043E\u0433\u043E \u0434\u043E \u0434\u0435\u0441\u044F\u0442\u0438, \u043F\u043E \u0443\u043C\u043E\u043B\u0447\u0430\u043D\u0438\u044E \u0442\u0440\u0438.",
              "- \u0418\u0441\u043F\u044B\u0442\u0430\u043D\u0438\u044F: \u043E\u0442\u043C\u0435\u0442\u044C\u0442\u0435 \u0442\u0435, \u0432 \u043A\u043E\u0442\u043E\u0440\u044B\u0435 \u0445\u043E\u0442\u0438\u0442\u0435 \u0438\u0433\u0440\u0430\u0442\u044C. \u0418\u0437\u043D\u0430\u0447\u0430\u043B\u044C\u043D\u043E \u0432\u043A\u043B\u044E\u0447\u0435\u043D\u044B \u0432\u0441\u0435. \u041E\u0441\u0442\u0430\u0432\u044C\u0442\u0435 \u0445\u043E\u0442\u044F \u0431\u044B \u043E\u0434\u043D\u043E \u0434\u043B\u044F \u043F\u043E\u0435\u0434\u0438\u043D\u043A\u043E\u0432 \u0438 \u043E\u0434\u043D\u043E \u0434\u043B\u044F \u0433\u0440\u0443\u043F\u043F\u044B.",
              "- \u0412\u043E\u043F\u0440\u043E\u0441\u044B: \u0432\u044B\u0431\u0435\u0440\u0438\u0442\u0435 \u044F\u0437\u044B\u043A \u0438 \u043D\u0430\u0431\u043E\u0440\u044B. \u041F\u043E \u0443\u043C\u043E\u043B\u0447\u0430\u043D\u0438\u044E \u043E\u0442\u043C\u0435\u0447\u0435\u043D \u043E\u0431\u0449\u0438\u0439 \u043D\u0430\u0431\u043E\u0440. \u0423 \u0432\u044B\u0431\u0440\u0430\u043D\u043D\u044B\u0445 \u043D\u0430\u0431\u043E\u0440\u043E\u0432 \u0440\u0430\u0432\u043D\u044B\u0435 \u0448\u0430\u043D\u0441\u044B \u0432\u044B\u043F\u0430\u0434\u0435\u043D\u0438\u044F; \u043E\u043D\u0438 \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u0443\u044E\u0442\u0441\u044F \u0434\u043B\u044F \u0432\u0441\u0435\u0445 \u0432\u043E\u043F\u0440\u043E\u0441\u043E\u0432 \u0432 \u0433\u043E\u043D\u043A\u0435."),
            rule_section(:interruptions, "\u0421\u043E\u0445\u0440\u0430\u043D\u0435\u043D\u0438\u0435 \u0438 \u043F\u0440\u0435\u0440\u0432\u0430\u043D\u043D\u044B\u0435 \u0438\u0441\u043F\u044B\u0442\u0430\u043D\u0438\u044F",
              "\u0413\u043E\u043D\u043A\u0443 \u043C\u043E\u0436\u043D\u043E \u0441\u043E\u0445\u0440\u0430\u043D\u0438\u0442\u044C \u043C\u0435\u0436\u0434\u0443 \u0445\u043E\u0434\u0430\u043C\u0438, \u043A\u043E\u0433\u0434\u0430 \u0437\u0430\u0432\u0435\u0440\u0448\u0438\u043B\u0438\u0441\u044C \u0438\u0441\u043F\u044B\u0442\u0430\u043D\u0438\u0435 \u0438 \u043E\u0441\u0442\u0430\u043B\u044C\u043D\u044B\u0435 \u0441\u043E\u0431\u044B\u0442\u0438\u044F, \u0432\u044B\u0437\u0432\u0430\u043D\u043D\u044B\u0435 \u043F\u0435\u0440\u0435\u043C\u0435\u0449\u0435\u043D\u0438\u0435\u043C.",
              "\u0415\u0441\u043B\u0438 \u0443\u0447\u0430\u0441\u0442\u043D\u0438\u043A \u0438\u0441\u043F\u044B\u0442\u0430\u043D\u0438\u044F \u043F\u043E\u043A\u0438\u0434\u0430\u0435\u0442 \u0441\u0442\u043E\u043B \u0438\u043B\u0438 \u0435\u0433\u043E \u0437\u0430\u043C\u0435\u043D\u044F\u044E\u0442, \u0438\u0441\u043F\u044B\u0442\u0430\u043D\u0438\u0435 \u043E\u0442\u043C\u0435\u043D\u044F\u0435\u0442\u0441\u044F \u0431\u0435\u0437 \u043F\u043E\u0442\u0435\u0440\u0438 \u043F\u0435\u0440\u044C\u0435\u0432."),
            rule_section(:question_reports, "\u041E\u0448\u0438\u0431\u043A\u0438 \u0432 \u0432\u043E\u043F\u0440\u043E\u0441\u0430\u0445",
              "Ctrl+B \u043E\u0442\u043C\u0435\u0447\u0430\u0435\u0442 \u0442\u0435\u043A\u0443\u0449\u0438\u0439 \u0432\u043E\u043F\u0440\u043E\u0441 \u0434\u043B\u044F \u0441\u043E\u043E\u0431\u0449\u0435\u043D\u0438\u044F \u043E\u0431 \u043E\u0448\u0438\u0431\u043A\u0435, \u0430 Ctrl+Shift+B \u2014 \u043F\u0440\u0435\u0434\u044B\u0434\u0443\u0449\u0438\u0439. \u042D\u0442\u043E \u0440\u0430\u0431\u043E\u0442\u0430\u0435\u0442 \u0441 \u0432\u043E\u043F\u0440\u043E\u0441\u0430\u043C\u0438 \u0438\u0437 \u043A\u043B\u0435\u0442\u043E\u043A, \u043A\u0430\u0440\u0442 \u0438 \u0438\u0441\u043F\u044B\u0442\u0430\u043D\u0438\u0439. \u041F\u0440\u0438 \u0432\u044B\u0445\u043E\u0434\u0435 \u0438\u0437-\u0437\u0430 \u0441\u0442\u043E\u043B\u0430 \u0432\u044B\u0431\u0435\u0440\u0438\u0442\u0435 \u00AB\u0414\u0430\u00BB, \u043A\u043E\u0433\u0434\u0430 \u043F\u0440\u043E\u0433\u0440\u0430\u043C\u043C\u0430 \u043F\u0440\u0435\u0434\u043B\u043E\u0436\u0438\u0442 \u043E\u0442\u043F\u0440\u0430\u0432\u0438\u0442\u044C \u0441\u043E\u043E\u0431\u0449\u0435\u043D\u0438\u044F, \u043E\u043F\u0438\u0448\u0438\u0442\u0435 \u043F\u0440\u043E\u0431\u043B\u0435\u043C\u0443 \u0438 \u043D\u0430\u0436\u043C\u0438\u0442\u0435 \u00AB\u041E\u0442\u043F\u0440\u0430\u0432\u0438\u0442\u044C\u00BB. \u0412 \u0444\u043E\u0440\u043C\u0435 \u043F\u043E\u043A\u0430\u0437\u0430\u043D\u044B \u0432\u043E\u043F\u0440\u043E\u0441, \u0432\u0430\u0440\u0438\u0430\u043D\u0442\u044B \u0438 \u043E\u0442\u0432\u0435\u0442, \u043E\u0442\u043C\u0435\u0447\u0435\u043D\u043D\u044B\u0439 \u0432 \u043D\u0430\u0431\u043E\u0440\u0435 \u043A\u0430\u043A \u043F\u0440\u0430\u0432\u0438\u043B\u044C\u043D\u044B\u0439."),
            rule_section(:controls, "\u041A\u043B\u0430\u0432\u0438\u0448\u0438 \u0433\u043E\u043D\u043A\u0438",
              "\u0421\u0442\u0440\u0435\u043B\u043A\u0438: \u0432\u044B\u0431\u0440\u0430\u0442\u044C \u043A\u0430\u0440\u0442\u0443 \u0438\u043B\u0438 \u0431\u0440\u043E\u0441\u043E\u043A \u0432 \u043A\u043E\u043D\u0446\u0435 \u0441\u043F\u0438\u0441\u043A\u0430.",
              "Enter: \u0441\u044B\u0433\u0440\u0430\u0442\u044C \u0432\u044B\u0431\u0440\u0430\u043D\u043D\u0443\u044E \u043A\u0430\u0440\u0442\u0443 \u0438\u043B\u0438 \u0431\u0440\u043E\u0441\u0438\u0442\u044C \u043A\u0443\u0431\u0438\u043A.",
              "\u041F\u0440\u043E\u0431\u0435\u043B: \u0431\u0440\u043E\u0441\u0438\u0442\u044C \u043A\u0443\u0431\u0438\u043A.",
              "D: \u043E\u043F\u0438\u0441\u0430\u043D\u0438\u0435 \u0432\u044B\u0431\u0440\u0430\u043D\u043D\u043E\u0439 \u043A\u0430\u0440\u0442\u044B.",
              "C: \u0432\u0430\u0448\u0430 \u043F\u043E\u0437\u0438\u0446\u0438\u044F, \u043F\u0435\u0440\u044C\u044F \u0438 \u0434\u0435\u0439\u0441\u0442\u0432\u0443\u044E\u0449\u0438\u0435 \u044D\u0444\u0444\u0435\u043A\u0442\u044B.",
              "S: \u043F\u043E\u043B\u043E\u0436\u0435\u043D\u0438\u0435 \u0432\u0441\u0435\u0445 \u0438\u0433\u0440\u043E\u043A\u043E\u0432.",
              "T: \u0442\u0435\u043A\u0443\u0449\u0438\u0439 \u0445\u043E\u0434 \u0438\u043B\u0438 \u0438\u0441\u043F\u044B\u0442\u0430\u043D\u0438\u0435.",
              "V: \u043F\u0440\u043E\u0441\u043C\u043E\u0442\u0440 \u0442\u0440\u0430\u0441\u0441\u044B, \u043D\u0430\u0447\u0438\u043D\u0430\u044F \u0441 \u0432\u0430\u0448\u0435\u0439 \u043A\u043B\u0435\u0442\u043A\u0438.",
              "P: \u043F\u043E\u0432\u0442\u043E\u0440\u0438\u0442\u044C \u0437\u0430\u0434\u0430\u043D\u0438\u0435 \u0438\u0441\u043F\u044B\u0442\u0430\u043D\u0438\u044F.",
              "Ctrl+B: \u043E\u0442\u043C\u0435\u0442\u0438\u0442\u044C \u0442\u0435\u043A\u0443\u0449\u0438\u0439 \u0432\u043E\u043F\u0440\u043E\u0441 \u0434\u043B\u044F \u0441\u043E\u043E\u0431\u0449\u0435\u043D\u0438\u044F \u043E\u0431 \u043E\u0448\u0438\u0431\u043A\u0435.",
              "Ctrl+Shift+B: \u043E\u0442\u043C\u0435\u0442\u0438\u0442\u044C \u043F\u0440\u0435\u0434\u044B\u0434\u0443\u0449\u0438\u0439 \u0432\u043E\u043F\u0440\u043E\u0441 \u0434\u043B\u044F \u0441\u043E\u043E\u0431\u0449\u0435\u043D\u0438\u044F \u043E\u0431 \u043E\u0448\u0438\u0431\u043A\u0435.")
          ]
        end
      end
